// Bank soal TKP (Tes Karakteristik Pribadi) SKD CPNS/kedinasan: situasional, skor 1-5 per opsi (latihan orisinal).
// ans = indeks opsi paling ideal (bernilai 5). Panjang opsi sengaja diseimbangkan: panjang bukan petunjuk jawaban.
window.BANK = window.BANK || {};
window.BANK["cpns-tkp"] = [
  { id: "tkp-pel-001", topik: "TKP Pelayanan Publik", level: 1, q: "Seorang warga marah-marah di loket karena antrean terasa sangat lama. Sikap Anda...", opts: ["Menyarankan warga mengisi kotak saran jika merasa tidak puas, karena keluhan lisan tidak bisa langsung diproses", "Mendengarkan keluhannya sampai selesai, meminta maaf atas ketidaknyamanan, lalu menjelaskan perkiraan waktunya", "Meminta warga duduk dan bersabar sambil tetap melayani nomor antrean yang sedang dipanggil saat ini", "Menjawab dengan nada tinggi supaya warga berhenti marah dan tidak mengganggu warga lain yang sedang antre", "Menunjukkan papan prosedur layanan dan mempersilakan warga membaca sendiri alur yang berlaku di sini"], ans: 1, skor: [2, 5, 4, 1, 3], bahas: "Antrean yang adil dan komunikasi yang santun menenangkan warga; membalas dengan emosi merusak citra layanan." },
  { id: "tkp-pel-002", topik: "TKP Pelayanan Publik", level: 1, q: "Berkas seorang pemohon kurang satu dokumen pendukung. Anda...", opts: ["Mengembalikan berkas dan menyuruh pemohon menanyakan syarat lengkapnya ke petugas di meja informasi depan", "Menerima berkas yang ada dan menjelaskan bahwa sisanya boleh menyusul sebelum batas waktu yang ditentukan", "Menunggu sampai pemohon menyadari sendiri bahwa berkasnya belum lengkap lalu memintanya mengulang dari awal", "Menyebutkan dokumen yang kurang dan memberi daftar syarat lengkapnya", "Menerima berkas begitu saja dengan harapan kekurangannya tidak terlihat oleh petugas pada tahap berikutnya"], ans: 3, skor: [3, 4, 2, 5, 1], bahas: "Pemohon harus tahu persis apa yang kurang; menerima berkas tidak lengkap menyalahi prosedur." },
  { id: "tkp-pel-003", topik: "TKP Pelayanan Publik", level: 1, q: "Saat jam istirahat, seorang lansia datang dan membutuhkan layanan. Anda...", opts: ["Menyarankan keluarganya datang menggantikan besok pagi, sebab Anda tidak ingin jam istirahat terganggu", "Memanggil rekan yang masih bertugas agar melayaninya dengan baik sambil Anda menemani lansia itu", "Mempersilakannya duduk lalu melayani atau memastikan petugas piket segera melayaninya dengan baik", "Menunjuk papan jam layanan dan menjelaskan bahwa loket baru dibuka satu jam lagi, karena aturan memang begitu", "Meminta lansia itu menunggu di ruang tunggu sampai jam istirahat selesai tepat pada waktunya"], ans: 2, skor: [1, 4, 5, 2, 3], bahas: "Kelompok rentan perlu dibantu, dan layanan tetap dijamin lewat petugas piket." },
  { id: "tkp-pel-004", topik: "TKP Pelayanan Publik", level: 2, q: "Anda menyadari salah menginput data seorang warga setelah warga itu pulang. Anda...", opts: ["Meminta rekan memperbaikinya diam-diam supaya kesalahan ini tidak tercatat atas nama Anda di laporan bulanan", "Segera memperbaiki sesuai prosedur koreksi, menghubungi warga, dan melapor kepada atasan", "Menunggu warga datang kembali atau komplain lebih dulu sebelum melakukan perbaikan yang diperlukan", "Menghapus catatan kesalahan itu agar atasan tidak mengetahui adanya kekeliruan input pada data warga tersebut", "Memperbaiki data sendiri lalu menyampaikannya kepada atasan setelah warga sempat dihubungi kembali"], ans: 1, skor: [2, 5, 3, 1, 4], bahas: "Kesalahan diakui, diperbaiki sesuai prosedur, dan dilaporkan secara transparan." },
  { id: "tkp-pel-005", topik: "TKP Pelayanan Publik", level: 1, q: "Seorang warga bertanya tentang layanan yang bukan wewenang unit Anda. Anda...", opts: ["Menyuruh warga mencari sendiri informasinya di internet tanpa memberi arahan apa pun kepadanya", "Menjawab seadanya berdasarkan dugaan karena merasa tidak enak bila warga pulang dengan tangan kosong", "Menunjukkan unit yang berwenang, menjelaskan alurnya, dan bila perlu mengantarnya ke sana", "Mengatakan bahwa hal itu bukan urusan unit Anda lalu melanjutkan pekerjaan di meja seperti tadi", "Menuliskan nama unit dan lokasinya di kertas lalu mempersilakan warga menuju ke sana sendiri"], ans: 2, skor: [1, 3, 5, 2, 4], bahas: "Melayani tidak berhenti di batas wewenang; warga harus mendapat arahan yang benar." },
  { id: "tkp-pel-006", topik: "TKP Pelayanan Publik", level: 2, q: "Seorang teman meminta Anda melayani lebih cepat dengan menawarkan imbalan uang. Anda...", opts: ["Mengatakan akan mempertimbangkannya dulu sambil menunggu waktu yang lebih tepat untuk menjawab", "Menolak dengan sopan, menjelaskan layanan gratis dan berurutan, serta melapor bila perlu", "Menerima imbalan dan melayani lebih dulu karena sama-sama diuntungkan oleh kesepakatan kecil ini saja", "Menerima uang itu sebagai tanda terima kasih karena hanya diminta sekali dan jumlahnya tidak besar", "Menolak tawaran itu dan tetap melayani sesuai urutan tanpa membahas soal imbalan lebih jauh"], ans: 1, skor: [3, 5, 1, 2, 4], bahas: "Gratifikasi harus ditolak tegas namun santun, dan dilaporkan bila berulang." },
  { id: "tkp-pel-007", topik: "TKP Pelayanan Publik", level: 2, q: "Sistem layanan sedang gangguan dan antrean warga memanjang. Anda...", opts: ["Menyalahkan bagian teknis di depan warga supaya mereka tahu bahwa gangguan ini bukan kesalahan Anda", "Menyarankan warga datang lagi besok tanpa memberi kepastian kapan sistem akan kembali normal", "Menyampaikan kondisi secara terbuka, menawarkan jalur alternatif seperti formulir manual, dan memperbarui informasi", "Meminta warga menunggu sambil terus mengecek apakah sistem sudah pulih lalu memberi kabar terbaru", "Menutup loket dan menempelkan pengumuman singkat tanpa penjelasan lanjutan, karena Anda tidak bisa berbuat apa-apa"], ans: 2, skor: [2, 3, 5, 4, 1], bahas: "Transparansi dan solusi sementara menjaga kepercayaan saat terjadi gangguan." },
  { id: "tkp-pel-008", topik: "TKP Pelayanan Publik", level: 1, q: "Seorang warga penyandang disabilitas kesulitan menuju loket di lantai dua. Anda...", opts: ["Turun menemuinya dan melayani di lantai dasar, atau menyiapkan fasilitas bantu", "Menjelaskan bahwa layanan hanya tersedia di lantai dua dan tidak ada pengecualian untuk siapa pun", "Menyarankan ia datang bersama keluarga agar ada yang membantu membawanya naik ke lantai atas", "Meminta rekan membantu mengantarnya naik dan memastikan ia dilayani dengan nyaman sampai selesai", "Menunggu warga itu naik sendiri sambil tetap melayani nomor antrean berikutnya agar tidak menunda"], ans: 0, skor: [5, 1, 3, 4, 2], bahas: "Pelayanan inklusif menyesuaikan cara melayani agar semua warga dapat mengakses haknya." },
  { id: "tkp-pel-009", topik: "TKP Pelayanan Publik", level: 3, q: "Muncul keluhan viral di media sosial tentang layanan unit Anda. Anda...", opts: ["Melaporkan ke atasan, menelusuri kebenarannya, lalu membantu menyusun jawaban resmi serta perbaikan layanan", "Meminta rekan membuat komentar tandingan agar citra unit kembali baik di mata publik secepatnya", "Menunggu arahan atasan dan tidak ikut berkomentar sampai ada pernyataan resmi dari kantor pusat", "Mengumpulkan bukti dan catatan layanan lalu menyerahkannya kepada atasan agar ditanggapi dengan tepat", "Membalas keluhan itu dengan sindiran dari akun pribadi supaya pengunggah merasa malu dan menghapus unggahannya"], ans: 0, skor: [5, 2, 3, 4, 1], bahas: "Kritik publik adalah bahan perbaikan; responsnya harus resmi, jujur, dan disertai tindakan." },
  { id: "tkp-pel-010", topik: "TKP Pelayanan Publik", level: 1, q: "Warga yang belum paham prosedur bertanya berulang kali. Anda...", opts: ["Memberi jawaban singkat saja karena waktu layanan terbatas dan antrean di belakangnya masih panjang", "Menunjukkan wajah tidak senang supaya warga merasa sungkan dan berhenti bertanya hal yang sama", "Menjelaskan ulang dengan bahasa sederhana dan memberi selebaran langkah-langkahnya", "Mengulang penjelasan dengan sabar sambil menunjukkan contoh formulir yang sudah terisi dengan benar", "Meminta warga membaca pengumuman di dinding sebelum bertanya lagi kepada petugas yang sedang sibuk"], ans: 2, skor: [3, 1, 5, 4, 2], bahas: "Kesabaran dan bahasa sederhana membuat layanan benar-benar bermanfaat." },
  { id: "tkp-pel-011", topik: "TKP Pelayanan Publik", level: 3, q: "Atasan meminta Anda mendahulukan kenalannya yang datang belakangan. Anda...", opts: ["Melayani kenalan atasan tanpa antre dan menutupinya dari warga lain yang sudah menunggu sejak pagi", "Menyampaikan dengan sopan bahwa layanan berurutan sesuai standar, lalu menawarkan membantu secepat prosedur membolehkan", "Menuruti perintah atasan sambil menggerutu pelan agar rekan lain tahu bahwa Anda melakukannya terpaksa", "Melayani kenalan itu karena perintah atasan namun mencatat kejadiannya untuk dilaporkan di lain waktu", "Menyampaikan keberatan kepada atasan secara pribadi dan tetap melayani sesuai urutan antrean yang ada"], ans: 1, skor: [1, 5, 2, 3, 4], bahas: "Asas keadilan melarang diskriminasi layanan; sampaikan dengan santun kepada atasan." },
  { id: "tkp-pel-012", topik: "TKP Pelayanan Publik", level: 2, q: "Jam layanan tinggal lima menit dan seorang warga datang dengan berkas lengkap. Anda...", opts: ["Menerima berkas itu tetapi baru memprosesnya beberapa hari lagi tanpa memberi tahu warga yang menunggu", "Meminta warga kembali besok karena jam layanan sudah hampir habis dan loket akan segera ditutup", "Mengatakan sistem sudah tutup padahal masih bisa dipakai untuk memproses satu berkas yang lengkap itu", "Melayani hingga selesai bila memungkinkan, atau memberi jadwal prioritas yang jelas", "Memeriksa berkas sekilas dan memproses bagian yang bisa selesai sebelum jam layanan berakhir nanti"], ans: 3, skor: [2, 3, 1, 5, 4], bahas: "Utamakan kepentingan warga selama tidak melanggar aturan; bila tidak sempat, beri kepastian." },
  { id: "tkp-pel-013", topik: "TKP Pelayanan Publik", level: 3, q: "Standar layanan 30 menit, tetapi satu kasus rumit membutuhkan 45 menit. Anda...", opts: ["Menjelaskan kondisinya kepada warga, menuntaskan kasus dengan benar, dan melapor untuk evaluasi standar waktu", "Mengalihkan kasus ke rekan yang lebih berpengalaman tanpa menjelaskan alasannya kepada warga yang menunggu", "Menolak kasus itu karena dianggap bisa merusak catatan kinerja layanan tepat waktu milik unit Anda", "Menuntaskan kasus itu sampai selesai dan mencatat penyebab keterlambatannya untuk bahan laporan bulanan", "Menyelesaikan seadanya supaya tepat 30 menit walaupun beberapa bagian belum sempat diperiksa dengan teliti"], ans: 0, skor: [5, 3, 1, 4, 2], bahas: "Kualitas dan ketepatan tidak boleh dikorbankan demi angka; sampaikan kendala secara terbuka." },
  { id: "tkp-pel-014", topik: "TKP Pelayanan Publik", level: 2, q: "Kotak saran memuat kritik pedas tentang sikap Anda dalam melayani. Reaksi Anda...", opts: ["Menyobek kertas kritik itu supaya tidak dibaca oleh atasan maupun rekan kerja lainnya di kantor", "Membaca dengan tenang, merenungkan bagian yang benar, lalu memperbaiki cara melayani", "Menganggap kritik itu tidak penting karena hanya ditulis oleh satu orang yang kebetulan sedang kesal", "Mencari tahu siapa penulisnya dari tulisan tangan untuk menanyakan maksud sebenarnya secara langsung", "Meminta pendapat rekan tentang kritik itu untuk memastikan apakah penilaian tersebut wajar atau tidak"], ans: 1, skor: [1, 5, 3, 2, 4], bahas: "Kritik adalah umpan balik; sikap terbuka adalah ciri profesional." },
  { id: "tkp-pel-015", topik: "TKP Pelayanan Publik", level: 1, q: "Seorang warga menyelipkan uang terima kasih di sela berkas. Anda...", opts: ["Mengembalikan uang dengan sopan, menjelaskan aturan gratifikasi, dan melapor bila diwajibkan oleh aturan", "Mengembalikan uang itu saat itu juga tanpa membahas panjang lebar dan tetap melayani seperti biasa", "Mengantongi uang karena diberikan dengan tulus dan tidak ada seorang pun yang meminta pemberiannya", "Menyimpan uang itu sementara di laci lalu mengembalikannya ketika warga datang lagi di lain hari", "Membiarkan uang itu di meja dan berpura-pura tidak melihatnya hingga warga pergi meninggalkan loket"], ans: 0, skor: [5, 4, 1, 3, 2], bahas: "Gratifikasi harus ditolak atau dilaporkan sesuai aturan." },
  { id: "tkp-pel-016", topik: "TKP Pelayanan Publik", level: 1, q: "Seorang warga menanyakan status berkasnya yang sudah melewati estimasi selesai. Anda...", opts: ["Mengatakan bahwa Anda bukan petugas yang mengurus berkas itu lalu mempersilakan warga pergi begitu saja", "Mencatat nomor berkas dan menjanjikan akan menghubungi warga setelah mendapat kabar dari bagian terkait", "Meminta warga menunggu karena prosesnya memang membutuhkan waktu dan tidak bisa dipercepat oleh siapa pun", "Menyalahkan bagian lain di depan warga supaya warga tidak marah kepada Anda dan unit tempat Anda bekerja", "Mengecek ke bagian terkait saat itu juga dan memberi perkiraan waktu yang jelas"], ans: 4, skor: [2, 4, 3, 1, 5], bahas: "Warga berhak atas kepastian; cek, jelaskan, dan beri perkiraan waktu." },
  { id: "tkp-pel-017", topik: "TKP Pelayanan Publik", level: 2, q: "Mesin nomor antrean rusak dan warga mulai berebut maju. Anda...", opts: ["Meminta semua warga pulang dan kembali besok setelah mesin antrean diperbaiki oleh teknisi yang berwenang", "Melayani siapa pun yang paling dulu berbicara agar suasana tidak semakin gaduh di ruang tunggu", "Meminta warga berbaris dan mencatat nama mereka sambil menunggu teknisi memperbaiki mesin nomor antrean", "Menyuruh satpam membubarkan kerumunan supaya loket kembali tenang dan petugas bisa bekerja tanpa gangguan", "Membuat daftar antrean manual dengan tanda urutan, lalu melayani sesuai urutan kedatangan warga"], ans: 4, skor: [2, 3, 4, 1, 5], bahas: "Cari solusi sementara yang adil sambil menunggu perbaikan." },
  { id: "tkp-pel-018", topik: "TKP Pelayanan Publik", level: 1, q: "Seorang warga yang tidak bisa membaca kesulitan mengisi formulir. Anda...", opts: ["Membacakan isi formulir dan mencatat jawabannya, dengan data tetap dari warga", "Mengisikan formulir sesuai perkiraan Anda agar cepat selesai dan antrean di belakangnya tidak tertahan", "Memanggil rekan untuk menemaninya mengisi formulir sambil Anda menjelaskan setiap kolom satu per satu", "Menyuruh warga meminta bantuan orang lain di luar kantor yang bisa membacakan isi formulir dengan baik", "Menolak membantu karena formulir seharusnya diisi sendiri oleh pemohon yang bersangkutan, sesuai aturan"], ans: 0, skor: [5, 2, 4, 3, 1], bahas: "Layanan inklusif membantu tanpa mengubah isi data milik warga." },
  { id: "tkp-pel-019", topik: "TKP Pelayanan Publik", level: 2, q: "Seorang warga hanya lancar berbahasa daerah dan kesulitan memahami penjelasan Anda. Anda...", opts: ["Mengulang penjelasan yang sama dengan suara lebih keras agar warga lebih mudah mengerti maksudnya", "Mengatakan Anda tidak bisa melayani karena kendala bahasa lalu memanggil nomor antrean berikutnya", "Menulis poin-poin penting dengan huruf besar lalu menjelaskannya sambil menunjuk satu per satu pelan-pelan", "Mencari petugas yang bisa menerjemahkan, atau memakai bahasa sederhana dan contoh yang mudah dipahami", "Menyuruhnya kembali bersama anak yang bisa berbahasa Indonesia agar proses berikutnya lebih cepat selesai"], ans: 3, skor: [3, 1, 4, 5, 2], bahas: "Pastikan warga benar-benar paham, bukan sekadar mendengar." },
  { id: "tkp-pel-020", topik: "TKP Pelayanan Publik", level: 2, q: "Rekan Anda melayani warga sambil bermain ponsel. Anda...", opts: ["Mendiamkannya karena Anda tidak ingin merusak hubungan baik dengan rekan kerja yang sudah lama dikenal", "Mengingatkan secara pribadi dengan sopan, dan melapor bila perilakunya berulang", "Merekam kejadian itu sebagai bukti untuk diunggah ke grup kantor jika terjadi lagi di kemudian hari", "Mengambil alih melayani warga itu dengan ramah lalu menegur rekan setelah jam layanan selesai nanti", "Memarahi rekan itu di depan warga agar semua orang tahu bahwa perilakunya tidak pantas dilakukan"], ans: 1, skor: [3, 5, 2, 4, 1], bahas: "Tegur dengan baik lebih dulu, jalur formal bila berulang." },
  { id: "tkp-pel-021", topik: "TKP Pelayanan Publik", level: 3, q: "Warga mengeluh diminta uang oleh orang yang mengaku petugas, padahal layanan gratis. Anda...", opts: ["Menyarankan warga membayar saja agar urusannya cepat selesai dan tidak menimbulkan masalah baru bagi dirinya", "Mencatat kronologi, menjelaskan bahwa layanan gratis, lalu melaporkannya ke atasan atau kanal pengaduan resmi", "Mengunggah cerita warga di media sosial tanpa bukti agar menjadi perhatian publik dan cepat ditindak", "Menenangkan warga dan menjelaskan bahwa layanan gratis, lalu meminta ia mengingat ciri orang tersebut", "Meminta warga mencari sendiri orang itu karena Anda tidak mengenal semua petugas yang ada di kantor ini"], ans: 1, skor: [2, 5, 1, 4, 3], bahas: "Pungli harus ditindak lewat jalur resmi dengan bukti." },
  { id: "tkp-pel-022", topik: "TKP Pelayanan Publik", level: 2, q: "Seseorang meminta data pribadi warga lain dengan alasan urusan keluarga. Anda...", opts: ["Meminta pemohon menunggu sebentar lalu memberikan datanya diam-diam tanpa pencatatan apa pun di buku layanan", "Meminta bukti hubungan keluarga lebih dulu lalu memberikan sebagian data yang memang diperlukan saja", "Menolak, menjelaskan data pribadi hanya untuk pemiliknya atau atas dasar hukum yang sah", "Memberikan seluruh data karena orang itu terlihat meyakinkan dan berbicara dengan sangat sopan kepada Anda", "Menawarkan agar pemilik data sendiri yang datang atau memberi surat kuasa yang resmi dan lengkap"], ans: 2, skor: [2, 3, 5, 1, 4], bahas: "Perlindungan data pribadi warga adalah kewajiban." },
  { id: "tkp-pel-023", topik: "TKP Pelayanan Publik", level: 3, q: "Kepala unit meminta laporan survei kepuasan dipercantik padahal hasil aslinya rendah. Anda...", opts: ["Membuat dua versi laporan, yang asli untuk arsip dan versi ringkas sesuai permintaan atasan Anda", "Menyampaikan bahwa data harus apa adanya, lalu mengusulkan rencana perbaikan agar hasil berikutnya meningkat", "Menuruti permintaan itu karena Anda khawatir dianggap tidak mendukung pimpinan unit dan dinilai kurang loyal", "Membocorkan hasil asli ke media agar atasan terpaksa memperbaiki layanan unit ini secepat mungkin", "Mengubah sedikit angka saja pada bagian yang paling rendah agar tidak terlalu mencolok di laporan"], ans: 1, skor: [4, 5, 2, 1, 3], bahas: "Data jujur adalah dasar perbaikan layanan." },
  { id: "tkp-pel-024", topik: "TKP Pelayanan Publik", level: 1, q: "Seorang warga datang sepuluh menit sebelum loket buka dan mendesak segera dilayani. Anda...", opts: ["Mempersilakan warga duduk di ruang tunggu dan menawarkan formulir untuk diisi sambil menunggu loket buka", "Mengusir warga dari depan loket karena dianggap mengganggu persiapan petugas sebelum layanan dimulai", "Mengabaikan permintaan itu sampai jam buka tanpa menjawab sepatah kata pun kepada warga tersebut", "Menjelaskan jam layanan, lalu mempersilakan menunggu atau mengambil nomor antrean", "Meminta warga kembali besok pagi karena loket baru bisa melayani pada jam yang sudah ditentukan"], ans: 3, skor: [4, 1, 2, 5, 3], bahas: "Tetap sopan dan konsisten pada jam layanan." },
  { id: "tkp-pel-025", topik: "TKP Pelayanan Publik", level: 1, q: "Anda tidak tahu jawaban pertanyaan seorang warga. Anda...", opts: ["Menyuruh warga bertanya ke internet karena jawabannya pasti ada di sana dan mudah ditemukan siapa saja", "Memberi jawaban perkiraan yang kira-kira benar agar warga tidak merasa pulang dengan tangan kosong", "Jujur mengatakan belum tahu, lalu bertanya ke rekan atau atasan dan menyampaikan jawaban yang benar kepada warga", "Meminta nomor kontak warga dan berjanji menghubungi setelah mencari tahu jawabannya dengan teliti", "Mengalihkan pembicaraan ke hal lain sampai warga lupa dengan pertanyaannya yang tadi belum terjawab"], ans: 2, skor: [1, 3, 5, 4, 2], bahas: "Jujur dan menuntaskan jawaban lebih baik daripada menebak." },
  { id: "tkp-pel-026", topik: "TKP Pelayanan Publik", level: 1, q: "Seorang ibu membawa bayi yang menangis di tengah antrean panjang. Anda...", opts: ["Memintanya datang lagi saat bayinya tenang agar tidak mengganggu kenyamanan warga lainnya di ruang tunggu", "Menawarkan ibu itu didahulukan atau diberi tempat duduk, sesuai kebijakan prioritas", "Menyediakan kursi dan air minum untuknya sambil tetap menjaga urutan antrean secara adil bagi semua", "Meminta ibu itu membawa bayinya keluar sebentar supaya suasana ruang tunggu tidak menjadi berisik", "Melayani seperti biasa tanpa perlakuan khusus karena semua orang di sini sedang menunggu giliran masing-masing"], ans: 1, skor: [1, 5, 4, 3, 2], bahas: "Perhatikan kelompok rentan dan kebijakan prioritas." },
  { id: "tkp-pel-027", topik: "TKP Pelayanan Publik", level: 2, q: "Seorang warga berulang kali mengadukan hal yang sama. Anda...", opts: ["Meminta warga berhenti mengadu karena sudah terlalu sering dan menurut Anda tidak ada yang bisa diubah", "Mencatat aduan itu lagi lalu meneruskannya kepada atasan dengan catatan bahwa ini sudah berulang kali", "Menelusuri riwayat aduan, mencari akar masalahnya, dan memberi penjelasan atau solusi yang tuntas bagi warga", "Mengalihkan aduan ke unit lain tanpa penjelasan agar tidak membebani unit Anda dengan urusan lama", "Menjawab dengan jawaban yang sama seperti sebelumnya karena aturan yang berlaku memang tidak berubah"], ans: 2, skor: [1, 4, 5, 2, 3], bahas: "Aduan berulang tanda masalah belum selesai." },
  { id: "tkp-pel-028", topik: "TKP Pelayanan Publik", level: 2, q: "Banyak warga bertanya karena formulir daring sulit dipahami. Anda...", opts: ["Mengabaikan keluhan itu karena formulir dibuat oleh pusat dan bukan oleh unit tempat Anda bekerja", "Mencatat pertanyaan yang sering muncul dan mengusulkan perbaikan formulir atau panduan", "Menyuruh warga datang langsung ke kantor saja supaya dibantu mengisi formulir oleh petugas yang ada", "Menyalahkan warga yang kurang teliti membaca petunjuk di bagian atas formulir daring tersebut", "Menjawab setiap pertanyaan dengan sabar dan menyiapkan contoh pengisian untuk dibagikan kepada warga"], ans: 1, skor: [1, 5, 3, 2, 4], bahas: "Masalah yang berulang perlu diperbaiki di sumbernya." },
  { id: "tkp-pel-029", topik: "TKP Pelayanan Publik", level: 2, q: "Rekan senior melayani warga berpenampilan sederhana dengan ketus. Anda...", opts: ["Menegur dengan sopan setelahnya bahwa semua warga berhak dilayani sama, dan mengambil alih bila perlu", "Meniru caranya berbicara agar tidak dianggap berbeda dari rekan-rekan seniornya yang lain di kantor", "Mencatat kejadian itu dalam hati untuk dijadikan bahan cerita di grup kerja pada kesempatan berikutnya", "Diam karena sungkan menegur orang yang lebih senior dan lebih berpengalaman di kantor ini selama bertahun-tahun", "Menghampiri warga itu dan menawarkan bantuan dengan ramah sambil rekan senior melanjutkan tugas lainnya"], ans: 0, skor: [5, 1, 2, 3, 4], bahas: "Layanan tidak boleh membedakan penampilan." },
  { id: "tkp-pel-030", topik: "TKP Pelayanan Publik", level: 2, q: "Tetangga menitipkan berkas dan meminta Anda membantu agar diproses lebih cepat dari yang lain. Anda...", opts: ["Memproses berkas itu lebih dulu sebagai bantuan sesama tetangga yang sudah saling mengenal sejak lama", "Menolak bicara dengan tetangga itu lagi karena merasa dimanfaatkan atas dasar hubungan bertetangga", "Memeriksa kelengkapan berkas itu hingga benar dan menjelaskan estimasi waktu prosesnya dengan jujur", "Menyampaikan berkas diproses sesuai urutan, dan menawarkan memeriksa kelengkapannya", "Meminta tetangga mengajukan sendiri secara langsung supaya tidak menimbulkan salah paham di kemudian hari"], ans: 3, skor: [1, 2, 4, 5, 3], bahas: "Bantu dengan memeriksa kelengkapan, bukan melompati antrean." },
  { id: "tkp-pel-031", topik: "TKP Pelayanan Publik", level: 1, q: "Seorang warga menelepon kantor tepat setelah jam layanan berakhir untuk menanyakan syarat pembuatan dokumen. Anda...", opts: ["Mengatakan layanan sudah tutup dan meminta warga menelepon kembali pada jam kerja berikutnya saja", "Menjawab dengan ramah, menjelaskan syaratnya, dan menyarankan melihat daftar persyaratan resmi di kanal daring", "Menjawab singkat tanpa kepastian karena jam kerja sudah selesai dan Anda sudah siap untuk pulang", "Mencatat pertanyaannya dan menghubungi kembali besok pagi dengan informasi yang lengkap dan akurat", "Membiarkan telepon berdering sampai warga menyerah dan menutupnya sendiri tanpa ada yang menjawab, sebab Anda merasa tidak ada pilihan lain"], ans: 1, skor: [3, 5, 2, 4, 1], bahas: "Layanan informasi yang ramah dan tuntas menghemat waktu warga." },
  { id: "tkp-pel-032", topik: "TKP Pelayanan Publik", level: 1, q: "Satu-satunya loket yang buka melayani antrean panjang saat jam makan siang. Anda...", opts: ["Mempersilakan warga mengambil formulir dulu agar prosesnya lebih cepat ketika gilirannya dilayani nanti", "Menutup loket untuk istirahat sesuai jadwal karena itu hak setiap petugas di kantor ini tanpa kecuali", "Menyuruh warga datang di jam lain tanpa menanyakan mendesak atau tidaknya keperluan mereka hari ini", "Melayani antrean tanpa istirahat sambil menyampaikan permohonan maaf kepada warga yang menunggu lama", "Mengusulkan bergantian istirahat agar dua loket tetap buka, dan mengumumkan estimasi waktu"], ans: 4, skor: [3, 2, 1, 4, 5], bahas: "Atur jadwal bergantian agar layanan tidak terputus." },
  { id: "tkp-pel-033", topik: "TKP Pelayanan Publik", level: 2, q: "Seorang warga membandingkan layanan Anda dengan instansi lain dengan nada ketus. Anda...", opts: ["Mengakui kekurangan dengan tenang, menanyakan hal yang paling mengganggu, dan mencari solusi sesuai aturan", "Membalas dengan membandingkan balik kekurangan instansi lain agar warga berhenti menyindir layanan Anda", "Mendengarkan perbandingan itu lalu menjelaskan alasan prosedur yang berlaku di unit Anda dengan sopan", "Mengabaikan sindiran itu dan melayani seperlunya dengan wajah datar tanpa berbicara sepatah kata pun", "Menjelaskan bahwa tiap instansi memiliki aturan sendiri dan Anda hanya menjalankan aturan yang ada saja"], ans: 0, skor: [5, 2, 4, 1, 3], bahas: "Kritik dijawab dengan solusi, bukan pembelaan." },
  { id: "tkp-pel-034", topik: "TKP Pelayanan Publik", level: 2, q: "Seorang warga kehilangan dokumen asli yang diperlukan untuk pengajuan layanan. Anda...", opts: ["Menerima salinan dokumen saja dan meminta warga melengkapi yang asli suatu saat nanti kalau sudah ketemu", "Menolak pengajuan karena dokumen asli adalah syarat mutlak yang tidak bisa ditawar dengan alasan apa pun", "Memberi tahu bahwa harus membuat surat kehilangan dulu lalu menjelaskan langkah-langkah selanjutnya", "Menyarankan warga mencari sendiri informasi pengurusan dokumen di kantor lain yang lebih paham soal itu", "Menjelaskan prosedur dokumen pengganti, memberi daftar syarat, dan membantu agar lancar"], ans: 4, skor: [3, 2, 4, 1, 5], bahas: "Bantu warga menemukan jalan keluar yang sesuai aturan." },
  { id: "tkp-pel-035", topik: "TKP Pelayanan Publik", level: 3, q: "Rekan Anda meminta Anda menutupi kesalahan layanan yang ia buat agar tidak dilaporkan. Anda...", opts: ["Mendorongnya mengakui kesalahan, membantu memperbaikinya, dan menyampaikan ke atasan bila berdampak ke warga", "Membantu memperbaiki kesalahan itu sambil mengingatkan agar rekan melaporkannya sendiri kepada atasan", "Menolak ikut menutupi tetapi tidak melaporkannya karena tidak ingin merusak hubungan baik dengan rekan", "Menutupi kesalahan itu satu kali saja dengan syarat tidak terulang lagi di kemudian hari nanti", "Menutupi kesalahan dan ikut membuat catatan palsu supaya rekan tidak terkena sanksi dari pimpinan unit"], ans: 0, skor: [5, 4, 3, 2, 1], bahas: "Akuntabilitas berarti tidak ikut menyembunyikan kesalahan yang berdampak pada warga." },
  { id: "tkp-pel-036", topik: "TKP Pelayanan Publik", level: 2, q: "Seorang warga datang bersama pendamping yang selalu menjawab menggantikan warga itu. Anda...", opts: ["Menanyakan langsung kepada warga dan mencatat sesuai kehendaknya sendiri", "Mempersilakan pendamping membantu tetapi mengonfirmasi hal penting kepada warga yang bersangkutan langsung", "Menerima jawaban pendamping karena warga tampak nyaman dengan bantuan orang yang mendampinginya itu", "Meminta pendamping keluar ruangan tanpa menjelaskan alasannya kepada warga maupun kepada pendampingnya", "Mengabaikan warga dan hanya berbicara dengan pendamping agar prosesnya berlangsung lebih singkat dan cepat"], ans: 0, skor: [5, 4, 3, 1, 2], bahas: "Data dan persetujuan harus bersumber dari warga sendiri." },
  { id: "tkp-pel-037", topik: "TKP Pelayanan Publik", level: 2, q: "Seorang warga meminta salinan dokumen internal kantor yang bukan haknya. Anda...", opts: ["Meminta warga bertanya kepada atasan karena Anda tidak berwenang memutuskan boleh tidaknya dokumen itu diberikan", "Menjelaskan bahwa dokumen itu tidak dapat diberikan, menyebut dasar aturannya, dan menawarkan jalur permohonan resmi", "Menolak permintaan itu dengan sopan dan menjelaskan dokumen apa saja yang boleh diakses oleh publik", "Memberi seluruh salinan karena warga tampak sangat membutuhkannya untuk keperluan urusan pribadinya", "Memberi salinan sebagian saja yang menurut Anda tidak terlalu penting bagi kantor maupun bagi warga"], ans: 1, skor: [3, 5, 4, 1, 2], bahas: "Keterbukaan informasi mengikuti aturan, bukan perasaan." },
  { id: "tkp-pel-038", topik: "TKP Pelayanan Publik", level: 1, q: "Seorang pengunjung tampak pucat dan hampir pingsan di ruang tunggu. Anda...", opts: ["Mendudukkannya, memberi air, memanggil petugas kesehatan, dan menghubungi keluarganya", "Meminta pengunjung lain membantu karena Anda sedang melayani warga yang sudah menunggu di loket", "Melanjutkan melayani antrean karena kejadian itu bukan bagian dari tugas pokok yang ada di meja Anda", "Memanggil petugas keamanan dan menjaga pengunjung itu sampai bantuan yang dibutuhkan tiba di tempat", "Menyarankan pengunjung itu pulang dan beristirahat di rumah saja agar tidak merepotkan petugas di kantor"], ans: 0, skor: [5, 3, 1, 4, 2], bahas: "Keselamatan warga lebih utama daripada urutan pekerjaan." },
  { id: "tkp-pel-039", topik: "TKP Pelayanan Publik", level: 2, q: "Seorang warga mengirim keluhan lewat WhatsApp pribadi Anda pada malam hari. Anda...", opts: ["Menanggapi dengan sopan di jam kerja, mengarahkan warga ke kanal pengaduan resmi, dan mencatat keluhannya", "Meneruskan pesan itu ke grup kantor sambil mengeluh tentang warga yang mengganggu waktu istirahat Anda", "Membalas singkat bahwa keluhan akan ditindaklanjuti besok dan meminta warga melampirkan datanya dengan lengkap", "Mengabaikan pesan itu karena sudah di luar jam kerja dan tidak ada kewajiban membalas pesan pribadi", "Memblokir nomor warga itu agar tidak lagi menghubungi Anda secara pribadi pada malam hari lagi tanpa memikirkan akibat jangka panjangnya"], ans: 0, skor: [5, 2, 4, 3, 1], bahas: "Arahkan keluhan ke kanal resmi agar tercatat dan ditindaklanjuti." },
  { id: "tkp-pel-040", topik: "TKP Pelayanan Publik", level: 1, q: "Anda melihat seorang warga tampak bingung mencari loket di lobi. Anda...", opts: ["Menunggu sampai warga bertanya terlebih dahulu karena tidak ingin dianggap mencampuri urusan orang lain", "Menghampiri, menanyakan keperluannya, dan mengantarnya ke loket yang tepat", "Menunjukkan arah dengan jelas dan memberi tahu nomor loket serta syarat yang perlu dibawa oleh warga", "Mengabaikannya karena tugas Anda adalah melayani warga yang sudah duduk di meja Anda saat ini saja", "Menyuruh warga bertanya kepada satpam di pintu depan yang menurut Anda lebih tahu letak ruangannya"], ans: 1, skor: [3, 5, 4, 1, 2], bahas: "Proaktif membantu warga mencerminkan budaya pelayanan." },
  { id: "tkp-pel-041", topik: "TKP Pelayanan Publik", level: 3, q: "Seorang warga ngotot memakai aturan lama yang sudah dicabut dan menuntut dilayani sesuai aturan itu. Anda...", opts: ["Menjelaskan dengan tenang aturan terbaru beserta dasarnya, menunjukkan salinannya, dan mencari solusi dalam batas aturan", "Melayani sesuai aturan lama demi menghindari keributan yang bisa mengganggu antrean warga yang lain", "Menjelaskan perubahan aturan itu dan memanggil atasan bila warga masih belum bisa menerima penjelasannya", "Membantah dengan nada tinggi dan menuduh warga tidak mengikuti perkembangan aturan yang sudah berubah", "Mempersilakan warga bertanya kepada atasan karena Anda tidak ingin berdebat soal aturan dengan warga"], ans: 0, skor: [5, 2, 4, 1, 3], bahas: "Konsisten pada aturan yang berlaku, disampaikan tenang dan beralasan." },
  { id: "tkp-pel-042", topik: "TKP Pelayanan Publik", level: 2, q: "Layanan daring sedang error dan seorang warga yang tidak mahir teknologi menunggu bantuan. Anda...", opts: ["Meminta warga bertanya kepada anaknya yang lebih paham teknologi dan kembali lagi pada hari yang lain", "Mengatakan sistem sedang rusak dan tidak ada yang bisa dilakukan hari ini oleh siapa pun di kantor", "Mendampinginya mencoba beberapa kali sampai bisa dan mencatat error untuk dilaporkan ke bagian TI", "Membantunya lewat jalur alternatif atau manual, dan menjelaskan kapan sistem normal", "Menyarankan warga mencoba lagi di rumah nanti saat sistem sudah kembali berfungsi dengan baik"], ans: 3, skor: [2, 1, 4, 5, 3], bahas: "Layanan harus tetap tersedia lewat alternatif saat sistem bermasalah." },
  { id: "tkp-pel-043", topik: "TKP Pelayanan Publik", level: 3, q: "Seorang warga yang pernah kecewa menolak dilayani Anda dan meminta petugas lain. Anda...", opts: ["Menjawab dengan nada tersinggung bahwa warga tidak berhak memilih petugas sesuka hatinya di kantor ini", "Menerima permintaan itu dengan lapang dada, memanggil rekan yang bersedia, lalu mengevaluasi diri secara jujur", "Menolak permintaan itu dengan alasan antrean harus dilayani sesuai urutan petugas yang sudah ditentukan", "Menjelaskan bahwa semua petugas melayani sesuai prosedur yang sama sehingga tidak ada perbedaan layanan", "Meminta maaf atas pengalaman sebelumnya dan menawarkan melayani dengan lebih baik pada kesempatan kali ini"], ans: 1, skor: [1, 5, 2, 3, 4], bahas: "Kepuasan warga diutamakan selama tidak melanggar aturan." },
  { id: "tkp-pel-044", topik: "TKP Pelayanan Publik", level: 1, q: "Seorang warga menanyakan jumlah biaya resmi suatu layanan karena khawatir ditipu. Anda...", opts: ["Menyebutkan biaya resmi dan menyarankan warga meminta bukti pembayaran setiap kali membayar sesuatu", "Menjawab perkiraan saja karena Anda tidak hafal tarif seluruh layanan yang tersedia di kantor ini", "Meminta warga tidak banyak bertanya karena biayanya sudah ditetapkan dari pusat dan tidak bisa diubah", "Menyebutkan biaya resmi, menunjukkan daftarnya, dan mengingatkan menolak pungutan lain", "Menjawab bahwa biaya bisa dilihat di loket pembayaran dan warga dipersilakan bertanya langsung di sana"], ans: 3, skor: [4, 2, 1, 5, 3], bahas: "Transparansi biaya mencegah pungli." },
  { id: "tkp-pel-045", topik: "TKP Pelayanan Publik", level: 2, q: "Dua formulir yang hampir sama membuat warga bingung memilih yang mana. Anda...", opts: ["Menyuruh warga bertanya kepada petugas lain yang menurut Anda lebih paham perbedaan kedua formulir tersebut", "Menyerahkan kedua formulir dan membiarkan warga memilih sendiri yang menurutnya paling cocok untuk dirinya", "Memilihkan formulir yang tepat sesuai keperluan warga dan menjelaskan cara mengisinya dengan runtut", "Menjelaskan perbedaan keduanya, membantu memilih yang sesuai, dan mengusulkan penyederhanaan formulir tersebut", "Menyalahkan warga yang tidak membaca keterangan di bagian atas formulir dengan teliti sebelum bertanya"], ans: 3, skor: [2, 3, 4, 5, 1], bahas: "Layanan yang baik juga memperbaiki sumber kebingungan." },
  { id: "tkp-pel-046", topik: "TKP Pelayanan Publik", level: 2, q: "Setelah dilayani, warga meminta Anda memberi nilai bagus pada survei kepuasan agar saling menguntungkan. Anda...", opts: ["Menjelaskan bahwa Anda tidak boleh memengaruhi penilaian dan mengajak warga mengisi surveinya sendiri", "Tersenyum tanpa menanggapi apa pun lalu membiarkan warga mengisi survei sesuai keinginannya sendiri", "Menjanjikan layanan lebih cepat di lain waktu jika warga bersedia memberi nilai sempurna untuk Anda", "Mengisikan survei itu untuk warga agar cepat selesai dan tidak merepotkan kedua belah pihak lagi", "Menolak sopan, menjelaskan survei harus jujur, dan mempersilakan warga menilai sendiri"], ans: 4, skor: [4, 3, 1, 2, 5], bahas: "Penilaian kepuasan harus murni dari warga." },
  { id: "tkp-pel-047", topik: "TKP Pelayanan Publik", level: 2, q: "Seorang warga menyerobot jalur prioritas padahal belum berhak. Anda...", opts: ["Melayani warga itu lebih dulu supaya tidak menimbulkan keributan di ruang layanan yang sedang ramai", "Memanggil petugas keamanan untuk membantu mengarahkan warga ke antrean yang benar dengan baik-baik", "Menegur warga dengan nada keras di depan banyak orang agar tidak ditiru oleh warga yang lain", "Membiarkan karena warga tampak terburu-buru dan antrean prioritas sedang sepi pada saat ini", "Menjelaskan dengan sopan bahwa jalur itu untuk kelompok tertentu, lalu mengarahkannya ke antrean umum"], ans: 4, skor: [1, 4, 2, 3, 5], bahas: "Tegakkan aturan jalur prioritas dengan sopan dan konsisten." },
  { id: "tkp-pel-048", topik: "TKP Pelayanan Publik", level: 1, q: "Seorang warga ingin berfoto bersama dan memberi bingkisan kecil setelah dibantu. Anda...", opts: ["Berterima kasih, menolak bingkisan sesuai aturan gratifikasi, dan menerima ucapan terima kasihnya", "Menerima karena nilainya kecil dan tidak ada hubungannya dengan pengurusan berkas milik warga itu", "Menerima bingkisan dan melaporkannya kepada atasan agar dicatat sesuai ketentuan yang berlaku di kantor", "Meminta warga menyerahkan bingkisan itu kepada rekan lain agar Anda tidak dianggap menerima pemberian", "Menolak bingkisan dan menyarankan warga menyampaikan apresiasi lewat survei layanan yang disediakan kantor"], ans: 0, skor: [5, 2, 3, 1, 4], bahas: "Gratifikasi ditolak atau dilaporkan, sekecil apa pun." },
  { id: "tkp-pel-049", topik: "TKP Pelayanan Publik", level: 2, q: "Seorang warga mengajukan permohonan yang jelas tidak memenuhi syarat dan mulai memelas. Anda...", opts: ["Menjelaskan syarat yang belum terpenuhi dan membantu warga mempersiapkan pengajuan berikutnya dengan baik", "Menunjukkan empati, menjelaskan alasan penolakan sesuai aturan, dan menyarankan alternatif yang masih mungkin ditempuh", "Memproses permohonan itu karena kasihan meski tahu bahwa permohonan tersebut tidak memenuhi persyaratan", "Menutup pembicaraan dengan menyatakan tidak ada kemungkinan apa pun tanpa memberikan penjelasan lebih lanjut", "Meminta warga bertemu atasan dengan harapan ada kebijakan khusus yang bisa diberikan kepadanya nanti"], ans: 1, skor: [4, 5, 2, 1, 3], bahas: "Empati tidak boleh melanggar aturan; jelaskan dan beri alternatif." },
  { id: "tkp-pel-050", topik: "TKP Pelayanan Publik", level: 3, q: "Jam pulang tiba, tetapi seorang warga masih membutuhkan bantuan penting yang tinggal sedikit lagi. Anda...", opts: ["Menuntaskan bantuan yang tinggal sedikit itu, lalu menyerahkan sisanya ke petugas berikutnya", "Meminta izin atasan untuk menyelesaikannya karena warga membutuhkan kepastian pada hari ini juga", "Menjadwalkan ulang esok hari dengan prioritas pertama dan memberi nomor yang bisa dihubungi warga", "Meminta warga kembali lain waktu tanpa memeriksa seberapa mendesak keperluan yang sedang dihadapinya", "Berhenti tepat waktu karena jam kerja sudah berakhir dan Anda memiliki urusan lain yang menunggu"], ans: 0, skor: [5, 4, 3, 1, 2], bahas: "Pelayanan menuntut kepekaan terhadap kebutuhan warga yang tinggal selangkah lagi selesai." },
  { id: "tkp-jej-001", topik: "TKP Jejaring Kerja", level: 1, q: "Anda butuh data dari unit lain, tetapi balasannya lambat. Anda...", opts: ["Menghubungi langsung dengan sopan, menjelaskan kebutuhan dan tenggat, lalu menindaklanjuti dengan jadwal yang disepakati", "Menanyakan kepada rekan dekat di unit itu siapa yang memegang data tersebut lalu meminta bantuannya", "Mengeluh kepada atasan tanpa menghubungi unit tersebut karena merasa sudah terlalu sering dipersulit", "Mengambil data dari sumber tidak resmi yang lebih cepat didapat walaupun keakuratannya belum jelas", "Mengerjakan laporan dengan data perkiraan lebih dulu dan menyempurnakannya ketika data resmi tiba, sebab Anda merasa tidak ada pilihan lain"], ans: 0, skor: [5, 4, 2, 1, 3], bahas: "Komunikasi langsung dan jelas membangun kerja sama antarunit." },
  { id: "tkp-jej-002", topik: "TKP Jejaring Kerja", level: 1, q: "Rekan satu tim berbeda pendapat dengan Anda tentang cara menyelesaikan tugas. Anda...", opts: ["Mengajak rekan membandingkan kedua cara dengan data singkat lalu memilih yang paling sesuai tujuan tim", "Membicarakan perbedaan itu di belakang kepada rekan lain agar mendapat dukungan untuk pendapat Anda", "Menyerahkan keputusan kepada atasan tanpa mencoba berdiskusi lebih dulu dengan rekan tersebut", "Mendengarkan alasannya, lalu mencari titik temu", "Diam dan menurut meskipun tidak setuju karena tidak ingin suasana tim menjadi canggung"], ans: 3, skor: [4, 1, 3, 5, 2], bahas: "Perbedaan pendapat diselesaikan dengan dialog terbuka demi tujuan tim." },
  { id: "tkp-jej-003", topik: "TKP Jejaring Kerja", level: 2, q: "Instansi lain mengundang rapat koordinasi di jam yang padat tugas Anda. Anda...", opts: ["Tidak hadir dan tidak memberi kabar karena yakin hasil rapat akan dikirim lewat email nantinya", "Mengatur jadwal dan hadir atau mengirim perwakilan yang paham materi, lalu menyampaikan hasilnya kepada tim", "Menolak undangan itu karena pekerjaan unit sedang sangat banyak dan tidak bisa ditinggalkan tanpa memikirkan akibat jangka panjangnya", "Hadir sebentar saja sambil mengerjakan tugas lain agar semua pekerjaan tetap berjalan bersamaan", "Meminta rapat dijadwalkan ulang bila memungkinkan dan tetap memberi kabar kepada penyelenggara"], ans: 1, skor: [1, 5, 2, 3, 4], bahas: "Koordinasi antarinstansi penting; pastikan kehadiran dan tindak lanjutnya." },
  { id: "tkp-jej-004", topik: "TKP Jejaring Kerja", level: 1, q: "Anda memiliki informasi yang berguna bagi tim lain. Anda...", opts: ["Menunggu sampai tim lain bertanya langsung karena tidak ingin dianggap mencampuri urusan mereka", "Menyimpannya untuk diri sendiri agar tim Anda terlihat lebih unggul dibandingkan tim yang lain", "Menginformasikannya kepada atasan agar disampaikan ke tim lain dalam rapat koordinasi berikutnya", "Membagikannya hanya kepada teman dekat di tim lain yang menurut Anda akan menyimpannya dengan baik", "Membagikannya secara proaktif lewat jalur resmi"], ans: 4, skor: [2, 1, 4, 3, 5], bahas: "Berbagi informasi memperkuat kolaborasi dan hasil organisasi." },
  { id: "tkp-jej-005", topik: "TKP Jejaring Kerja", level: 1, q: "Rekan baru kesulitan beradaptasi, sementara Anda sedang sibuk. Anda...", opts: ["Menyarankan ia membaca panduan kerja dan bertanya bila ada hal yang benar-benar tidak dipahami", "Menyediakan waktu singkat menjelaskan hal pokok, lalu menjadwalkan pendampingan lanjutan di hari berikutnya", "Meminta ia belajar sendiri dulu karena Anda yakin semua orang dulu juga harus melewati masa itu sesuai kebiasaan yang selama ini Anda jalani", "Menegurnya karena bekerja lambat padahal sudah beberapa hari berada di tim tanpa banyak kemajuan", "Meminta rekan lain yang lebih senggang untuk mendampinginya dan Anda tetap memantau perkembangannya"], ans: 1, skor: [3, 5, 2, 1, 4], bahas: "Membantu rekan baru mempercepat kinerja tim." },
  { id: "tkp-jej-006", topik: "TKP Jejaring Kerja", level: 3, q: "Dua unit berselisih soal pembagian wewenang pada satu tugas yang menyangkut Anda. Anda...", opts: ["Menceritakan perselisihan itu kepada banyak rekan agar ada yang membantu menekan unit yang lain sesuai kebiasaan yang selama ini Anda jalani", "Menghindar dari persoalan itu karena merasa bukan Anda yang berwenang menyelesaikan perselisihan antarunit", "Memilih berpihak pada unit sendiri karena Anda merasa lebih mengenal cara kerja dan kebutuhannya", "Menyiapkan ringkasan aturan yang relevan dan memberikannya kepada kedua unit agar dibahas bersama", "Meminta ruang pertemuan bersama dengan membawa data aturan wewenang, lalu mencari kesepakatan atau meminta keputusan pimpinan"], ans: 4, skor: [1, 3, 2, 4, 5], bahas: "Rujukan aturan dan keputusan pimpinan menyelesaikan konflik wewenang secara objektif." },
  { id: "tkp-jej-007", topik: "TKP Jejaring Kerja", level: 2, q: "Mitra eksternal terlambat menyerahkan laporan yang Anda butuhkan. Anda...", opts: ["Menawarkan bantuan atau format laporan yang lebih sederhana agar mitra dapat menyelesaikannya lebih cepat", "Menunda seluruh pekerjaan Anda sampai laporan itu diterima karena tidak ingin mengambil risiko kesalahan", "Langsung melapor mitra itu kepada atasannya karena menilai keterlambatan ini tidak bisa ditoleransi", "Menghubungi mitra, menanyakan kendalanya, dan menyepakati tenggat baru", "Mengancam akan memutus kerja sama jika laporan tidak diterima paling lambat besok pagi hari"], ans: 3, skor: [4, 3, 2, 5, 1], bahas: "Pendekatan solutif menjaga hubungan baik dan kelancaran kerja." },
  { id: "tkp-jej-008", topik: "TKP Jejaring Kerja", level: 2, q: "Anda ditugaskan menjembatani komunitas masyarakat dengan kantor. Langkah pertama Anda...", opts: ["Menyerahkan tugas itu kepada bawahan karena Anda sedang memiliki banyak pekerjaan penting lainnya", "Fokus pada kepentingan kantor lebih dulu karena kepentingan komunitas bisa dibahas setelah target tercapai", "Menyusun daftar kegiatan kantor yang berkaitan dengan komunitas lalu mengirimkannya melalui surat resmi", "Menunggu komunitas datang dan menyampaikan kebutuhannya sendiri karena merasa itu lebih menunjukkan keseriusan", "Menemui tokoh komunitas, mendengar kebutuhan mereka, lalu menyusun jalur komunikasi rutin yang jelas"], ans: 4, skor: [2, 1, 4, 3, 5], bahas: "Membangun jaringan dimulai dengan mendengar dan hadir." },
  { id: "tkp-jej-009", topik: "TKP Jejaring Kerja", level: 2, q: "Dalam rapat lintas instansi Anda paling junior, tetapi punya masukan penting. Anda...", opts: ["Menyampaikannya kepada pimpinan rapat sebelum atau sesudah sesi agar dipertimbangkan dengan baik", "Meminta senior menyampaikan masukan itu atas nama Anda agar tidak dianggap tidak sopan oleh peserta", "Menyampaikannya sopan berbasis data pada saat yang tepat", "Diam saja karena merasa tidak pantas memberi masukan di hadapan orang-orang yang jauh lebih senior", "Menulis masukan itu lewat pesan setelah rapat usai karena lebih nyaman daripada berbicara di forum"], ans: 2, skor: [4, 1, 5, 2, 3], bahas: "Kontribusi tidak ditentukan senioritas selama disampaikan santun dan relevan." },
  { id: "tkp-jej-010", topik: "TKP Jejaring Kerja", level: 2, q: "Rekan dari unit lain meminta bantuan di luar tugas pokok Anda. Anda...", opts: ["Meminta imbalan tertentu sebelum membantu karena pekerjaan itu bukan bagian dari tanggung jawab Anda", "Menilai urgensinya, membantu bila tidak mengganggu tugas utama, dan memberi tahu atasan Anda", "Mengarahkan rekan itu kepada orang lain yang menurut Anda lebih tepat menangani permintaan tersebut", "Menolak mentah-mentah karena semua orang sudah punya tugas masing-masing dan tidak boleh saling merepotkan", "Membantu sebisanya setelah tugas utama selesai dan menyampaikan kepada atasan bahwa Anda ikut membantu"], ans: 1, skor: [2, 5, 3, 1, 4], bahas: "Saling membantu tetap menjaga prioritas dan komunikasi dengan atasan." },
  { id: "tkp-jej-011", topik: "TKP Jejaring Kerja", level: 3, q: "Pembagian tugas dalam proyek tidak jelas karena pimpinan proyek kurang tegas. Anda...", opts: ["Mengambil alih peran pimpinan dan membagikan tugas kepada anggota tanpa meminta izin siapa pun, sebab Anda merasa tidak ada pilihan lain", "Mengajak rekan satu tim mendata tugas yang tumpang tindih lalu menyampaikan hasilnya kepada pimpinan", "Mengerjakan apa pun yang terlihat belum dikerjakan orang lain agar proyek tetap berjalan tanpa hambatan", "Menunggu sampai pimpinan menyadari sendiri bahwa pembagian tugas belum jelas dan segera memperbaikinya", "Menyusun usulan pembagian tugas tertulis, lalu meminta pimpinan proyek menyetujui dan menyampaikannya kepada seluruh anggota"], ans: 4, skor: [1, 4, 3, 2, 5], bahas: "Inisiatif menyusun kejelasan peran membantu tim tanpa melangkahi pimpinan." },
  { id: "tkp-jej-012", topik: "TKP Jejaring Kerja", level: 3, q: "Seorang rekan sering mengklaim hasil kerja tim sebagai miliknya. Anda...", opts: ["Berhenti berkontribusi pada tugas tim supaya rekan itu tidak bisa lagi mengaku-ngaku hasil kerja Anda", "Membalas dengan ikut mengklaim hasil kerja rekan lain agar adil dalam hal penghargaan di unit ini", "Berbicara langsung dengannya, dan bila berulang menyampaikan kepada atasan dengan bukti kontribusi tim", "Mendokumentasikan kontribusi tiap anggota sejak awal agar pembagian peran terlihat jelas dalam laporan", "Mendiamkannya karena Anda tidak ingin ribut dan berharap atasan akan menyadari sendiri siapa yang bekerja"], ans: 2, skor: [1, 2, 5, 4, 3], bahas: "Selesaikan lewat komunikasi langsung dulu, lalu jalur formal bila perlu." },
  { id: "tkp-jej-013", topik: "TKP Jejaring Kerja", level: 1, q: "Anda diminta menyusun daftar kontak darurat lintas unit. Anda...", opts: ["Menghubungi tiap unit, memverifikasi nomor dan penanggung jawab, lalu memperbaruinya secara berkala", "Meminta setiap unit mengirim kontak terbarunya lalu menggabungkannya menjadi satu daftar yang rapi", "Menyusun daftar dari ingatan karena Anda merasa sudah mengenal hampir semua orang di unit-unit itu", "Menyalin daftar lama yang tersimpan di arsip tanpa memeriksa ulang apakah nomornya masih aktif", "Menunda tugas itu sampai terjadi keadaan darurat karena baru pada saat itu daftar benar-benar dibutuhkan"], ans: 0, skor: [5, 4, 2, 3, 1], bahas: "Jaringan kerja yang andal membutuhkan data kontak yang akurat dan terbarui." },
  { id: "tkp-jej-014", topik: "TKP Jejaring Kerja", level: 1, q: "Dalam acara pertemuan antarinstansi, Anda...", opts: ["Berkenalan dengan peserta instansi lain, bertukar kontak, dan menindaklanjuti peluang kerja sama", "Menyendiri sambil memegang ponsel karena tidak terbiasa memulai percakapan dengan orang yang baru dikenal", "Mengikuti sesi acara dengan serius lalu menyapa beberapa peserta yang terkait dengan bidang kerja Anda", "Pulang lebih awal karena merasa pertemuan seperti ini hanya buang waktu dan tidak banyak manfaatnya", "Berbincang hanya dengan rekan kantor sendiri karena merasa lebih nyaman dengan orang yang sudah dikenal"], ans: 0, skor: [5, 2, 4, 1, 3], bahas: "Jejaring dibangun lewat interaksi dan tindak lanjut." },
  { id: "tkp-jej-015", topik: "TKP Jejaring Kerja", level: 2, q: "Dua rekan bertengkar di depan Anda. Anda...", opts: ["Menonton dulu untuk mengetahui siapa yang salah sebelum memutuskan akan bersikap bagaimana", "Meminta mereka berhenti dan melanjutkan pembicaraan di ruangan lain dengan didampingi atasan", "Memihak rekan yang lebih dekat dengan Anda karena merasa ia lebih benar dalam pertengkaran itu", "Menenangkan keduanya, lalu mengajak bicara terpisah untuk menyelesaikan masalah", "Melaporkannya kepada atasan tanpa mencoba menengahi karena menganggap itu bukan urusan Anda sama sekali"], ans: 3, skor: [3, 4, 2, 5, 1], bahas: "Menengahi dengan netral mencegah konflik membesar." },
  { id: "tkp-jej-016", topik: "TKP Jejaring Kerja", level: 2, q: "Seorang anggota tim tiba-tiba mengundurkan diri sehingga tugas menumpuk pada Anda. Anda...", opts: ["Melapor ke atasan, mengusulkan pembagian ulang tugas, dan membantu serah terima pekerjaan dengan baik", "Mengeluh kepada rekan-rekan lain tentang betapa tidak adilnya beban kerja yang tiba-tiba menjadi tanggung Anda", "Mengabaikan tugas yang bukan bagian Anda karena sudah ada pembagian peran yang jelas sejak awal", "Menyalahkan anggota yang keluar karena telah meninggalkan tim di saat pekerjaan sedang sangat banyak", "Mengerjakan semua tugas itu sendiri lebih dulu lalu melapor setelah beban kerja Anda terasa terlalu berat"], ans: 0, skor: [5, 3, 2, 1, 4], bahas: "Komunikasikan beban kerja dan atur ulang secara tertib." },
  { id: "tkp-jej-017", topik: "TKP Jejaring Kerja", level: 3, q: "Rapat dengan mitra eksternal berjalan alot dan mulai emosional. Anda...", opts: ["Meninggalkan rapat dengan alasan ada keperluan lain agar tidak terseret dalam perdebatan yang tidak produktif", "Mengusulkan jeda singkat", "Merangkum poin yang sudah disepakati dan mengajak peserta membahas poin yang masih berbeda satu per satu", "Diam saja sampai rapat selesai karena Anda tidak ingin memperkeruh suasana yang sudah memanas", "Ikut meninggikan suara untuk membela posisi unit Anda agar tidak dianggap lemah oleh pihak mitra"], ans: 1, skor: [1, 5, 4, 3, 2], bahas: "Meredakan suasana dan mengarahkan ke kesepakatan." },
  { id: "tkp-jej-018", topik: "TKP Jejaring Kerja", level: 3, q: "Atasan memerintahkan Anda mengoordinasikan tiga unit yang saling tidak akur. Anda...", opts: ["Memberi perintah kepada ketiganya tanpa mendengar alasan mereka agar pekerjaan bisa segera berjalan", "Bertemu masing-masing unit lebih dulu untuk memahami kepentingannya, lalu mempertemukan mereka dengan tujuan bersama yang jelas", "Melaporkan ketiga unit itu kepada atasan dan meminta atasan langsung yang menegur mereka semua", "Menyusun jadwal pertemuan bersama dan menetapkan aturan diskusi yang adil bagi ketiga unit sejak awal", "Menolak tugas itu karena terlalu sulit dan menyarankan atasan menunjuk orang lain yang lebih berpengaruh"], ans: 1, skor: [2, 5, 3, 4, 1], bahas: "Pahami kepentingan masing-masing sebelum menyatukan." },
  { id: "tkp-jej-019", topik: "TKP Jejaring Kerja", level: 1, q: "Seorang kolega di unit lain mengabaikan email Anda berulang kali. Anda...", opts: ["Meminta bantuan rekan di unit itu untuk mengingatkannya karena Anda tidak mau terkesan memaksa", "Mengirim pesan singkat yang menegaskan hal terpenting dan tenggatnya agar lebih mudah segera dibalas", "Mengirim email lagi dengan nada marah untuk menunjukkan bahwa Anda sudah kehabisan kesabaran sekarang", "Melapor kepada atasannya tanpa mencoba menghubungi lewat cara lain karena merasa itu cara tercepat", "Mencoba telepon atau menemuinya langsung"], ans: 4, skor: [3, 4, 2, 1, 5], bahas: "Ganti jalur komunikasi sebelum eskalasi." },
  { id: "tkp-jej-020", topik: "TKP Jejaring Kerja", level: 2, q: "Anda baru sadar telah memberi informasi yang keliru kepada unit lain. Anda...", opts: ["Segera menghubungi mereka, meminta maaf, dan menyampaikan informasi yang benar", "Membiarkannya karena belum ada masalah yang muncul dan Anda tidak ingin memperbesar persoalan ini", "Menyalahkan sumber data Anda supaya tidak dianggap lalai ketika kekeliruan itu akhirnya ketahuan", "Menunggu sampai mereka menyadari sendiri bahwa ada kekeliruan lalu menjelaskannya bila mereka bertanya", "Mengirim ralat tertulis berisi informasi yang benar disertai permohonan maaf kepada pihak yang terkait"], ans: 0, skor: [5, 2, 1, 3, 4], bahas: "Koreksi cepat dan terbuka menjaga kepercayaan." },
  { id: "tkp-jej-021", topik: "TKP Jejaring Kerja", level: 1, q: "Sebuah komunitas ingin bermitra tetapi proposalnya belum sesuai prioritas kantor. Anda...", opts: ["Mengajak perwakilan komunitas berdiskusi untuk menyamakan harapan sebelum proposal diajukan ulang", "Meneruskan proposal itu kepada atasan apa adanya tanpa memberi catatan atau pendapat apa pun", "Mengapresiasi inisiatifnya, menjelaskan prioritas kantor, dan membantu menyesuaikan proposal atau mencari bentuk kerja sama lain", "Menolak proposal itu tanpa penjelasan sehingga komunitas tidak tahu bagian mana yang perlu diperbaiki", "Menerima semua usulan komunitas demi menjaga hubungan baik walaupun tidak sejalan dengan prioritas kantor"], ans: 2, skor: [4, 3, 5, 1, 2], bahas: "Menolak dengan membangun, bukan menutup pintu." },
  { id: "tkp-jej-022", topik: "TKP Jejaring Kerja", level: 2, q: "Anda diminta mewakili kantor dalam sebuah forum tetapi kurang menguasai topiknya. Anda...", opts: ["Mengirim orang lain tanpa memberi tahu atasan karena merasa orang itu pasti lebih siap daripada Anda", "Hadir dan menyimak saja tanpa banyak bicara agar tidak salah menyampaikan sesuatu di depan orang lain", "Meminta bantuan rekan yang lebih paham untuk mendampingi dan menyiapkan bahan paparan Anda", "Mempelajari materi, berkonsultasi dengan yang ahli, lalu hadir dan mencatat hasil untuk tim", "Menolak penugasan itu karena merasa tidak mampu dan tidak mau mempermalukan nama baik kantor"], ans: 3, skor: [2, 3, 4, 5, 1], bahas: "Siapkan diri dan bawa pulang hasil untuk tim." },
  { id: "tkp-jej-023", topik: "TKP Jejaring Kerja", level: 2, q: "Seorang rekan sering curhat negatif tentang atasan kepada Anda. Anda...", opts: ["Menyarankan rekan menuliskan masukannya dengan bahasa yang santun lalu menyampaikannya kepada atasan", "Mendengarkan saja tanpa menanggapi apa pun agar rekan merasa lega setelah menumpahkan perasaannya", "Menyebarkan cerita rekan itu kepada orang lain supaya banyak yang tahu betapa sulitnya bekerja di sini", "Mendengarkan sebentar, lalu mengarahkan agar disampaikan langsung dan baik-baik lewat jalur resmi", "Ikut menambah cerita tentang kekurangan atasan karena Anda pun pernah merasakan hal yang sama"], ans: 3, skor: [4, 3, 1, 5, 2], bahas: "Jangan ikut memanaskan; arahkan ke solusi." },
  { id: "tkp-jej-024", topik: "TKP Jejaring Kerja", level: 1, q: "Dua tim berebut memakai ruang rapat pada jam yang sama. Anda...", opts: ["Melapor kepada pimpinan agar membuat aturan baru tanpa mencoba membantu kedua tim mencari jalan keluar", "Mengajak kedua tim berdiskusi singkat untuk menemukan pengaturan yang tidak merugikan siapa pun", "Mengecek jadwal tercatat, lalu mengusulkan pergantian waktu atau ruang alternatif", "Mengambil ruang itu lebih dulu karena Anda yang pertama kali menyadari ruangan tersebut kosong", "Membiarkan mereka berdebat sampai selesai karena nanti pasti ada yang mengalah dengan sendirinya"], ans: 2, skor: [1, 4, 5, 3, 2], bahas: "Cari solusi bersama berdasarkan aturan penjadwalan." },
  { id: "tkp-jej-025", topik: "TKP Jejaring Kerja", level: 2, q: "Anda menemukan kesalahan dalam pekerjaan unit lain. Anda...", opts: ["Memperbaiki kesalahan itu sendiri tanpa memberi tahu siapa pun agar urusan cepat selesai", "Menyampaikan temuan itu kepada penanggung jawab unit lewat pesan yang jelas dan tidak menyudutkan", "Melapor kepada atasan mereka tanpa berbicara dengan yang bersangkutan lebih dulu karena merasa lebih aman", "Membiarkannya agar mereka belajar dari kesalahan sendiri tanpa campur tangan dari pihak lain", "Menyampaikannya langsung dengan sopan disertai bukti, dan menawarkan membantu memperbaiki"], ans: 4, skor: [3, 4, 2, 1, 5], bahas: "Sampaikan langsung dengan santun dan bantu." },
  { id: "tkp-jej-026", topik: "TKP Jejaring Kerja", level: 1, q: "Seorang rekan tidak pernah dilibatkan dalam grup kerja. Anda...", opts: ["Menunggu sampai ia meminta sendiri untuk dimasukkan karena Anda tidak ingin terkesan memaksakan", "Menanyakan kepada rekan itu apakah ia membutuhkan akses atau informasi tambahan dari grup", "Mengajaknya bergabung dan memastikan informasi tim sampai kepadanya", "Melaporkannya sebagai anggota yang pasif karena tidak pernah terlihat aktif berdiskusi di grup", "Membiarkannya karena mungkin ada alasan tertentu sehingga ia memang tidak perlu berada dalam grup"], ans: 2, skor: [3, 4, 5, 1, 2], bahas: "Inklusi dalam tim memperkuat kerja sama." },
  { id: "tkp-jej-027", topik: "TKP Jejaring Kerja", level: 3, q: "Mitra meminta data internal yang sensitif untuk keperluan kerja sama. Anda...", opts: ["Menolak tanpa menjelaskan apa pun karena merasa data seperti itu pasti tidak boleh diberikan dan menganggap persoalannya selesai begitu saja", "Menanyakan alasan dan batas penggunaan data itu lalu meneruskan permintaan kepada atasan Anda", "Memberikan sebagian data yang menurut Anda tidak terlalu penting agar mitra tidak merasa dipersulit", "Menyampaikan bahwa pemberian data harus melalui persetujuan atasan dan perjanjian yang jelas, lalu mengurus prosedurnya bersama mitra", "Memberikan seluruh data lewat pesan pribadi karena sudah percaya sepenuhnya kepada mitra tersebut"], ans: 3, skor: [2, 4, 3, 5, 1], bahas: "Data sensitif hanya dengan izin dan dasar yang sah." },
  { id: "tkp-jej-028", topik: "TKP Jejaring Kerja", level: 3, q: "Tim terpecah menjadi dua kubu karena perbedaan metode kerja. Anda...", opts: ["Memilih bergabung dengan kubu yang lebih kuat karena lebih besar kemungkinan metodenya yang akan dipakai", "Menunggu atasan turun tangan karena merasa keputusan ini bukan wewenang anggota biasa seperti Anda", "Mengundurkan diri dari tim supaya tidak terseret konflik yang berkepanjangan di antara kedua kubu", "Mengajak kedua kubu menyepakati tujuan yang sama, membandingkan metode dengan data, dan mencoba gabungan yang terbaik", "Mengusulkan uji coba kedua metode secara terbatas lalu menilai hasilnya bersama-sama"], ans: 3, skor: [2, 3, 1, 5, 4], bahas: "Tujuan bersama dan data menyatukan perbedaan metode." },
  { id: "tkp-jej-029", topik: "TKP Jejaring Kerja", level: 1, q: "Anda butuh bantuan tetapi merasa gengsi bertanya. Anda...", opts: ["Bertanya kepada rekan yang lebih paham, lalu menerapkannya dan berterima kasih", "Menyalin pekerjaan orang lain tanpa bertanya agar tidak ketahuan belum memahami caranya", "Mencari panduan atau contoh pekerjaan sebelumnya lalu menanyakan bagian yang masih belum dipahami", "Mengerjakan sendiri meski lama dan hasilnya meragukan karena tidak ingin terlihat kurang mampu", "Menunda pekerjaan itu sampai ada orang yang menawarkan bantuan dengan sendirinya kepada Anda"], ans: 0, skor: [5, 1, 4, 3, 2], bahas: "Meminta bantuan tepat waktu menunjukkan profesionalitas." },
  { id: "tkp-jej-030", topik: "TKP Jejaring Kerja", level: 2, q: "Penghargaan diberikan hanya kepada Anda padahal hasil itu karya tim. Anda...", opts: ["Mengaku bahwa hasil itu sepenuhnya berkat kerja keras Anda karena memang Anda yang memimpin tim", "Menerima sambil menyebut kontribusi seluruh tim, lalu membagikan apresiasi kepada mereka", "Menolak penghargaan di depan umum dengan marah supaya semua orang tahu betapa tidak adilnya hal ini", "Menerimanya tanpa komentar karena Anda tidak ingin merusak suasana acara penyerahan penghargaan", "Menerima penghargaan itu dan mengusulkan kepada atasan agar tim mendapat pengakuan yang sama"], ans: 1, skor: [2, 5, 1, 3, 4], bahas: "Mengakui kerja tim membangun kepercayaan." },
  { id: "tkp-jej-031", topik: "TKP Jejaring Kerja", level: 1, q: "Anda baru bergabung di tim lintas instansi dan belum mengenal siapa pun. Anda...", opts: ["Menunggu orang lain yang menyapa lebih dulu karena Anda tidak terbiasa memulai percakapan dengan orang asing", "Mengamati cara kerja tim selama beberapa minggu dulu sebelum mulai ikut berbicara di setiap pertemuan", "Menanyakan kepada koordinator siapa saja yang perlu Anda temui lebih dulu dan apa harapan terhadap peran Anda", "Mengerjakan tugas sendiri tanpa berinteraksi agar tidak mengganggu pekerjaan anggota tim yang lain", "Memperkenalkan diri kepada anggota, menanyakan peran masing-masing, dan menawarkan bantuan pada tugas yang tersedia"], ans: 4, skor: [2, 3, 4, 1, 5], bahas: "Proaktif membangun relasi mempercepat adaptasi." },
  { id: "tkp-jej-032", topik: "TKP Jejaring Kerja", level: 2, q: "Rapat koordinasi dikuasai satu orang yang terlalu dominan. Anda...", opts: ["Mengusulkan giliran bicara agar semua peserta dapat menyampaikan pendapat", "Membiarkan karena orang dominan itu biasanya memang punya banyak ide dan pengalaman di bidang ini", "Menyela pembicaraan orang itu berulang kali agar Anda bisa mendapat kesempatan bicara juga di rapat", "Diam sampai rapat selesai lalu mengeluhkannya kepada rekan-rekan lain di luar ruangan nanti", "Menyampaikan kepada pimpinan rapat secara sopan bahwa beberapa peserta belum sempat menyampaikan pendapatnya"], ans: 0, skor: [5, 3, 2, 1, 4], bahas: "Forum yang sehat memberi kesempatan setara." },
  { id: "tkp-jej-033", topik: "TKP Jejaring Kerja", level: 2, q: "Mitra meminta perubahan jadwal kegiatan secara mendadak. Anda...", opts: ["Menyetujui langsung tanpa memeriksa karena Anda tidak ingin hubungan kerja sama menjadi renggang", "Menolak permintaan itu dengan tegas karena jadwal awal sudah disepakati bersama sejak lama", "Mengonfirmasi bahwa Anda akan memeriksa dulu ketersediaan tim lalu memberi jawaban secepatnya hari ini", "Menyerahkan keputusan kepada atasan tanpa memberi masukan apa pun mengenai kondisi tim di lapangan", "Menanyakan alasannya, mengecek dampaknya, lalu menegosiasikan jadwal baru yang realistis"], ans: 4, skor: [3, 2, 4, 1, 5], bahas: "Fleksibel namun realistis menjaga kemitraan." },
  { id: "tkp-jej-034", topik: "TKP Jejaring Kerja", level: 3, q: "Tim lain menolak berbagi data karena persaingan antarunit. Anda...", opts: ["Mencari data pengganti dari sumber lain walaupun hasilnya mungkin kurang lengkap untuk kebutuhan Anda", "Membalas dengan menolak berbagi data milik unit Anda agar dianggap setimpal dan tidak dirugikan", "Menjelaskan tujuan bersama dan manfaat berbagi data bagi kedua unit, lalu menawarkan kesepakatan penggunaan data yang jelas", "Meminta atasan masing-masing unit membuat kesepakatan tertulis tentang pertukaran data yang diperlukan", "Menyebarkan keluhan tentang tim itu kepada unit-unit lain supaya mereka ikut menekannya meskipun belum yakin dampaknya bagi orang lain"], ans: 2, skor: [3, 2, 5, 4, 1], bahas: "Persaingan sehat tidak boleh menghalangi tujuan organisasi." },
  { id: "tkp-jej-035", topik: "TKP Jejaring Kerja", level: 1, q: "Anda diminta mewakili kantor dalam acara komunitas pada akhir pekan. Anda...", opts: ["Menyanggupi tetapi tidak hadir karena pada akhirnya Anda merasa terlalu lelah setelah seminggu bekerja", "Mengirim rekan lain tanpa memberi tahu atasan karena Anda memiliki urusan keluarga pada hari itu", "Menyanggupi bila memungkinkan, menyiapkan bahan, dan melaporkan hasilnya kepada atasan setelah acara", "Menolak karena itu hari libur Anda dan tidak ada kewajiban untuk hadir pada akhir pekan", "Menanyakan kepada atasan apakah ada penggantian waktu lalu mempersiapkan diri sebaik mungkin"], ans: 2, skor: [1, 2, 5, 3, 4], bahas: "Representasi kantor menuntut komitmen dan pelaporan." },
  { id: "tkp-jej-036", topik: "TKP Jejaring Kerja", level: 2, q: "Seorang rekan di unit lain sakit dan tugasnya perlu diteruskan. Anda...", opts: ["Menyarankan agar pekerjaan itu ditunda sampai rekan tersebut sembuh dan kembali bekerja seperti biasa", "Mengabaikannya karena tugas itu sepenuhnya menjadi tanggung jawab unit rekan Anda yang sedang sakit", "Menawarkan bantuan sementara dan memastikan informasi tugas diserahkan dengan jelas", "Menanyakan kepada atasan rekan itu bagian mana yang paling mendesak dan bisa Anda bantu kerjakan", "Menunggu sampai ada permintaan resmi karena tidak ingin dianggap mencampuri pekerjaan unit lain"], ans: 2, skor: [2, 1, 5, 4, 3], bahas: "Kolaborasi menjaga kesinambungan layanan." },
  { id: "tkp-jej-037", topik: "TKP Jejaring Kerja", level: 2, q: "Atasan memerintahkan Anda menghubungi pejabat instansi lain yang tidak Anda kenal. Anda...", opts: ["Meminta rekan yang pernah berhubungan dengan pejabat itu untuk memperkenalkan Anda lebih dulu", "Menunda sampai ada kesempatan bertemu langsung agar tidak terkesan lancang kepada pejabat tersebut", "Mengirim surat resmi saja karena merasa lebih aman daripada berbicara langsung dengan orang yang belum dikenal", "Meminta atasan menghubunginya sendiri karena Anda merasa kurang pantas berbicara dengan pejabat sekelas itu", "Mencari tahu perannya, menyiapkan poin pembicaraan, lalu menghubunginya dengan sopan"], ans: 4, skor: [4, 2, 3, 1, 5], bahas: "Persiapan membuat komunikasi lintas instansi efektif." },
  { id: "tkp-jej-038", topik: "TKP Jejaring Kerja", level: 2, q: "Seorang rekan sering menyela dan meremehkan pendapat Anda. Anda...", opts: ["Membiarkannya karena Anda tidak ingin memperpanjang urusan dan berharap ia berubah dengan sendirinya", "Menyampaikan dengan tenang bahwa Anda ingin menyelesaikan pendapat, lalu melanjutkan dengan data", "Membalas dengan meremehkan pendapat rekan itu juga agar ia merasakan bagaimana rasanya diperlakukan begitu", "Berhenti menyampaikan pendapat di rapat supaya tidak lagi mengalami perlakuan seperti itu", "Berbicara dengan rekan itu secara pribadi setelah rapat untuk membahas cara berdiskusi yang lebih baik"], ans: 1, skor: [3, 5, 2, 1, 4], bahas: "Tegas dan santun menjaga forum tetap sehat." },
  { id: "tkp-jej-039", topik: "TKP Jejaring Kerja", level: 3, q: "Dua kolega meminta Anda memihak dalam perselisihan mereka. Anda...", opts: ["Menyampaikan bahwa Anda tidak memihak, mendengarkan keduanya secara adil, dan mendorong mereka berdialog langsung", "Menawarkan diri menjadi penengah dengan syarat keduanya bersedia mendengarkan satu sama lain secara tenang", "Memihak kolega yang lebih lama Anda kenal karena merasa lebih bisa mempercayai ceritanya", "Menyarankan keduanya menyelesaikan sendiri dan meminta Anda tidak dilibatkan karena tidak mau repot", "Memberi tahu masing-masing bahwa Anda setuju dengannya agar keduanya tidak marah kepada Anda tanpa memikirkan akibat jangka panjangnya"], ans: 0, skor: [5, 4, 2, 3, 1], bahas: "Netralitas menjaga kepercayaan dua belah pihak." },
  { id: "tkp-jej-040", topik: "TKP Jejaring Kerja", level: 2, q: "Mitra eksternal mengkritik unit Anda di depan umum. Anda...", opts: ["Membalas lewat media sosial agar publik mengetahui sisi cerita dari pihak unit Anda", "Mengucapkan terima kasih atas masukan itu dan berjanji menindaklanjutinya setelah berkoordinasi dengan tim", "Membela diri di tempat itu juga dengan menunjukkan kekurangan pihak mitra yang selama ini terjadi", "Mendengarkan kritik itu dengan tenang dan menawarkan pertemuan untuk membahas solusinya", "Diam dan meninggalkan acara lebih cepat agar tidak terlibat perdebatan terbuka di depan banyak orang"], ans: 3, skor: [1, 4, 3, 5, 2], bahas: "Kritik publik ditanggapi tenang dan solutif." },
  { id: "tkp-jej-041", topik: "TKP Jejaring Kerja", level: 1, q: "Tim Anda dibantu unit lain pada sebuah pekerjaan, tetapi tidak ada ucapan terima kasih. Anda...", opts: ["Berharap mereka memahami sendiri rasa terima kasih Anda tanpa perlu diucapkan secara langsung", "Menyampaikan terima kasih secara resmi kepada unit itu dan menyebut kontribusinya dalam laporan", "Membiarkannya karena semua bantuan memang sudah menjadi bagian dari kewajiban kerja sama antarunit", "Mengirim pesan apresiasi kepada rekan yang membantu dan mengabarkannya kepada atasan mereka", "Menceritakan kepada rekan lain bahwa bantuan unit itu tidak seberapa dibandingkan hasil kerja tim Anda"], ans: 1, skor: [2, 5, 3, 4, 1], bahas: "Apresiasi memperkuat jejaring kerja." },
  { id: "tkp-jej-042", topik: "TKP Jejaring Kerja", level: 2, q: "Proyek bersama terlambat karena satu unit bekerja lambat. Anda...", opts: ["Mengumumkan di rapat bahwa unit itu penyebab keterlambatan agar semua orang mengetahuinya", "Menanyakan kendala unit itu dan menawarkan bantuan atau penyesuaian jadwal bersama", "Mengerjakan bagian unit itu diam-diam agar proyek tetap selesai tanpa memberi tahu siapa pun", "Menyampaikan dampak keterlambatan kepada koordinator proyek disertai usulan percepatan yang realistis", "Menunggu sampai unit itu menyelesaikan bagiannya karena tidak ada yang bisa Anda lakukan untuk mempercepat"], ans: 1, skor: [2, 5, 3, 4, 1], bahas: "Selesaikan hambatan dengan komunikasi dan solusi." },
  { id: "tkp-jej-043", topik: "TKP Jejaring Kerja", level: 1, q: "Anda perlu meminjam alat dari unit lain yang sedang dipakai. Anda...", opts: ["Membatalkan pekerjaan yang membutuhkan alat itu tanpa menyampaikan kendalanya kepada atasan", "Meminta izin penanggung jawab alat dan menyampaikan kebutuhan serta lama waktu peminjaman", "Mengambil alat itu saat petugasnya sedang tidak ada karena sebentar saja dan akan segera dikembalikan", "Mencari alat serupa dari unit lain tanpa memberi tahu unit yang pertama agar tidak perlu menunggu", "Menanyakan kapan alat selesai dipakai, lalu membuat kesepakatan jadwal peminjaman yang jelas"], ans: 4, skor: [1, 4, 3, 2, 5], bahas: "Koordinasi peminjaman menjaga hubungan antarunit." },
  { id: "tkp-jej-044", topik: "TKP Jejaring Kerja", level: 2, q: "Dalam rapat daring, mikrofon peserta bising dan sering terputus. Anda...", opts: ["Mengusulkan penggunaan kolom obrolan untuk poin penting agar tidak ada informasi yang terlewat", "Menegur peserta itu dengan nada kesal di forum agar semua orang tahu gangguannya tanpa memikirkan akibat jangka panjangnya", "Membiarkan gangguan itu sampai rapat selesai karena Anda tidak ingin mengoreksi peserta lain", "Meninggalkan rapat lebih cepat karena merasa gangguan itu membuat rapat tidak efektif", "Mengingatkan dengan sopan agar mikrofon dimatikan saat tidak berbicara dan menawarkan alternatif"], ans: 4, skor: [4, 1, 3, 2, 5], bahas: "Tata krama rapat daring perlu dijaga dengan santun." },
  { id: "tkp-jej-045", topik: "TKP Jejaring Kerja", level: 3, q: "Rekan dari unit lain meminta Anda menyampaikan pesan yang sulit kepada atasannya. Anda...", opts: ["Menyampaikan pesan itu apa adanya kepada atasannya karena Anda sudah terlanjur berjanji membantu", "Menanyakan isi pesan itu lalu membantu menyusun kalimat yang sopan agar rekan sendiri yang menyampaikannya", "Menyampaikan pesan itu dengan menambahkan pendapat pribadi Anda agar atasannya lebih cepat bereaksi", "Menyarankan rekan menyampaikannya sendiri dengan baik, dan menawarkan mendampingi atau memberi masukan cara menyampaikannya", "Menolak membantu dengan alasan bukan urusan Anda dan tidak mau terseret persoalan unit lain"], ans: 3, skor: [3, 4, 1, 5, 2], bahas: "Pesan sulit sebaiknya disampaikan langsung oleh pemiliknya." },
  { id: "tkp-jej-046", topik: "TKP Jejaring Kerja", level: 2, q: "Anda mengetahui rencana kegiatan unit lain bertabrakan dengan kegiatan unit Anda. Anda...", opts: ["Menghubungi unit itu, memeriksa jadwal bersama, dan mengatur ulang agar tidak bentrok", "Memberi tahu atasan lalu mengusulkan pertemuan singkat dua unit untuk menyelaraskan agenda", "Menunggu sampai kegiatan berdekatan baru membahasnya karena jadwal masih bisa berubah sewaktu-waktu", "Membiarkan bentrokan itu karena menganggap sumber daya masing-masing unit pasti mencukupi", "Mengubah jadwal unit Anda sendiri tanpa memberi tahu unit lain agar urusan cepat selesai"], ans: 0, skor: [5, 4, 3, 1, 2], bahas: "Koordinasi dini mencegah bentrokan jadwal." },
  { id: "tkp-jej-047", topik: "TKP Jejaring Kerja", level: 1, q: "Anda diminta memperkenalkan diri dan membangun relasi di sebuah acara jejaring. Anda...", opts: ["Menyapa beberapa peserta yang bidangnya berhubungan dengan pekerjaan Anda dan mencatat nama mereka", "Datang sebentar untuk absen lalu pulang karena merasa acara seperti ini tidak penting tanpa memikirkan akibat jangka panjangnya", "Menyiapkan perkenalan singkat tentang peran Anda, lalu bertukar kontak dan menindaklanjuti dengan pesan setelah acara", "Membagikan kartu nama sebanyak-banyaknya tanpa berbicara agar terlihat sudah berjejaring dengan banyak orang", "Menunggu dihampiri orang lain karena Anda lebih nyaman menjadi pendengar dalam setiap pertemuan"], ans: 2, skor: [4, 1, 5, 2, 3], bahas: "Relasi dibangun dengan interaksi yang bermakna." },
  { id: "tkp-jej-048", topik: "TKP Jejaring Kerja", level: 2, q: "Mitra meminta bantuan di luar kesepakatan kerja sama. Anda...", opts: ["Menolak tanpa penjelasan karena permintaan itu jelas bukan bagian dari kesepakatan awal kerja sama", "Menyanggupi langsung agar hubungan baik terjaga walaupun belum tahu apakah kantor mengizinkannya", "Membantu secara diam-diam di luar jam kerja tanpa memberi tahu atasan agar urusan tidak rumit", "Menilai permintaannya, lalu membahas dengan atasan sebelum menyanggupi atau menolak", "Menjelaskan batas kesepakatan yang ada dan menawarkan membahas perluasan kerja sama secara resmi"], ans: 3, skor: [2, 3, 1, 5, 4], bahas: "Permintaan di luar kesepakatan perlu persetujuan resmi." },
  { id: "tkp-jej-049", topik: "TKP Jejaring Kerja", level: 2, q: "Anggota tim baru berbeda generasi dan cara kerjanya. Anda...", opts: ["Mengajaknya berdiskusi tentang cara kerja yang disukai lalu membuat kesepakatan kerja bersama", "Meminta ia mengikuti cara lama yang sudah biasa dipakai tim karena sudah terbukti berjalan baik", "Menilai cara kerjanya kurang sopan dan menceritakannya kepada rekan lain agar ada yang menegurnya", "Menghargai perbedaan itu, menyepakati cara berkomunikasi, dan memanfaatkan kelebihan masing-masing", "Membiarkan ia bekerja dengan caranya sendiri tanpa mencoba memahami apa yang ia butuhkan dari tim"], ans: 3, skor: [4, 2, 1, 5, 3], bahas: "Keberagaman generasi memperkaya tim." },
  { id: "tkp-jej-050", topik: "TKP Jejaring Kerja", level: 3, q: "Hasil rapat lintas unit tidak ditindaklanjuti siapa pun. Anda...", opts: ["Menyusun notulen dengan pembagian tugas dan tenggat, lalu mengirimkannya serta memantau tindak lanjutnya secara berkala", "Menunggu salah satu unit mengambil inisiatif karena Anda merasa bukan pihak yang bertanggung jawab tanpa memikirkan akibat jangka panjangnya", "Menganggap rapat itu hanya formalitas sehingga tidak perlu lagi dipikirkan setelah selesai", "Mengingatkan para peserta lewat pesan tentang tugas masing-masing dan menawarkan membantu bila ada hambatan", "Menyalahkan pimpinan rapat yang tidak membagi tugas dengan jelas dan menceritakannya kepada rekan lain"], ans: 0, skor: [5, 3, 1, 4, 2], bahas: "Tindak lanjut membuat koordinasi bermakna." },
  { id: "tkp-sos-001", topik: "TKP Sosial Budaya", level: 1, q: "Seorang rekan berbeda agama sedang beribadah saat rapat akan dimulai. Anda...", opts: ["Memulai rapat tanpa menunggu karena jadwal sudah ditetapkan dan peserta lain sudah hadir semua", "Mengusulkan rapat dimulai beberapa menit lebih lambat dan menyampaikannya kepada peserta lain", "Memberi waktu dan menyesuaikan jadwal rapat dengan wajar agar rekan dapat beribadah dengan tenang", "Menertawakan kebiasaan ibadahnya bersama rekan lain karena menurut Anda terlalu memakan waktu", "Menegur rekan itu agar beribadah di luar jam kerja supaya tidak mengganggu agenda rapat sesuai kebiasaan yang selama ini Anda jalani"], ans: 2, skor: [3, 4, 5, 1, 2], bahas: "Menghormati ibadah adalah wujud toleransi dan menjaga kebersamaan." },
  { id: "tkp-sos-002", topik: "TKP Sosial Budaya", level: 2, q: "Anda dipindah tugas ke daerah dengan adat yang sangat berbeda. Anda...", opts: ["Mengeluh kepada rekan tentang betapa anehnya kebiasaan di daerah baru itu setiap ada kesempatan", "Mempelajari adat setempat dan menyesuaikan diri tanpa melanggar aturan", "Tetap memakai kebiasaan lama Anda karena menurut Anda cara itu sudah terbukti baik dan benar", "Meminta dipindahkan kembali ke daerah asal karena merasa sulit menyesuaikan diri dengan lingkungan baru", "Bertanya kepada tokoh dan rekan setempat tentang kebiasaan yang perlu diperhatikan lalu mencatatnya baik-baik"], ans: 1, skor: [2, 5, 3, 1, 4], bahas: "Adaptasi budaya mempermudah penerimaan dan efektivitas kerja." },
  { id: "tkp-sos-003", topik: "TKP Sosial Budaya", level: 1, q: "Warga lokal memiliki tradisi yang tidak Anda pahami. Anda...", opts: ["Mengkritik tradisi itu di depan umum agar warga mau meninggalkannya dan mengikuti cara yang lebih modern", "Menghindari acara tradisi itu karena khawatir melakukan kesalahan di depan banyak orang yang hadir", "Menganggap tradisi itu kuno dan membicarakannya sebagai bahan candaan bersama rekan pendatang lainnya", "Menyaksikan tradisi itu dengan sopan lalu bertanya makna dan tata caranya kepada warga yang mengerti", "Bertanya dengan hormat tentang makna tradisi tersebut dan ikut berpartisipasi sewajarnya"], ans: 4, skor: [1, 3, 2, 4, 5], bahas: "Rasa ingin tahu yang menghormati memperkuat hubungan sosial." },
  { id: "tkp-sos-004", topik: "TKP Sosial Budaya", level: 2, q: "Seorang rekan bercanda merendahkan suku tertentu di ruang kerja. Anda...", opts: ["Menegur dengan sopan bahwa candaan itu menyinggung dan mengajak menjaga ucapan", "Diam saja agar suasana tidak menjadi canggung walaupun dalam hati Anda tidak setuju dengan candaan itu", "Membalas dengan candaan merendahkan suku rekan itu supaya ia merasakan bagaimana rasanya diejek", "Mengalihkan topik pembicaraan dengan ramah lalu menyampaikan keberatan secara pribadi setelahnya", "Ikut tertawa agar tidak dianggap terlalu serius atau tidak bisa diajak bercanda oleh rekan-rekan"], ans: 0, skor: [5, 3, 1, 4, 2], bahas: "Menjaga lingkungan kerja yang inklusif dengan menegur secara santun." },
  { id: "tkp-sos-005", topik: "TKP Sosial Budaya", level: 1, q: "Kantor mengadakan acara bertepatan dengan hari besar agama seorang rekan. Anda...", opts: ["Mencatat siapa saja yang tidak hadir untuk dilaporkan kepada atasan sebagai bentuk ketidakdisiplinan", "Mengusulkan penjadwalan ulang atau penyesuaian agar semua rekan dapat hadir dengan nyaman", "Menanyakan kepada rekan itu apakah ia dapat hadir lalu menyampaikan masukannya kepada panitia", "Tetap menyelenggarakan acara tanpa berdiskusi karena sulit menyesuaikan dengan semua hari besar yang ada", "Meminta rekan itu mengajukan izin tidak hadir karena acara sudah terlanjur dijadwalkan sejak lama"], ans: 1, skor: [1, 5, 4, 2, 3], bahas: "Kepekaan pada perbedaan agama menjaga keharmonisan." },
  { id: "tkp-sos-006", topik: "TKP Sosial Budaya", level: 3, q: "Warga adat menolak aturan baru yang Anda sosialisasikan. Anda...", opts: ["Menghentikan sosialisasi sampai warga bersedia mendengarkan penjelasan Anda dengan sikap yang lebih tenang", "Menyerahkan penanganannya kepada aparat keamanan agar aturan tetap berlaku di wilayah tersebut tanpa penundaan", "Mendengarkan alasan mereka, melibatkan tokoh adat, dan mencari penyesuaian pelaksanaan yang tetap sesuai hukum", "Memaksa aturan itu berlaku saat itu juga karena sudah ditetapkan dan semua warga wajib menaatinya", "Mengajak tokoh adat berdialog dan mencatat keberatan warga untuk disampaikan kepada pembuat kebijakan"], ans: 2, skor: [3, 2, 5, 1, 4], bahas: "Pendekatan dialogis dan melibatkan tokoh meningkatkan penerimaan aturan." },
  { id: "tkp-sos-007", topik: "TKP Sosial Budaya", level: 1, q: "Rekan berbicara bahasa daerah yang tidak Anda mengerti di ruang kerja. Anda...", opts: ["Bertanya dengan ramah tentang arti beberapa ungkapan lalu ikut belajar kata-kata sederhana darinya", "Menganggap ia sedang membicarakan Anda dan menegurnya agar berbicara dengan bahasa yang dipahami semua orang", "Mengabaikannya dan melanjutkan pekerjaan karena percakapan itu tidak ada hubungannya dengan tugas Anda", "Melarangnya memakai bahasa daerah di kantor supaya tidak ada yang merasa dikucilkan dari pembicaraan", "Meminta ia menerjemahkan jika diperlukan dan memahami bahwa itu bagian dari identitasnya"], ans: 4, skor: [4, 2, 3, 1, 5], bahas: "Bahasa daerah adalah kekayaan budaya yang patut dihargai." },
  { id: "tkp-sos-008", topik: "TKP Sosial Budaya", level: 2, q: "Seorang rekan berkebutuhan khusus bergabung dalam tim Anda. Anda...", opts: ["Memberinya tugas minimal saja karena khawatir ia kesulitan dan tidak ingin membebani dirinya", "Menanyakan bantuan apa yang ia butuhkan lalu menyesuaikan pembagian tugas agar sesuai kemampuannya", "Membantunya secara berlebihan di setiap hal kecil sehingga ia tidak diberi kesempatan mencoba sendiri", "Menghindari ia dalam pekerjaan tim karena tidak tahu bagaimana cara berkomunikasi dengannya", "Memahami kebutuhannya, menyesuaikan cara kerja, dan memberi kesempatan berkontribusi"], ans: 4, skor: [3, 4, 2, 1, 5], bahas: "Inklusi berarti menyediakan kesempatan yang setara." },
  { id: "tkp-sos-009", topik: "TKP Sosial Budaya", level: 1, q: "Hidangan acara kantor tidak sesuai dengan pantangan seorang rekan. Anda...", opts: ["Menyiapkan makanan tambahan yang aman untuk rekan itu setelah menanyakan jenis pantangannya dengan sopan", "Menyuruhnya makan seadanya saja karena menu sudah dipesan dan tidak mungkin diganti lagi hari ini", "Menyebut permintaannya merepotkan di depan rekan lain karena panitia sudah bekerja keras menyiapkan acara", "Meminta rekan itu membawa bekal sendiri pada acara-acara berikutnya agar tidak menyulitkan panitia kegiatan", "Mengusulkan menu alternatif dan memastikan rekan itu terlayani dengan baik pada acara tersebut"], ans: 4, skor: [4, 2, 1, 3, 5], bahas: "Menghormati keyakinan dan kebutuhan setiap orang." },
  { id: "tkp-sos-010", topik: "TKP Sosial Budaya", level: 1, q: "Ada kerja bakti warga pada hari libur Anda. Anda...", opts: ["Datang membawa peralatan yang dibutuhkan lalu membantu sampai kegiatan selesai bersama warga lain", "Mengirim uang pengganti tanpa hadir karena hari libur ingin Anda manfaatkan untuk beristirahat di rumah", "Datang sebentar untuk menunjukkan kehadiran lalu pulang sebelum pekerjaan utama dimulai oleh warga", "Menyuruh orang lain menggantikan Anda karena merasa sudah cukup lelah setelah bekerja seminggu penuh", "Ikut berpartisipasi aktif dan mengajak anggota keluarga"], ans: 4, skor: [4, 3, 2, 1, 5], bahas: "Gotong royong memperkuat kohesi sosial." },
  { id: "tkp-sos-011", topik: "TKP Sosial Budaya", level: 2, q: "Tetangga baru dari etnis berbeda diperlakukan dingin oleh warga. Anda...", opts: ["Menyapa, memperkenalkan diri, dan mengajaknya bergabung dalam kegiatan lingkungan", "Mengantarkan makanan kecil sebagai tanda perkenalan lalu mengundangnya ke pertemuan warga berikutnya", "Membicarakannya di grup warga untuk mengetahui bagaimana pendapat tetangga lain tentang pendatang baru itu", "Ikut menjauhinya karena tidak ingin berbeda sikap dari tetangga lain di lingkungan ini", "Menunggu ia menyapa lebih dulu karena Anda tidak ingin dianggap terlalu mencampuri urusan orang lain"], ans: 0, skor: [5, 4, 2, 1, 3], bahas: "Inisiatif ramah menjembatani perbedaan dan mencegah pengucilan." },
  { id: "tkp-sos-012", topik: "TKP Sosial Budaya", level: 2, q: "Rekan perempuan berkali-kali dipotong bicaranya saat rapat. Anda...", opts: ["Menganggapnya wajar karena dalam rapat memang sering terjadi saling menyela antara peserta", "Ikut memotong pembicaraan karena merasa pendapat Anda juga perlu segera disampaikan sebelum rapat usai", "Menyampaikan keberatan kepada rekan yang memotong secara pribadi setelah rapat selesai nanti", "Mengingatkan forum agar semua mendapat giliran bicara, lalu memberi ruang bagi rekan itu", "Menyampaikan kepada pimpinan rapat setelahnya agar mengatur giliran bicara yang lebih adil bagi semua"], ans: 3, skor: [2, 1, 3, 5, 4], bahas: "Keadilan gender menuntut kesempatan berpendapat yang setara." },
  { id: "tkp-sos-013", topik: "TKP Sosial Budaya", level: 1, q: "Anda menemukan kebiasaan lokal yang tampak aneh bagi Anda. Anda...", opts: ["Berusaha mengubahnya karena menurut Anda cara yang lebih modern pasti lebih baik bagi seluruh warga", "Menertawakannya di depan rekan pendatang sebagai bahan cerita lucu tentang daerah yang baru Anda tempati", "Mencari tahu latar belakangnya dan menghormatinya selama tidak melanggar hukum", "Bertanya kepada warga yang mengerti tentang maknanya lalu mencatatnya sebagai bahan belajar", "Menjauhinya karena merasa tidak nyaman dan tidak yakin harus bersikap bagaimana terhadap kebiasaan itu"], ans: 2, skor: [1, 2, 5, 4, 3], bahas: "Keberagaman dipahami lewat belajar, bukan menghakimi." },
  { id: "tkp-sos-014", topik: "TKP Sosial Budaya", level: 2, q: "Perayaan budaya daerah menutup jalan dan mengganggu jam kerja Anda. Anda...", opts: ["Mengeluh kepada rekan tentang betapa mengganggunya perayaan itu bagi aktivitas orang yang bekerja", "Mencari tahu jam berakhirnya perayaan dan mengatur ulang rencana kerja Anda pada hari itu", "Menyesuaikan rute dan jadwal kerja serta menghormati kegiatan yang sedang berlangsung", "Tidak masuk kerja pada hari itu dengan alasan jalan tertutup tanpa memberi kabar kepada atasan", "Memprotes keras panitia agar jalan segera dibuka kembali supaya aktivitas kantor tidak terganggu"], ans: 2, skor: [3, 4, 5, 1, 2], bahas: "Perayaan budaya sah dan berlangsung singkat; sesuaikan diri dengan bijak." },
  { id: "tkp-sos-015", topik: "TKP Sosial Budaya", level: 3, q: "Rekan dari daerah lain dianggap kurang pintar oleh sebagian orang di kantor. Anda...", opts: ["Diam karena merasa bukan urusan Anda dan tidak ingin terlibat dalam pembicaraan yang tidak nyaman itu", "Menjauhinya demi aman agar Anda tidak ikut dianggap sebagai bagian dari kelompok yang dicibir", "Menegur dengan sopan rekan yang melontarkan anggapan itu dan meminta mereka menilai berdasarkan hasil kerja", "Menolak stereotip itu, menunjukkan kontribusinya, dan mengajak rekan lain bekerja sama dengannya", "Ikut mengejeknya agar diterima di antara rekan-rekan yang lebih dulu bekerja di unit ini sesuai kebiasaan yang selama ini Anda jalani"], ans: 3, skor: [3, 2, 4, 5, 1], bahas: "Melawan stereotip dengan fakta dan inklusi memperkuat persatuan." },
  { id: "tkp-sos-016", topik: "TKP Sosial Budaya", level: 2, q: "Seorang warga penganut kepercayaan lokal tidak ikut kegiatan yang bernuansa ibadah agama tertentu. Anda...", opts: ["Membiarkan ia tidak hadir tanpa mengajaknya karena tidak ingin menimbulkan perdebatan di antara warga", "Melaporkannya sebagai warga pembangkang kepada pengurus lingkungan agar mendapat teguran tertulis", "Memaksa ia ikut demi kekompakan karena semua warga lain sudah bersedia mengikuti kegiatan tersebut", "Menghormati pilihannya dan menyiapkan peran lain agar tetap terlibat dalam kebersamaan", "Menanyakan bentuk keterlibatan yang nyaman bagi dirinya lalu menyampaikannya kepada panitia kegiatan"], ans: 3, skor: [3, 1, 2, 5, 4], bahas: "Kebebasan berkeyakinan dihormati tanpa meniadakan kebersamaan." },
  { id: "tkp-sos-017", topik: "TKP Sosial Budaya", level: 1, q: "Rekan memakai pakaian adat daerahnya saat acara kantor. Anda...", opts: ["Memperhatikannya saja tanpa berkomentar karena tidak ingin dianggap terlalu mencampuri penampilan orang", "Mengapresiasi pakaiannya dan bertanya tentang makna di baliknya dengan hormat", "Menyuruhnya berganti pakaian biasa karena menurut Anda tidak sesuai dengan suasana kerja di kantor", "Memotretnya diam-diam untuk dijadikan bahan candaan di grup chat bersama teman-teman dekat", "Memuji pakaian itu lalu mengajak rekan lain mengenal budaya daerah rekan tersebut dalam acara santai"], ans: 1, skor: [3, 5, 2, 1, 4], bahas: "Keberagaman budaya adalah kekayaan bangsa." },
  { id: "tkp-sos-018", topik: "TKP Sosial Budaya", level: 2, q: "Seorang tamu dari daerah dengan etika berbeda menyapa dengan cara yang terasa janggal bagi Anda. Anda...", opts: ["Menirukan cara sapaannya dengan maksud menyindir di hadapan rekan lain agar suasana menjadi lucu", "Menegurnya karena dianggap tidak sopan menurut kebiasaan di daerah tempat Anda tinggal sekarang", "Memahami bahwa etika tiap daerah berbeda dan menanggapi dengan ramah", "Menyesuaikan sapaan dengan cara yang membuat tamu nyaman setelah memperhatikan kebiasaannya sejenak", "Menjaga jarak dari tamu itu karena Anda khawatir salah bersikap dan menimbulkan salah paham"], ans: 2, skor: [1, 2, 5, 4, 3], bahas: "Pahami konteks budaya sebelum menilai." },
  { id: "tkp-sos-019", topik: "TKP Sosial Budaya", level: 2, q: "Menjelang hari raya, rekan yang merayakan meminta cuti sementara Anda yang tidak merayakan tidak libur. Anda...", opts: ["Melapor kepada atasan agar rekan itu tidak jadi cuti supaya Anda tidak perlu menggantikan tugasnya", "Mengeluh bahwa pembagian cuti tidak adil lalu menolak menggantikan tugas rekan yang sedang berhari raya", "Bersedia menggantikan sebagian tugas dan meminta pembagian yang adil di kesempatan lain", "Menerima pergantian itu sambil menyindir bahwa Anda selalu diminta mengalah dalam urusan seperti ini", "Menyampaikan kesediaan membantu dengan syarat jadwal pengganti dibuat jelas dan tertulis bagi semua orang"], ans: 2, skor: [1, 2, 5, 3, 4], bahas: "Toleransi diwujudkan dengan saling menggantikan secara adil." },
  { id: "tkp-sos-020", topik: "TKP Sosial Budaya", level: 3, q: "Terjadi perselisihan antarkelompok pemuda di lingkungan Anda. Anda...", opts: ["Memihak kelompok yang Anda kenal baik karena merasa mereka berada di pihak yang benar dalam masalah ini", "Menutup pintu rumah dan menunggu keadaan mereda karena khawatir ikut terseret dalam perselisihan itu", "Melerai, mengajak tokoh masyarakat memfasilitasi dialog, dan tidak menyebarkan kabar yang memanaskan keadaan", "Merekam kejadian itu lalu mengunggahnya agar banyak orang tahu siapa yang memulai keributan di lingkungan", "Menenangkan pihak yang paling emosi lalu memanggil ketua lingkungan untuk membantu menyelesaikan masalah"], ans: 2, skor: [2, 3, 5, 1, 4], bahas: "Redakan konflik lewat dialog dan tokoh masyarakat." },
  { id: "tkp-sos-021", topik: "TKP Sosial Budaya", level: 1, q: "Tetangga mengadakan hajatan hingga larut malam sehingga Anda terganggu. Anda...", opts: ["Memutar musik keras sebagai balasan agar tetangga merasakan bagaimana terganggunya Anda malam ini", "Melapor kepada polisi malam itu juga agar acara segera dihentikan dan suasana kembali tenang", "Memaklumi karena hanya sesekali, dan bila perlu menyampaikan dengan baik agar mengatur volume suara", "Menyampaikan keberatan dengan sopan kepada keluarga penyelenggara setelah acara selesai agar lain kali lebih diperhatikan", "Menutup jendela dan menggunakan penyumbat telinga supaya tetap bisa beristirahat dengan tenang malam itu"], ans: 2, skor: [1, 2, 5, 4, 3], bahas: "Tenggang rasa dan komunikasi baik-baik." },
  { id: "tkp-sos-022", topik: "TKP Sosial Budaya", level: 2, q: "Rekan perempuan yang sedang hamil diminta lembur oleh atasan. Anda...", opts: ["Mengejek rekan itu sebagai orang yang manja karena tidak mau lembur seperti rekan lainnya", "Menganggap itu urusan pribadi rekan tersebut dan tidak ikut campur karena merasa bukan tanggung jawab Anda", "Menyampaikan kepada atasan agar mempertimbangkan kondisinya dan mencari pembagian tugas yang sesuai", "Menawarkan diri membantu bagian pekerjaannya agar ia dapat pulang tepat waktu dengan aman dan nyaman", "Menyarankan rekan itu mengajukan cuti panjang saja supaya tugasnya bisa dialihkan kepada orang lain"], ans: 2, skor: [1, 3, 5, 4, 2], bahas: "Perhatikan kebutuhan khusus dan keadilan." },
  { id: "tkp-sos-023", topik: "TKP Sosial Budaya", level: 2, q: "Ketua RT meminta iuran untuk perayaan agama yang bukan agama Anda. Anda...", opts: ["Menanyakan peruntukannya, dan bila bersifat kemasyarakatan memberi sumbangan sukarela sewajarnya", "Menanyakan rincian kegiatan dan memberi sumbangan sukarela yang sesuai kemampuan jika kegiatan bersifat umum", "Menolak dengan marah karena merasa dipaksa mendukung kegiatan yang bertentangan dengan keyakinan Anda", "Menyebarkan keberatan Anda di grup warga agar warga lain tahu bahwa iuran itu tidak adil", "Menyampaikan bahwa Anda tidak bisa memberi karena kegiatan itu bukan bagian dari keyakinan Anda"], ans: 0, skor: [5, 4, 2, 1, 3], bahas: "Bijak menilai dan menjaga kerukunan." },
  { id: "tkp-sos-024", topik: "TKP Sosial Budaya", level: 3, q: "Rekan dari kelompok minoritas di kantor sering dikucilkan dalam percakapan makan siang. Anda...", opts: ["Membiarkan keadaan itu berjalan karena Anda tidak ingin merusak hubungan dengan kelompok yang lain", "Duduk bersamanya saat makan siang dan mengajak rekan lain bergabung agar suasana lebih cair", "Ikut mengucilkan agar diterima di lingkungan pertemanan kantor yang sudah terbentuk lebih dulu", "Mengajaknya bergabung, memilih topik yang inklusif, dan menegur dengan baik sikap yang mengucilkan", "Menyalahkan rekan itu karena dianggap terlalu tertutup dan tidak berusaha menyesuaikan diri dengan kelompok"], ans: 3, skor: [3, 4, 1, 5, 2], bahas: "Lingkungan kerja inklusif dibangun dari sikap sehari-hari." },
  { id: "tkp-sos-025", topik: "TKP Sosial Budaya", level: 1, q: "Panggilan khas daerah yang biasa dipakai rekan terdengar kurang sopan bagi Anda. Anda...", opts: ["Menegur keras di depan rekan lain karena panggilan itu menurut Anda tidak pantas dipakai di kantor", "Membiarkannya saja dan menganggap itu bagian dari kebiasaan yang akan terbiasa dengan sendirinya nanti", "Menjelaskan dengan ramah panggilan yang Anda sukai tanpa menyalahkan kebiasaan di daerah rekan tersebut", "Bertanya dengan baik apa maksud panggilan itu dan menyampaikan bila Anda kurang nyaman", "Menjauhi rekan itu dan tidak lagi mau menanggapi sapaannya karena merasa tersinggung berkepanjangan"], ans: 3, skor: [2, 3, 4, 5, 1], bahas: "Klarifikasi santun mencegah salah paham budaya." },
  { id: "tkp-sos-026", topik: "TKP Sosial Budaya", level: 2, q: "Warga lansia menolak teknologi dan ingin urusannya dilayani dengan cara lama. Anda...", opts: ["Menyarankan keluarganya membantu mengurus melalui aplikasi karena sistem sekarang memang serba daring", "Melayani sesuai kebutuhannya sambil memperkenalkan cara baru secara perlahan dan sabar", "Menyediakan jalur manual untuknya dan menawarkan pendampingan bila suatu saat ia ingin mencoba aplikasi", "Menolak melayani dengan cara lama karena aturan baru mewajibkan semua urusan dilakukan lewat sistem", "Menertawakannya sebagai orang yang ketinggalan zaman di depan rekan-rekan yang sedang berada di sana"], ans: 1, skor: [3, 5, 4, 2, 1], bahas: "Layanan yang ramah lintas generasi." },
  { id: "tkp-sos-027", topik: "TKP Sosial Budaya", level: 3, q: "Pasangan beda suku akan menikah dan keluarga keberatan; Anda diminta menengahi. Anda...", opts: ["Menolak ikut campur karena urusan pernikahan adalah wilayah pribadi keluarga yang tidak boleh dicampuri orang luar", "Mengajak kedua keluarga bertemu dalam suasana santai dan membahas kekhawatiran masing-masing dengan tenang", "Mendengarkan kedua pihak, mengingatkan nilai persatuan, dan mendorong dialog dengan tokoh yang dihormati", "Menyalahkan pasangan itu karena tidak memikirkan perasaan keluarga sebelum memutuskan untuk menikah", "Memihak keluarga yang lebih dekat dengan Anda karena merasa lebih memahami adat yang mereka pegang"], ans: 2, skor: [3, 4, 5, 1, 2], bahas: "Menengahi dengan dialog dan tokoh yang dihormati." },
  { id: "tkp-sos-028", topik: "TKP Sosial Budaya", level: 1, q: "Rekan memajang simbol agamanya di meja kerja. Anda...", opts: ["Menanyakan maknanya jika ingin tahu dengan sopan dan tidak menjadikannya bahan perdebatan di kantor", "Memasang simbol tandingan di meja Anda sendiri untuk menunjukkan bahwa Anda juga punya hak yang sama", "Menghormatinya selama tidak mengganggu pekerjaan", "Tidak mempermasalahkannya tetapi merasa kurang nyaman sehingga memilih menghindari meja rekan itu", "Menyuruh memindahkannya karena menurut Anda ruang kerja seharusnya netral dari simbol apa pun"], ans: 2, skor: [4, 1, 5, 3, 2], bahas: "Kebebasan beragama dihormati." },
  { id: "tkp-sos-029", topik: "TKP Sosial Budaya", level: 3, q: "Sebuah acara adat memerlukan iuran besar dari warga yang kurang mampu. Anda...", opts: ["Mengusulkan agar acara adat dihapus saja karena dianggap membebani ekonomi warga setiap tahunnya", "Diam saja karena merasa tidak berhak mengomentari urusan adat yang sudah berlangsung sejak lama", "Menyampaikan kepada pengurus adat bahwa sebagian warga keberatan dan meminta pembahasan ulang bersama", "Memaksa semua warga membayar penuh demi menjaga kehormatan adat dan nama baik kampung ini", "Mengusulkan musyawarah untuk meringankan, misalnya iuran bertingkat atau bantuan gotong royong, tanpa menghilangkan makna adat"], ans: 4, skor: [1, 3, 4, 2, 5], bahas: "Adat dihormati sekaligus dijalankan secara adil." },
  { id: "tkp-sos-030", topik: "TKP Sosial Budaya", level: 3, q: "Anda menemukan indikasi diskriminasi dalam seleksi kegiatan di lingkungan kerja. Anda...", opts: ["Mengabaikannya karena bukan urusan Anda dan khawatir menimbulkan masalah dengan panitia seleksi", "Menanyakan dasar penilaian kepada panitia dengan sopan lalu mendokumentasikan jawabannya sebagai bahan laporan", "Mengumpulkan fakta, menyampaikan kepada pihak berwenang, dan mengusulkan kriteria seleksi yang objektif", "Menuduh orang tertentu sebagai pelaku diskriminasi tanpa menunjukkan bukti yang jelas kepada siapa pun", "Menyebarkan dugaan itu di media sosial agar mendapat perhatian banyak orang dengan cepat"], ans: 2, skor: [3, 4, 5, 1, 2], bahas: "Perjuangkan keadilan lewat jalur resmi dan fakta." },
  { id: "tkp-sos-031", topik: "TKP Sosial Budaya", level: 1, q: "Seorang rekan sedang berpuasa dan tidak ikut makan siang bersama. Anda...", opts: ["Menggodanya dengan menawarkan makanan di depannya sebagai candaan agar suasana menjadi akrab", "Menghormatinya, mengatur kegiatan makan siang tanpa memaksanya, dan tetap melibatkannya dalam obrolan kerja", "Menyindir bahwa ia kurang bersemangat bekerja karena sedang menahan lapar sepanjang hari tanpa berkonsultasi dengan siapa pun lebih dulu", "Menjaga sikap dan tidak menawarkan makanan kepadanya lalu menanyakan apakah ia butuh tempat istirahat", "Menyarankan ia tetap ikut makan karena kekompakan tim jauh lebih penting daripada kebiasaan pribadi"], ans: 1, skor: [2, 5, 1, 4, 3], bahas: "Menghormati ibadah rekan menjaga kebersamaan." },
  { id: "tkp-sos-032", topik: "TKP Sosial Budaya", level: 2, q: "Anda ditugaskan di daerah yang bahasanya tidak Anda kuasai. Anda...", opts: ["Mempelajari bahasa dasar setempat dan meminta bantuan warga untuk menerjemahkan bila perlu", "Mengurangi interaksi dengan warga karena kendala bahasa dan memilih bekerja sendiri di kantor", "Meminta warga menyesuaikan diri dengan bahasa Anda karena Anda adalah petugas yang bertugas di sini", "Menunggu warga yang mampu berbahasa Indonesia mendatangi Anda untuk berkomunikasi dengan lebih mudah", "Menggunakan bahasa Indonesia sederhana dengan sabar dan meminta rekan setempat membantu saat diperlukan"], ans: 0, skor: [5, 1, 2, 3, 4], bahas: "Mau belajar bahasa setempat membangun kepercayaan." },
  { id: "tkp-sos-033", topik: "TKP Sosial Budaya", level: 2, q: "Warga meminta acara kantor mengikuti tata cara adat setempat. Anda...", opts: ["Berdiskusi dengan tokoh adat tentang bagian yang dapat diikuti dan bagian yang perlu disesuaikan", "Menolak karena acara kantor harus mengikuti tata cara yang sudah baku di seluruh unit", "Menyerahkan semua keputusan kepada atasan tanpa memberi masukan tentang kebutuhan masyarakat setempat", "Menyesuaikan tata cara yang tidak bertentangan dengan aturan dan mengundang tokoh adat", "Menyetujui seluruh permintaan tanpa memeriksa apakah ada yang bertentangan dengan aturan kantor"], ans: 3, skor: [4, 3, 1, 5, 2], bahas: "Menghargai adat sambil menaati aturan." },
  { id: "tkp-sos-034", topik: "TKP Sosial Budaya", level: 3, q: "Atasan baru mempertanyakan seorang rekan yang berjilbab atau memakai atribut keagamaan di kantor. Anda...", opts: ["Ikut mempertanyakan penampilan rekan itu di grup kantor agar mendapat perhatian atasan baru meskipun belum yakin dampaknya bagi orang lain", "Menjelaskan aturan berpakaian kantor yang berlaku dan memastikan pembahasan dilakukan dengan sopan serta adil", "Menyampaikan bahwa memeluk dan menjalankan keyakinan dijamin konstitusi, lalu mengajak membahas aturan seragam secara tenang", "Membiarkan masalah itu diselesaikan oleh rekan yang bersangkutan dan atasan tanpa melibatkan Anda", "Menyarankan rekan itu mengalah demi menjaga hubungan baik dengan atasan yang baru bertugas"], ans: 2, skor: [1, 4, 5, 3, 2], bahas: "Kebebasan menjalankan keyakinan dijamin dan dibahas secara santun." },
  { id: "tkp-sos-035", topik: "TKP Sosial Budaya", level: 1, q: "Seorang teman melontarkan lelucon bernuansa rasial di grup percakapan. Anda...", opts: ["Membiarkan karena hanya lelucon dan Anda tidak ingin merusak suasana pertemanan di grup", "Menyebarkan tangkapan layar lelucon itu ke banyak grup agar teman itu dipermalukan dan menganggap persoalannya selesai begitu saja", "Tidak memberi tanggapan di grup lalu menyampaikan keberatan kepadanya lewat pesan pribadi", "Ikut tertawa dan membalas dengan lelucon serupa agar tidak dianggap terlalu serius", "Menegur secara pribadi dengan sopan, menjelaskan lelucon itu menyakitkan, dan mengajaknya menghapus unggahan"], ans: 4, skor: [3, 1, 4, 2, 5], bahas: "Menolak lelucon rasial dengan cara yang santun." },
  { id: "tkp-sos-036", topik: "TKP Sosial Budaya", level: 3, q: "Warga pendatang dan penduduk asli berselisih soal lahan. Anda...", opts: ["Menengahi dengan fakta hukum dan melibatkan tokoh kedua pihak untuk mencari kesepakatan tanpa kekerasan", "Menyuruh pendatang meninggalkan lahan itu agar keadaan cepat tenang tanpa memeriksa kebenaran klaimnya", "Menyerahkan masalah kepada aparat dan tidak ikut campur agar tidak dianggap memihak", "Memihak penduduk asli karena merasa mereka yang lebih berhak atas wilayah itu sejak dahulu", "Mengumpulkan dokumen kepemilikan kedua pihak dan menyarankan penyelesaian melalui musyawarah desa"], ans: 0, skor: [5, 1, 3, 2, 4], bahas: "Sengketa diselesaikan dengan hukum dan dialog." },
  { id: "tkp-sos-037", topik: "TKP Sosial Budaya", level: 2, q: "Seorang rekan dari keluarga kurang mampu diejek karena pakaian lusuh. Anda...", opts: ["Menegur pengejek dengan tegas lalu menunjukkan dukungan kepada rekan itu", "Menyarankan rekan itu membeli pakaian baru supaya tidak lagi menjadi bahan ejekan", "Ikut tertawa karena orang lain pun tertawa dan Anda tidak ingin dianggap berbeda", "Membiarkan ejekan itu karena yang diejek tampak tidak terlalu mempermasalahkannya", "Mengajak rekan yang diejek berbincang dan memastikan ia merasa dihargai di tim ini"], ans: 0, skor: [5, 1, 2, 3, 4], bahas: "Membela martabat sesama tanpa memandang status ekonomi." },
  { id: "tkp-sos-038", topik: "TKP Sosial Budaya", level: 1, q: "Anda menyadari brosur acara kantor hanya memuat satu bahasa daerah padahal pesertanya beragam. Anda...", opts: ["Membiarkannya karena brosur sudah selesai dicetak dan acara tinggal beberapa hari lagi", "Mengganti seluruh isi brosur menjadi bahasa daerah Anda sendiri karena lebih Anda kuasai", "Menyampaikan masukan kepada panitia dan membantu menyiapkan terjemahan singkat dalam beberapa bahasa", "Mengusulkan brosur dalam bahasa Indonesia dan memberi ruang bahasa daerah lain agar semua peserta merasa tercakup", "Mengeluh kepada rekan tentang panitia yang tidak peka tanpa menyampaikannya langsung kepada panitia"], ans: 3, skor: [3, 2, 4, 5, 1], bahas: "Inklusi dimulai dari hal-hal kecil seperti bahasa." },
  { id: "tkp-sos-039", topik: "TKP Sosial Budaya", level: 2, q: "Rekan yang tuli membutuhkan juru bahasa isyarat pada rapat. Anda...", opts: ["Menyampaikan kebutuhan itu kepada panitia rapat lalu menyiapkan catatan tertulis yang lengkap untuk rekan tersebut", "Mengabaikan kebutuhan itu karena anggaran rapat terbatas dan tidak ada yang meminta penyediaannya tanpa memikirkan akibat jangka panjangnya", "Menyarankan ia membaca notulen setelah rapat saja agar rapat tidak terhambat dan tetap tepat waktu", "Menunggu rekan itu meminta sendiri karena Anda tidak ingin menganggapnya berbeda dari peserta yang lain", "Mengusulkan penyediaan juru bahasa isyarat atau teks langsung dan memastikan rekan dapat mengikuti rapat"], ans: 4, skor: [4, 1, 2, 3, 5], bahas: "Akses setara bagi penyandang disabilitas." },
  { id: "tkp-sos-040", topik: "TKP Sosial Budaya", level: 2, q: "Pesta kantor menyajikan minuman beralkohol padahal ada rekan yang tidak mengonsumsinya. Anda...", opts: ["Menyampaikan kepada panitia agar menyediakan pilihan minuman tanpa alkohol dan menandainya dengan jelas", "Mengusulkan minuman alternatif agar semua rekan dapat menikmati acara dengan nyaman", "Menekan rekan itu untuk mencoba minuman itu agar terlihat menyatu dengan suasana pesta", "Membiarkan karena rekan yang tidak minum bisa memilih sendiri apa yang akan dikonsumsinya", "Meminta rekan itu tidak hadir saja supaya tidak merasa terganggu oleh minuman tersebut"], ans: 1, skor: [4, 5, 1, 3, 2], bahas: "Acara yang inklusif memperhatikan semua peserta." },
  { id: "tkp-sos-041", topik: "TKP Sosial Budaya", level: 3, q: "Anda diundang ke ritual adat yang berbeda dari keyakinan Anda. Anda...", opts: ["Menghadiri sebagai tamu yang menghormati, memperhatikan batas keyakinan sendiri, dan menyampaikan dengan santun bila ada bagian yang tidak dapat diikuti", "Menanyakan kepada penyelenggara bagian mana yang dapat diikuti tamu lalu hadir sesuai batas itu", "Menolak undangan itu tanpa penjelasan agar tidak terjadi kesalahpahaman di kemudian hari", "Hadir dan mengikuti seluruh rangkaian ritual meskipun bertentangan dengan keyakinan Anda agar tidak menyinggung tuan rumah", "Hadir tetapi mengomentari jalannya ritual dengan nada merendahkan kepada orang di sebelah Anda"], ans: 0, skor: [5, 4, 3, 2, 1], bahas: "Menghormati tanpa mengorbankan keyakinan sendiri." },
  { id: "tkp-sos-042", topik: "TKP Sosial Budaya", level: 1, q: "Seorang peserta magang dari suku minoritas gugup berbicara karena logatnya. Anda...", opts: ["Mengulang kata-katanya dengan menirukan logatnya dalam nada bercanda di depan rekan lain", "Memberinya kesempatan menyampaikan pendapat dalam kelompok kecil agar lebih percaya diri", "Menyemangatinya, mendengarkan sampai selesai, dan menegaskan bahwa logat bukan masalah", "Menyuruhnya berlatih berbicara tanpa logat supaya lebih mudah diterima oleh rekan-rekan", "Menghindari memberinya kesempatan bicara agar ia tidak merasa malu di depan orang banyak"], ans: 2, skor: [2, 4, 5, 3, 1], bahas: "Menghargai keberagaman logat dan latar belakang." },
  { id: "tkp-sos-043", topik: "TKP Sosial Budaya", level: 2, q: "Rapat penting dijadwalkan bertepatan dengan waktu salat Jumat. Anda...", opts: ["Mengusulkan penyesuaian waktu agar peserta yang menjalankan ibadah dapat hadir tanpa meninggalkan kewajiban", "Tetap memulai rapat sesuai jadwal karena jadwal sudah disebar jauh hari sebelumnya", "Menyampaikan kepada penyelenggara bahwa jadwal berbenturan dengan waktu ibadah dan meminta alternatif waktu", "Menyebut peserta yang beribadah sebagai orang yang kurang menghargai waktu kerja, agar urusannya cepat selesai menurut perhitungan Anda", "Menyarankan peserta yang ingin beribadah meninggalkan rapat lalu menyusul setelah selesai"], ans: 0, skor: [5, 2, 4, 1, 3], bahas: "Jadwal kerja menghormati waktu ibadah." },
  { id: "tkp-sos-044", topik: "TKP Sosial Budaya", level: 3, q: "Warga memprotes penggunaan tanah ulayat untuk sebuah proyek. Anda...", opts: ["Menunda pekerjaan tanpa memberi tahu warga atau atasan sehingga tidak ada yang mengetahui alasannya", "Melanjutkan proyek karena sudah mendapat izin dari pemerintah daerah dan sesuai rencana yang disetujui", "Menganggap protes warga sebagai penghambat pembangunan dan meminta aparat membubarkannya", "Mendengarkan keberatan warga, menelaah status hukum tanahnya, dan memfasilitasi musyawarah dengan pemegang hak ulayat", "Menyampaikan keberatan warga kepada pemimpin proyek dan meminta kajian dampak sosial dilakukan bersama warga"], ans: 3, skor: [2, 3, 1, 5, 4], bahas: "Hak ulayat dihormati melalui musyawarah dan hukum." },
  { id: "tkp-sos-045", topik: "TKP Sosial Budaya", level: 1, q: "Sebuah pesan berantai membandingkan kelompok ekonomi dengan nada merendahkan. Anda...", opts: ["Menambahkan komentar yang lebih merendahkan agar pesan terlihat lebih lucu meskipun belum yakin dampaknya bagi orang lain", "Meneruskan pesan itu ke beberapa teman karena menurut Anda ada benarnya juga", "Tidak menyebarkannya, mengingatkan pengirim bahwa pesan itu merendahkan, dan membagikan konten yang membangun", "Menyimpan pesan itu tanpa menanggapi karena tidak ingin menimbulkan perdebatan di grup", "Menghapus pesan itu dan menyampaikan kepada pengirim dengan sopan bahwa isinya kurang pantas disebar"], ans: 2, skor: [1, 2, 5, 3, 4], bahas: "Menolak konten yang memecah belah." },
  { id: "tkp-sos-046", topik: "TKP Sosial Budaya", level: 2, q: "Kegiatan gotong royong melibatkan semua agama membersihkan salah satu rumah ibadah. Anda...", opts: ["Ikut berpartisipasi, menghormati tata tertib di rumah ibadah itu, dan mengajak orang lain bergabung", "Menyindir peserta lain yang berbeda agama karena dianggap terlalu ikut campur meskipun belum yakin dampaknya bagi orang lain", "Membantu di bagian yang diperbolehkan dan menanyakan aturan yang berlaku kepada pengurus setempat", "Menolak ikut karena kegiatan itu bukan bagian dari agama Anda dan tidak wajib diikuti", "Hanya mengirim bantuan dana karena merasa kurang nyaman berada di rumah ibadah agama lain"], ans: 0, skor: [5, 1, 4, 2, 3], bahas: "Kerukunan dibangun lewat kerja sama nyata." },
  { id: "tkp-sos-047", topik: "TKP Sosial Budaya", level: 2, q: "Anda melihat seseorang diejek karena mengenakan pakaian adat di angkutan umum. Anda...", opts: ["Menghampiri orang yang diejek, menyapa dengan ramah, dan menunjukkan bahwa ia tidak sendirian", "Berpura-pura tidak melihat agar tidak terlibat keributan di tempat umum", "Menahan diri dan merekam kejadian untuk diunggah sebagai bahan kritik di media sosial", "Ikut tertawa karena penumpang lain juga tertawa dan Anda tidak mau dianggap berbeda", "Menegur pengejek dengan sopan dan menunjukkan dukungan kepada orang yang diejek"], ans: 4, skor: [4, 3, 2, 1, 5], bahas: "Berani membela martabat budaya." },
  { id: "tkp-sos-048", topik: "TKP Sosial Budaya", level: 3, q: "Seorang teman kantor menolak bekerja sama dengan rekan dari suku tertentu. Anda...", opts: ["Menyampaikan kepada atasan secara santun dan mengusulkan pembagian tim yang adil bagi seluruh anggota", "Menuruti permintaan teman itu agar pekerjaan tetap berjalan tanpa konflik dalam waktu dekat meskipun belum yakin dampaknya bagi orang lain", "Menyebarkan keluhan teman itu kepada rekan lain agar mereka juga ikut menjauhi rekan tersebut", "Mendukung penolakan itu karena Anda juga memiliki pengalaman kurang baik dengan orang dari suku tersebut", "Menjelaskan bahwa penilaian harus berdasarkan kinerja bukan suku, lalu mengajak keduanya bekerja sama dalam tugas kecil"], ans: 4, skor: [4, 3, 1, 2, 5], bahas: "Tolak prasangka suku dan nilai orang berdasarkan karyanya." },
  { id: "tkp-sos-049", topik: "TKP Sosial Budaya", level: 1, q: "Anda ditugasi menyambut tamu internasional yang budaya dan kebiasaannya berbeda. Anda...", opts: ["Menyerahkan penyambutan kepada rekan lain karena Anda tidak suka bertemu orang asing tanpa memikirkan akibat jangka panjangnya", "Menghindari kontak langsung dengan tamu karena khawatir melakukan kesalahan yang memalukan", "Mempelajari kebiasaan dasar budaya tamu, menyiapkan sambutan yang sopan, dan bersikap ramah dan terbuka", "Menanyakan kebutuhan khusus tamu kepada panitia lalu menyesuaikan jamuan dan tata cara penyambutan", "Menyambut dengan cara yang biasa Anda lakukan karena tamu pasti memaklumi perbedaan kebiasaan"], ans: 2, skor: [1, 2, 5, 4, 3], bahas: "Menyambut tamu dengan sikap hormat dan wawasan budaya." },
  { id: "tkp-sos-050", topik: "TKP Sosial Budaya", level: 2, q: "Warga dua kampung berseteru dalam festival budaya. Anda...", opts: ["Menonton dari jauh sambil menunggu aparat datang menenangkan keadaan", "Menenangkan kedua belah pihak, mengajak tokoh kedua kampung berdialog, dan menghentikan kabar yang memanaskan", "Meminta panitia mengatur ulang jalannya acara agar kedua kampung tampil bergantian dengan adil", "Memihak kampung asal Anda dan membantu mereka dalam perseteruan itu", "Merekam pertikaian dan mengunggahnya agar menjadi viral dan ditindak secepatnya dan menganggap persoalannya selesai begitu saja"], ans: 1, skor: [3, 5, 4, 2, 1], bahas: "Festival budaya adalah sarana persatuan, bukan perpecahan." },
  { id: "tkp-tik-001", topik: "TKP TIK", level: 1, q: "Anda menerima email mencurigakan yang meminta kata sandi akun kantor. Anda...", opts: ["Mengklik tautannya untuk memeriksa apakah pengirimnya benar-benar berasal dari bagian TI kantor", "Membalas email itu dengan menyertakan kata sandi karena pengirimnya mengaku sebagai petugas resmi", "Tidak membukanya, melaporkannya kepada bagian TI, lalu menghapusnya dari kotak masuk agar tidak terklik oleh siapa pun", "Tidak membalas email itu dan menanyakan kepada rekan apakah mereka juga menerima pesan serupa", "Mengabaikannya begitu saja karena Anda yakin tidak akan terpengaruh oleh email seperti itu"], ans: 2, skor: [2, 1, 5, 4, 3], bahas: "Phishing harus dilaporkan agar tidak ada korban lain." },
  { id: "tkp-tik-002", topik: "TKP TIK", level: 1, q: "Instansi memakai sistem baru yang terasa rumit. Anda...", opts: ["Mencoba sistem itu pada data contoh dan mencatat bagian yang masih membingungkan untuk ditanyakan", "Mengikuti pelatihan, mempelajari panduan, dan bertanya bila masih bingung", "Mengeluh kepada atasan bahwa sistem itu terlalu rumit dan meminta agar diganti secepatnya", "Tetap memakai cara lama selama masih diperbolehkan karena sudah terbiasa dan merasa lebih cepat", "Menunggu rekan yang lebih mahir mengerjakannya lebih dulu lalu menirunya belakangan"], ans: 1, skor: [4, 5, 1, 2, 3], bahas: "Adaptif pada teknologi baru meningkatkan efisiensi kerja." },
  { id: "tkp-tik-003", topik: "TKP TIK", level: 2, q: "Data warga Anda simpan di flashdisk pribadi agar bisa dikerjakan di rumah. Menurut Anda...", opts: ["Boleh bila rekan Anda mengetahuinya dan tidak keberatan Anda membawa data itu ke rumah", "Boleh selama flashdisk tidak hilang dan hanya Anda sendiri yang pernah memakainya", "Boleh bila flashdisk itu dilindungi kata sandi dan data dihapus setelah selesai dikerjakan di rumah", "Wajar saja karena praktis dan banyak pegawai lain juga melakukannya dalam pekerjaan mereka", "Tidak boleh; gunakan perangkat dan penyimpanan resmi yang diamankan sesuai ketentuan kantor"], ans: 4, skor: [2, 3, 4, 1, 5], bahas: "Data pribadi warga harus dilindungi dengan sarana resmi." },
  { id: "tkp-tik-004", topik: "TKP TIK", level: 1, q: "Rekan meminjam akun login Anda karena lupa kata sandinya. Anda...", opts: ["Memberikan akun itu karena pekerjaannya mendesak dan Anda tidak ingin menghambat tugas orang lain", "Meminjamkannya sebentar sambil mengawasi apa yang dikerjakan rekan itu di akun Anda", "Menyarankan rekan menghubungi bagian TI dan menawarkan menemaninya agar prosesnya lebih cepat", "Menolak dan menyarankan ia mengurus reset kata sandi kepada bagian TI sesuai prosedur resmi kantor", "Memberi kata sandi lalu mengubahnya setelah rekan selesai mengerjakan tugasnya hari ini"], ans: 3, skor: [1, 3, 4, 5, 2], bahas: "Akun bersifat pribadi; tanggung jawab tindakan ada pada pemiliknya." },
  { id: "tkp-tik-005", topik: "TKP TIK", level: 2, q: "Laptop kantor yang memuat data hilang. Anda...", opts: ["Mencari laptop itu ke tempat-tempat yang pernah Anda kunjungi lalu melapor bila tidak ketemu", "Menunggu beberapa hari barangkali ada yang menemukan dan mengembalikannya ke kantor", "Mengganti dengan laptop pribadi dan berharap tidak ada yang menanyakan keberadaan laptop yang hilang", "Segera melapor ke atasan dan bagian TI agar akses dikunci dan data diamankan", "Menyembunyikan kejadian itu agar tidak dianggap lalai dan terkena sanksi dari pimpinan"], ans: 3, skor: [4, 3, 2, 5, 1], bahas: "Pelaporan cepat meminimalkan kebocoran data." },
  { id: "tkp-tik-006", topik: "TKP TIK", level: 3, q: "Aplikasi pelaporan error saat tenggat. Anda...", opts: ["Menyalahkan aplikasi dan tidak mengirimkan laporan sampai ada yang menegur Anda, karena Anda sedang tidak ingin berurusan dengan hal itu", "Mengirim tangkapan layar error kepada atasan dan meminta kebijakan perpanjangan waktu resmi", "Menghubungi admin, mendokumentasikan error, dan memakai jalur alternatif yang sah untuk menyampaikan laporan tepat waktu", "Menunggu sampai aplikasi berfungsi kembali walaupun itu berarti laporan terlambat dikirim", "Mengubah data agar tampak sudah terkirim di sistem tanpa benar-benar melalui aplikasi"], ans: 2, skor: [1, 4, 5, 3, 2], bahas: "Bukti dan alternatif yang sah menjaga akuntabilitas." },
  { id: "tkp-tik-007", topik: "TKP TIK", level: 2, q: "Anda perlu bekerja di tempat umum dengan Wi-Fi gratis. Anda...", opts: ["Memakai jaringan aman atau VPN dan tidak membuka data sensitif", "Terhubung ke Wi-Fi gratis tetapi hanya membuka dokumen yang tidak terlalu penting", "Menggunakan komputer umum yang tersedia dan menyimpan kata sandi di peramban agar lebih praktis", "Menggunakan hotspot ponsel pribadi lalu memastikan perangkat terlindungi dengan sandi yang kuat", "Terhubung ke Wi-Fi gratis dan membuka seluruh data karena jaringan itu terlihat lancar dan cepat"], ans: 0, skor: [5, 3, 1, 4, 2], bahas: "Jaringan publik rawan penyadapan." },
  { id: "tkp-tik-008", topik: "TKP TIK", level: 1, q: "Ada pelatihan aplikasi baru yang terkait tugas Anda. Anda...", opts: ["Menolak mengikuti pelatihan karena merasa cara kerja lama sudah cukup baik dan tidak perlu diubah", "Hadir tepat waktu dan bertanya tentang fitur yang berkaitan dengan tugas Anda", "Mengikuti pelatihan dengan aktif, mencatat poin penting, dan menerapkannya dalam pekerjaan sehari-hari secepatnya", "Mengirim wakil dari unit Anda karena pekerjaan sedang banyak dan rekan itu bisa menyampaikan intinya", "Hadir tetapi sibuk memeriksa ponsel karena merasa materinya sudah pernah Anda dengar"], ans: 2, skor: [1, 4, 5, 3, 2], bahas: "Pengembangan kompetensi digital adalah investasi diri." },
  { id: "tkp-tik-009", topik: "TKP TIK", level: 3, q: "Anda menemukan celah keamanan pada sistem kantor. Anda...", opts: ["Membiarkannya karena merasa itu bukan tugas Anda dan pasti sudah diketahui oleh bagian TI", "Mendokumentasikan dan melaporkannya kepada pihak berwenang tanpa menyebarkan detail celah itu kepada siapa pun", "Menyampaikan temuan itu kepada atasan dan bagian TI lalu menunggu arahan penanganannya", "Memanfaatkan celah itu untuk melihat data yang biasanya tidak dapat Anda akses, sebab Anda merasa tidak ada pilihan lain", "Membagikan temuan itu kepada rekan sebagai informasi menarik tentang kelemahan sistem kantor"], ans: 1, skor: [3, 5, 4, 1, 2], bahas: "Pelaporan bertanggung jawab melindungi sistem dan pengguna." },
  { id: "tkp-tik-010", topik: "TKP TIK", level: 1, q: "Rekan senior yang gaptek meminta Anda mengajarinya aplikasi. Anda...", opts: ["Menertawakan kekurangannya di depan rekan lain sambil memberi contoh singkat", "Mengajarkan langkah demi langkah dengan sabar", "Mengerjakan tugas itu sendiri setiap kali ia kesulitan agar pekerjaan cepat selesai", "Memberikan panduan tertulis dari pabrikan tanpa penjelasan tambahan karena Anda sedang sibuk", "Membuatkan panduan singkat bergambar yang bisa ia baca ulang kapan pun ia membutuhkannya"], ans: 1, skor: [1, 5, 3, 2, 4], bahas: "Berbagi pengetahuan digital mendukung kerja tim." },
  { id: "tkp-tik-011", topik: "TKP TIK", level: 2, q: "Anda harus mengirim dokumen sensitif ke instansi lain. Anda...", opts: ["Mengunggah dokumen itu ke penyimpanan daring umum lalu membagikan tautannya kepada penerima", "Mengirim lewat aplikasi pesan pribadi karena penerima lebih cepat menanggapi di sana", "Memakai saluran resmi yang terenkripsi atau sistem yang ditetapkan kantor", "Mengirim lewat email pribadi karena lebih cepat sampai dan penerimanya pun lebih mudah membukanya", "Mengirim melalui email dinas dengan berkas dilindungi kata sandi yang dikirim lewat jalur terpisah"], ans: 2, skor: [2, 1, 5, 3, 4], bahas: "Informasi sensitif hanya lewat jalur resmi dan aman." },
  { id: "tkp-tik-012", topik: "TKP TIK", level: 1, q: "Anda memakai kata sandi yang sama untuk semua akun. Seharusnya Anda...", opts: ["Menuliskan semua kata sandi di kertas dan menempelkannya di meja agar tidak lupa tanpa berkonsultasi dengan siapa pun lebih dulu", "Membuat kata sandi panjang yang berbeda untuk akun-akun penting dan mengaktifkan verifikasi tambahan", "Memakai kata sandi unik yang kuat untuk tiap akun, dengan pengelola kata sandi atau autentikasi dua langkah", "Tetap memakai kata sandi yang sama karena lebih mudah diingat dan jarang ada yang mencobanya", "Menambahkan satu angka di akhir kata sandi lama agar tiap akun terlihat berbeda satu sama lain"], ans: 2, skor: [1, 4, 5, 2, 3], bahas: "Kata sandi unik dan autentikasi ganda mengurangi risiko pembobolan." },
  { id: "tkp-tik-013", topik: "TKP TIK", level: 2, q: "Notifikasi pembaruan sistem keamanan muncul di komputer kantor. Anda...", opts: ["Menjadwalkan pembaruan pada jam istirahat agar tidak mengganggu pekerjaan yang sedang berjalan", "Menyimpan pekerjaan lalu memperbarui pada waktu yang aman", "Menundanya terus karena takut pembaruan akan memperlambat komputer atau mengubah tampilan", "Mematikan fitur pembaruan otomatis agar tidak ada notifikasi yang mengganggu pekerjaan Anda", "Meminta rekan memperbarui komputer Anda saat Anda sedang tidak berada di tempat"], ans: 1, skor: [4, 5, 3, 1, 2], bahas: "Pembaruan menutup celah keamanan." },
  { id: "tkp-tik-014", topik: "TKP TIK", level: 2, q: "Beredar kabar tidak benar di grup kantor soal gangguan sistem. Anda...", opts: ["Meneruskan kabar itu agar semua rekan ikut waspada sebelum ada penjelasan dari pihak berwenang", "Menambahkan dugaan Anda sendiri tentang penyebab gangguan supaya pembahasan di grup lebih ramai", "Menanyakan sumber kabar itu kepada pengirimnya dan menunggu pengumuman resmi dari bagian TI", "Meninggalkan grup agar tidak ikut terseret dalam kabar yang belum jelas kebenarannya", "Memverifikasi ke bagian TI lalu meluruskannya di grup dengan informasi resmi"], ans: 4, skor: [2, 1, 4, 3, 5], bahas: "Periksa fakta sebelum membagikan informasi." },
  { id: "tkp-tik-015", topik: "TKP TIK", level: 1, q: "Anda belum mencadangkan data penting pekerjaan. Anda...", opts: ["Menganggap pencadangan tidak perlu karena data pernah tersimpan di surel beberapa bulan lalu", "Menyalin data ke folder cadangan di server kantor hari ini lalu membuat pengingat mingguan", "Menyimpan di satu komputer saja karena merasa komputer itu cukup aman dan jarang bermasalah", "Segera mencadangkan di penyimpanan resmi dan menjadwalkan pencadangan rutin agar data tidak hilang", "Menunda pencadangan sampai ada waktu luang karena pekerjaan lain masih menumpuk saat ini"], ans: 3, skor: [1, 4, 2, 5, 3], bahas: "Pencadangan rutin mencegah kehilangan data." },
  { id: "tkp-tik-016", topik: "TKP TIK", level: 1, q: "Anda menerima pesan WhatsApp dari nomor tak dikenal yang mengaku atasan dan meminta transfer dana. Anda...", opts: ["Menanyakan hal yang hanya diketahui atasan Anda lalu melapor ke bagian TI bila jawabannya tidak sesuai", "Mengabaikan pesan itu tanpa melaporkannya karena Anda yakin tidak akan tertipu oleh pesan seperti itu", "Mengonfirmasi lewat telepon atau jalur resmi kepada atasan yang sebenarnya, dan tidak mentransfer sebelum yakin", "Langsung mentransfer dana karena pesan itu terlihat mendesak dan Anda tidak ingin mengecewakan atasan", "Meneruskan pesan itu ke grup agar rekan lain ikut menilai apakah pesan tersebut benar adanya meskipun belum yakin dampaknya bagi orang lain"], ans: 2, skor: [4, 3, 5, 1, 2], bahas: "Penipuan mengatasnamakan atasan harus diverifikasi." },
  { id: "tkp-tik-017", topik: "TKP TIK", level: 2, q: "Untuk laporan, Anda tergoda mengunggah data warga ke aplikasi daring tak resmi yang praktis. Anda...", opts: ["Menggunakan aplikasi itu dengan data yang sudah disamarkan sebagian agar risikonya tidak terlalu besar", "Memakai aplikasi yang resmi disediakan kantor, atau meminta izin lebih dulu bila butuh alat baru", "Mengunggah langsung karena cepat dan praktis dan hasilnya sangat membantu menyelesaikan laporan", "Mengunggah lewat akun pribadi supaya tidak tercatat sebagai pemakaian aplikasi oleh kantor", "Mengajukan permohonan penggunaan aplikasi itu ke bagian TI dan menunggu hasil penilaian keamanannya"], ans: 1, skor: [3, 5, 1, 2, 4], bahas: "Data warga hanya diproses dengan sarana resmi." },
  { id: "tkp-tik-018", topik: "TKP TIK", level: 1, q: "Pembaruan aplikasi mengubah fitur yang biasa Anda pakai. Anda...", opts: ["Membaca catatan pembaruan atau panduan, mencoba fitur baru, dan bertanya bila perlu", "Menanyakan kepada rekan yang sudah mencoba fitur baru lalu mempelajarinya bersama-sama", "Menunggu orang lain mempelajarinya lebih dulu lalu mengikuti cara yang paling banyak dipakai", "Tetap memakai versi lama tanpa pembaruan keamanan karena sudah terbiasa dengan tampilannya", "Mengeluh kepada rekan karena pembaruan dianggap hanya mempersulit pekerjaan sehari-hari"], ans: 0, skor: [5, 4, 3, 2, 1], bahas: "Adaptif terhadap perubahan teknologi." },
  { id: "tkp-tik-019", topik: "TKP TIK", level: 2, q: "Anda menemukan USB asing di area parkir kantor. Anda...", opts: ["Menyerahkannya kepada bagian TI atau keamanan tanpa mencolokkannya", "Mencolokkannya ke komputer kantor untuk melihat isi dan mencari tahu siapa pemiliknya", "Membuangnya ke tempat sampah karena tidak ada yang mengakuinya setelah beberapa waktu", "Membawanya pulang untuk dipakai sendiri karena kondisinya masih bagus", "Menyimpannya di tempat aman lalu menanyakan kepada petugas keamanan apakah ada yang kehilangan"], ans: 0, skor: [5, 1, 3, 2, 4], bahas: "USB asing bisa membawa malware." },
  { id: "tkp-tik-020", topik: "TKP TIK", level: 2, q: "Rekan menyalin file kerja ke penyimpanan cloud pribadi agar mudah dibuka di rumah. Anda...", opts: ["Menghapus file itu dari penyimpanan pribadinya tanpa izin karena merasa itu yang paling benar", "Ikut menyalin file kerja ke cloud pribadi karena terlihat praktis dan sudah banyak yang melakukannya", "Mengingatkan risikonya dan menyarankan memakai akses jarak jauh resmi dari kantor", "Membiarkannya karena Anda tidak ingin dianggap mencampuri cara kerja orang lain di unit ini", "Menyampaikan kepada atasan agar disediakan cara akses resmi yang aman bagi seluruh pegawai"], ans: 2, skor: [1, 2, 5, 3, 4], bahas: "Ingatkan dan arahkan pada sarana resmi." },
  { id: "tkp-tik-021", topik: "TKP TIK", level: 1, q: "Aplikasi baru meminta izin mengakses seluruh kontak dan lokasi padahal tidak terkait fungsinya. Anda...", opts: ["Memberi izin untuk sementara dan mencabutnya setelah selesai dipakai karena butuh cepat", "Menyetujui semua izin karena tidak ada waktu membaca dan aplikasi itu sudah banyak yang memakai sesuai kebiasaan yang selama ini Anda jalani", "Memberi izin seperlunya saja yang berkaitan dengan fungsi aplikasi lalu memeriksa pengaturannya berkala", "Menyuruh rekan mencoba lebih dulu lalu mengikuti keputusan mereka tanpa memeriksa izinnya", "Menolak izin yang tidak relevan, atau tidak memasang aplikasi itu bila izinnya terlalu luas dan tidak jelas fungsinya"], ans: 4, skor: [3, 2, 4, 1, 5], bahas: "Beri izin seperlunya saja." },
  { id: "tkp-tik-022", topik: "TKP TIK", level: 2, q: "Rekan mengunggah foto dokumen kantor yang memuat data internal ke media sosial. Anda...", opts: ["Menyebarkan ulang unggahan itu karena menurut Anda isinya menarik untuk diketahui orang banyak", "Memberi komentar sindiran di unggahan itu agar rekan sadar sendiri tanpa menegurnya langsung", "Menghubungi rekan secara pribadi untuk menghapus unggahan lalu menanyakan apakah ada data yang telah tersebar", "Memberi tahu rekan agar segera menghapus unggahan itu dan melapor ke atasan atau bagian terkait", "Membiarkannya karena unggahan itu sudah terlanjur dilihat orang dan sulit untuk ditarik kembali"], ans: 3, skor: [1, 2, 4, 5, 3], bahas: "Cegah kebocoran data sesegera mungkin." },
  { id: "tkp-tik-023", topik: "TKP TIK", level: 1, q: "Rapat penting lewat video call tetapi sinyal Anda buruk. Anda...", opts: ["Tetap bergabung dengan gambar putus-putus dan berharap peserta lain memahami kondisi Anda", "Menyalahkan operator seluler di grup rapat sampai suasana pembicaraan menjadi terganggu", "Tidak hadir tanpa kabar karena yakin peserta lain tidak akan terlalu mempermasalahkannya tanpa berkonsultasi dengan siapa pun lebih dulu", "Mencari lokasi yang sinyalnya lebih baik, memberi tahu peserta lain, dan menyiapkan cadangan seperti telepon", "Mengabari penyelenggara tentang kendala sinyal dan meminta rekaman atau notulen rapat setelahnya"], ans: 3, skor: [3, 2, 1, 5, 4], bahas: "Antisipasi kendala teknis dan komunikasikan." },
  { id: "tkp-tik-024", topik: "TKP TIK", level: 2, q: "Anda ditugasi membuat panduan penggunaan sistem baru bagi rekan-rekan. Anda...", opts: ["Menyalin panduan dari internet dan mengubah sedikit agar terlihat sesuai dengan sistem kantor", "Menyerahkan tugas itu kepada orang lain karena Anda merasa belum cukup menguasai sistemnya", "Mengumpulkan pertanyaan yang sering muncul dari rekan lalu menyusunnya menjadi panduan singkat", "Membuat panduan seadanya dengan beberapa tangkapan layar karena waktu penyelesaian sangat singkat", "Mempelajari sistem secara mendalam, menulis langkah yang jelas, lalu mengujinya pada rekan"], ans: 4, skor: [3, 1, 4, 2, 5], bahas: "Panduan yang baik teruji pada pengguna nyata." },
  { id: "tkp-tik-025", topik: "TKP TIK", level: 2, q: "Anda menemukan data ganda dan tidak konsisten di basis data kantor. Anda...", opts: ["Membiarkan karena sudah lama begitu dan tidak ada yang pernah mempermasalahkannya sebelumnya", "Menghapus data yang menurut Anda salah agar basis data kantor terlihat lebih rapi", "Mendokumentasikan temuan dan melaporkannya kepada pengelola data untuk diverifikasi sesuai prosedur", "Mengubahnya diam-diam tanpa memberi tahu siapa pun agar tidak terjadi perdebatan tanpa berkonsultasi dengan siapa pun lebih dulu", "Membuat daftar data yang bermasalah lalu mengirimkannya kepada pengelola data disertai usulan perbaikannya"], ans: 2, skor: [3, 2, 5, 1, 4], bahas: "Perubahan data harus melalui prosedur." },
  { id: "tkp-tik-026", topik: "TKP TIK", level: 1, q: "Rekan meninggalkan komputer dalam keadaan terbuka dan menampilkan data warga. Anda...", opts: ["Memotret layar itu sebagai bukti kelalaian rekan untuk dilaporkan kepada atasan nanti", "Menguncinya lalu mengingatkan rekan agar selalu mengunci layar saat meninggalkan meja kerja", "Membiarkannya karena rekan itu pasti hanya pergi sebentar dan segera kembali ke mejanya", "Memakai komputer itu untuk keperluan Anda karena sudah dalam keadaan menyala dan terhubung", "Menunggu di dekat komputer itu sampai rekan kembali lalu mengingatkannya dengan sopan"], ans: 1, skor: [2, 5, 3, 1, 4], bahas: "Kunci layar adalah kebiasaan dasar keamanan." },
  { id: "tkp-tik-027", topik: "TKP TIK", level: 3, q: "Akun lama rekan yang sudah keluar ternyata masih aktif di sistem. Anda...", opts: ["Melaporkannya kepada bagian TI agar akun dinonaktifkan sesuai prosedur dan memastikan tidak ada aktivitas mencurigakan", "Membagikan kata sandi akun itu kepada rekan lain agar mereka juga bisa memakainya saat dibutuhkan", "Mengabaikannya karena Anda menganggap bagian TI pasti sudah mengetahui dan akan menanganinya", "Memakai akun itu untuk mempercepat pekerjaan yang membutuhkan akses yang tidak Anda miliki, sebab Anda merasa tidak ada pilihan lain", "Menanyakan kepada atasan siapa yang berwenang menonaktifkan akun lalu menyampaikan temuan Anda"], ans: 0, skor: [5, 1, 3, 2, 4], bahas: "Akun tak terpakai adalah celah keamanan." },
  { id: "tkp-tik-028", topik: "TKP TIK", level: 2, q: "Sistem down dan atasan meminta kabar perkembangan. Anda...", opts: ["Menghubungi tim TI untuk mendapat perkiraan waktu lalu meneruskannya kepada atasan secara berkala", "Menyampaikan kondisi terkini, perkiraan pemulihan dari tim TI, dan langkah sementara", "Menunggu sampai sistem pulih baru memberi kabar agar tidak menyampaikan informasi yang belum pasti", "Menyalahkan tim TI di depan atasan karena sistem sering bermasalah pada saat yang genting", "Mengatakan bahwa semuanya aman terkendali supaya atasan tidak perlu mengkhawatirkan keadaan"], ans: 1, skor: [4, 5, 3, 1, 2], bahas: "Informasi jelas dan solusi sementara." },
  { id: "tkp-tik-029", topik: "TKP TIK", level: 3, q: "Beredar kabar belum jelas tentang kebocoran data kantor. Anda...", opts: ["Memeriksa pengumuman resmi kantor lalu mengingatkan rekan agar tidak menyebarkan kabar yang belum pasti", "Membantah kabar itu dengan tegas tanpa bukti agar kantor tidak dianggap lalai menjaga data", "Mengabaikannya karena Anda tidak mau terlibat dalam kabar yang belum diketahui kebenarannya", "Menunggu konfirmasi resmi dari pihak berwenang, dan melapor ke bagian TI bila Anda memiliki informasi yang relevan", "Menyebarkannya ke banyak orang agar semua waspada dan segera mengganti kata sandi mereka dan menganggap persoalannya selesai begitu saja"], ans: 3, skor: [4, 2, 3, 5, 1], bahas: "Jangan menyebar spekulasi; salurkan informasi lewat jalur resmi." },
  { id: "tkp-tik-030", topik: "TKP TIK", level: 1, q: "Anda ingin mencoba perangkat lunak baru yang dapat mempercepat pekerjaan. Anda...", opts: ["Memakainya di perangkat pribadi untuk mengolah data kantor supaya tidak ketahuan bagian TI sesuai kebiasaan yang selama ini Anda jalani", "Mengabaikan ide itu karena merasa prosedur izin tentu akan memakan waktu terlalu lama", "Memasangnya langsung di komputer kantor agar bisa segera dicoba dan dimanfaatkan hasilnya", "Mencoba versi uji pada data contoh di perangkat terpisah lalu menyampaikan hasilnya kepada bagian TI", "Mengusulkannya kepada atasan atau bagian TI agar diuji keamanan dan izin pemakaiannya lebih dulu"], ans: 4, skor: [1, 3, 2, 4, 5], bahas: "Inovasi disalurkan lewat izin dan uji keamanan." },
  { id: "tkp-tik-031", topik: "TKP TIK", level: 1, q: "Anda menerima tautan undian hadiah di grup kantor yang meminta data pribadi. Anda...", opts: ["Menghapus pesan itu dan menanyakan kepada pengirim apakah akunnya telah diretas orang lain", "Mengabaikannya karena Anda sendiri tidak tertarik pada undian dan tidak merasa perlu bertindak", "Tidak mengklik tautan itu, mengingatkan anggota grup bahwa itu kemungkinan penipuan, dan melaporkannya kepada bagian TI", "Mengisi data pribadi di tautan itu karena hadiahnya tampak menarik dan banyak yang membagikannya", "Mengklik tautannya sekadar melihat tampilan tanpa mengisi apa pun karena penasaran tanpa memikirkan akibat jangka panjangnya"], ans: 2, skor: [4, 3, 5, 1, 2], bahas: "Waspada pada penipuan berkedok hadiah." },
  { id: "tkp-tik-032", topik: "TKP TIK", level: 2, q: "Printer jaringan mencetak dokumen milik orang lain yang memuat data pegawai. Anda...", opts: ["Memberi tahu bagian TI bahwa ada dokumen terkirim ke printer yang salah agar pengaturannya diperbaiki", "Membuang dokumen itu ke tempat sampah agar tidak terbaca orang lain tanpa memberi tahu siapa pun", "Menyimpan dokumen dengan aman dan menyerahkannya kepada pemiliknya atau bagian TI", "Membaca isinya sekilas untuk mengetahui milik siapa lalu meninggalkannya begitu saja di meja", "Menunjukkan isi dokumen itu kepada rekan lain karena menurut Anda isinya menarik untuk diketahui"], ans: 2, skor: [4, 2, 5, 3, 1], bahas: "Dokumen sensitif harus ditangani dengan hati-hati." },
  { id: "tkp-tik-033", topik: "TKP TIK", level: 3, q: "Rekan memakai alat kecerdasan buatan daring untuk menulis laporan dengan menempelkan data internal. Anda...", opts: ["Menanyakan kepada atasan apakah ada kebijakan penggunaan alat itu lalu menyampaikannya kepada rekan", "Mengingatkan bahwa data internal tidak boleh dimasukkan ke layanan luar, lalu menyarankan memakai alat resmi atau data yang telah disamarkan", "Membiarkannya karena hasil laporannya bagus dan Anda tidak ingin mencampuri cara rekan bekerja", "Ikut memakai alat yang sama untuk laporan Anda karena terlihat menghemat banyak waktu", "Melaporkan rekan itu kepada atasan sebagai pelanggar tanpa mencoba menegurnya terlebih dahulu, sebab Anda merasa tidak ada pilihan lain"], ans: 1, skor: [4, 5, 3, 2, 1], bahas: "Data internal tidak boleh dikirim ke layanan luar." },
  { id: "tkp-tik-034", topik: "TKP TIK", level: 2, q: "Anda diminta mengganti kata sandi setiap 90 hari. Anda...", opts: ["Membuat kata sandi panjang yang mudah diingat tetapi sulit ditebak lalu menyimpannya dengan aman", "Menggantinya dengan kata sandi lama yang hanya ditambah satu angka di bagian akhirnya", "Menunda penggantian sampai sistem memaksa Anda melakukannya pada saat yang kurang tepat", "Menggantinya dengan kata sandi baru yang kuat dan berbeda dari sebelumnya", "Menolak mengganti karena merasa kata sandi lama sudah cukup aman dan belum pernah bermasalah"], ans: 3, skor: [4, 3, 2, 5, 1], bahas: "Kata sandi kuat dan berkala mengurangi risiko." },
  { id: "tkp-tik-035", topik: "TKP TIK", level: 3, q: "Anda memakai perangkat pribadi untuk bekerja tanpa pengamanan khusus. Anda...", opts: ["Meminta panduan keamanan dari bagian TI, memasang pengamanan yang disyaratkan, dan memisahkan data kerja dari data pribadi", "Meminjamkan perangkat itu kepada anggota keluarga yang membutuhkan tanpa menghapus data kerja, sebab Anda merasa tidak ada pilihan lain", "Tetap memakainya seperti biasa karena selama ini tidak pernah ada masalah yang terjadi", "Memasang kunci layar dan pembaruan keamanan lalu menanyakan kebijakan perangkat pribadi kepada bagian TI", "Menyimpan seluruh dokumen kantor di perangkat itu agar mudah diakses kapan saja dan di mana saja"], ans: 0, skor: [5, 1, 3, 4, 2], bahas: "Perangkat pribadi untuk kerja harus diamankan." },
  { id: "tkp-tik-036", topik: "TKP TIK", level: 2, q: "Anda menerima notifikasi login dari lokasi asing pada akun kantor Anda. Anda...", opts: ["Membalas notifikasi itu dengan menanyakan siapa yang mencoba login ke akun Anda", "Mengabaikannya karena mungkin hanya kesalahan sistem yang sering terjadi pada layanan daring", "Memeriksa riwayat aktivitas akun lalu mengaktifkan verifikasi dua langkah dan melaporkan temuan", "Menunggu beberapa hari untuk melihat apakah ada kejadian mencurigakan lainnya yang menyusul", "Segera mengganti kata sandi dan melaporkannya kepada bagian TI"], ans: 4, skor: [1, 3, 4, 2, 5], bahas: "Aktivitas mencurigakan harus segera ditangani." },
  { id: "tkp-tik-037", topik: "TKP TIK", level: 2, q: "Anda menemukan file rahasia di folder bersama yang dapat diakses semua pegawai. Anda...", opts: ["Tidak membuka file itu dan mencatat lokasinya lalu menyampaikannya kepada pengelola folder bersama", "Membuka file itu sebentar untuk memastikan benar-benar rahasia sebelum melaporkannya kepada pengelola", "Memberi tahu pemilik atau bagian TI agar hak aksesnya segera dibatasi", "Menyalin file itu ke komputer Anda agar tidak hilang ketika folder bersama dibersihkan", "Membiarkannya karena semua pegawai memang bebas mengakses folder bersama di kantor ini"], ans: 2, skor: [4, 3, 5, 2, 1], bahas: "Akses data rahasia harus dibatasi." },
  { id: "tkp-tik-038", topik: "TKP TIK", level: 1, q: "Pelatihan keamanan siber wajib bertabrakan dengan pekerjaan Anda. Anda...", opts: ["Menanyakan kemungkinan pelatihan susulan dan mendelegasikan tugas mendesak kepada rekan selama pelatihan", "Mengatur ulang pekerjaan, mendiskusikan dengan atasan, lalu mengikuti pelatihan agar tidak tertinggal materinya", "Melewatkan pelatihan karena merasa sudah cukup paham mengenai keamanan siber dari pengalaman meskipun belum yakin dampaknya bagi orang lain", "Mengikuti pelatihan sambil mengerjakan tugas lain agar semua pekerjaan tetap terpantau", "Mengirim rekan sebagai pengganti karena pekerjaan Anda lebih penting dan tidak bisa ditinggalkan"], ans: 1, skor: [4, 5, 1, 3, 2], bahas: "Pelatihan keamanan adalah kewajiban bersama." },
  { id: "tkp-tik-039", topik: "TKP TIK", level: 2, q: "Seorang warga bertanya cara memakai layanan daring kantor. Anda...", opts: ["Menunjukkan layar contoh pengisian dan mendampingi warga sampai berhasil menyelesaikan layanan", "Menjelaskan langkah-langkahnya dengan sabar dan memberi panduan yang mudah dipahami", "Meminta warga membaca panduan di situs resmi karena semua langkah sudah dijelaskan di sana", "Meminta warga datang langsung dan mengabaikan layanan daring karena lebih ribet menjelaskannya", "Menyarankan warga bertanya kepada anaknya karena generasi muda biasanya lebih paham teknologi"], ans: 1, skor: [4, 5, 3, 1, 2], bahas: "Literasi digital warga adalah bagian dari pelayanan." },
  { id: "tkp-tik-040", topik: "TKP TIK", level: 3, q: "Anda melihat rekan memotret layar sistem yang memuat data warga. Anda...", opts: ["Menanyakan keperluannya dan menyarankan mengajukan salinan resmi data melalui prosedur yang benar", "Mengabaikannya karena Anda tidak mau dianggap suka mengawasi kegiatan rekan kerja tanpa memikirkan akibat jangka panjangnya", "Menegur dengan sopan bahwa memotret data warga tidak diperbolehkan, meminta menghapus foto, dan melapor bila berulang", "Membiarkannya karena menurut Anda rekan itu pasti hanya membutuhkannya sebagai catatan pribadi", "Meminta rekan itu mengirimkan juga fotonya kepada Anda sebagai arsip tambahan"], ans: 2, skor: [4, 1, 5, 3, 2], bahas: "Data warga tidak boleh disalin sembarangan." },
  { id: "tkp-tik-041", topik: "TKP TIK", level: 2, q: "Pencadangan otomatis gagal berhari-hari tanpa ada yang menyadari. Anda...", opts: ["Menunggu sistem memperbaiki diri karena biasanya masalah seperti ini hilang dengan sendirinya", "Menghapus catatan kegagalan agar tidak ada yang menyadari kelalaian yang telah terjadi", "Mengabaikannya karena Anda bukan petugas TI dan tidak punya wewenang menangani masalah ini", "Melaporkannya kepada bagian TI dan membuat pencadangan manual sementara", "Memeriksa catatan kegagalan lalu menyampaikan hasilnya kepada bagian TI disertai usulan perbaikan"], ans: 3, skor: [3, 1, 2, 5, 4], bahas: "Kegagalan cadangan harus segera ditangani." },
  { id: "tkp-tik-042", topik: "TKP TIK", level: 2, q: "Anda tidak sengaja mengirim email berisi data sensitif kepada penerima yang salah. Anda...", opts: ["Segera melapor kepada atasan dan bagian TI, lalu meminta penerima menghapus email itu", "Mencoba menarik kembali email dan menghubungi penerima untuk meminta penghapusan pesan itu", "Mengirim email susulan tanpa menjelaskan apa pun agar tidak menarik perhatian orang lain", "Menyembunyikan kesalahan itu karena khawatir mendapat teguran dari pimpinan", "Menunggu apakah penerima membalas karena mungkin ia sendiri akan menghapusnya tanpa diminta"], ans: 0, skor: [5, 4, 2, 1, 3], bahas: "Insiden data harus dilaporkan secara terbuka." },
  { id: "tkp-tik-043", topik: "TKP TIK", level: 1, q: "Anda diminta menyetujui izin pemasangan perangkat lunak baru di komputer kantor. Anda...", opts: ["Menanyakan kepada bagian TI apakah perangkat lunak itu sudah masuk daftar yang diizinkan", "Menyetujui langsung karena pengirim permintaannya terlihat meyakinkan dan menyebut nama pimpinan", "Membiarkan pemasangan dilakukan karena Anda tidak ingin menghambat pekerjaan rekan yang membutuhkannya", "Memeriksa sumber dan kebutuhan perangkat lunak itu, lalu memastikan pemasangan dilakukan oleh bagian TI sesuai prosedur", "Memasang sendiri perangkat lunak itu dari tautan yang diberikan agar cepat selesai sesuai kebiasaan yang selama ini Anda jalani"], ans: 3, skor: [4, 3, 2, 5, 1], bahas: "Pemasangan perangkat lunak harus melalui prosedur." },
  { id: "tkp-tik-044", topik: "TKP TIK", level: 2, q: "Server sedang dalam pemeliharaan saat tenggat laporan. Anda...", opts: ["Memakai server pribadi untuk mengunggah laporan agar tidak terlambat dari tenggat", "Menunggu sampai server aktif kembali tanpa melakukan apa pun agar tidak salah langkah", "Menyelesaikan bagian laporan yang bisa dikerjakan lebih dulu lalu mengunggah setelah sistem pulih", "Menyalahkan pihak pemeliharaan atas keterlambatan dan menolak mengirim laporan hari ini", "Menghubungi atasan, meminta kebijakan perpanjangan, dan menyiapkan laporan di luar sistem"], ans: 4, skor: [2, 3, 4, 1, 5], bahas: "Atasi hambatan dengan komunikasi dan solusi sah." },
  { id: "tkp-tik-045", topik: "TKP TIK", level: 2, q: "Rekan mengirim data pekerjaan lewat aplikasi pesan pribadi. Anda...", opts: ["Menyarankan rekan menghapus pesan itu lalu mengirim ulang lewat saluran resmi yang ditetapkan kantor", "Mengabaikan kejadian itu karena Anda tidak bertanggung jawab atas cara rekan bekerja", "Ikut memakai aplikasi pesan pribadi untuk berbagi data agar komunikasi lebih lancar", "Membiarkan karena rekan itu hanya ingin cepat dan datanya tidak terlalu besar", "Mengingatkan agar memakai saluran resmi kantor dan menjelaskan risiko kebocorannya"], ans: 4, skor: [4, 1, 2, 3, 5], bahas: "Data kerja hanya lewat saluran resmi." },
  { id: "tkp-tik-046", topik: "TKP TIK", level: 2, q: "Aplikasi pelaporan mewajibkan banyak langkah dan rekan ingin menyingkatnya. Anda...", opts: ["Membantu rekan menyelesaikan langkah dengan lebih cepat melalui pintasan yang diizinkan", "Membiarkan rekan melewati beberapa langkah karena menurutnya tidak terlalu penting", "Menjelaskan bahwa langkah itu ada tujuannya, dan mengusulkan penyederhanaan lewat jalur resmi", "Ikut melewati langkah itu agar pekerjaan Anda juga cepat selesai bersama rekan", "Menyarankan rekan mengisi data seadanya agar laporan bisa segera dikirim sesuai kebiasaan yang selama ini Anda jalani"], ans: 2, skor: [4, 3, 5, 2, 1], bahas: "Prosedur tidak dilewati; usulkan perbaikan lewat jalur resmi." },
  { id: "tkp-tik-047", topik: "TKP TIK", level: 3, q: "Anda diminta mengunggah foto kegiatan di media sosial kantor dan di dalamnya ada wajah warga. Anda...", opts: ["Mengunggahnya lebih dulu lalu menghapusnya apabila ada warga yang keberatan di kemudian hari", "Menanyakan kebijakan publikasi foto kepada atasan lalu menunggu keputusan sebelum mengunggah", "Memastikan warga memberi persetujuan dan mengikuti kebijakan kantor, lalu menyamarkan wajah bila tidak ada izin", "Mengunggah foto itu karena kegiatan tersebut kegiatan publik dan warga pasti tidak keberatan", "Mengunggah foto lengkap dengan nama warga agar terlihat lebih lengkap dan menarik tanpa memikirkan akibat jangka panjangnya"], ans: 2, skor: [1, 4, 5, 3, 2], bahas: "Privasi warga harus dihormati dalam publikasi." },
  { id: "tkp-tik-048", topik: "TKP TIK", level: 2, q: "Anda menemukan perangkat lunak bajakan terpasang di komputer kantor. Anda...", opts: ["Membiarkannya karena selama berfungsi baik tidak ada yang dirugikan oleh pemakaiannya", "Menanyakan kepada atasan siapa yang memasangnya lalu menyampaikan risiko hukum dan keamanannya", "Menyalin perangkat lunak itu ke komputer Anda karena kantor pun sudah memakainya", "Melaporkannya kepada bagian TI agar diganti dengan perangkat lunak berlisensi", "Menghapus perangkat lunak itu sendiri tanpa memberi tahu siapa pun agar masalahnya selesai"], ans: 3, skor: [3, 4, 2, 5, 1], bahas: "Gunakan perangkat lunak yang sah." },
  { id: "tkp-tik-049", topik: "TKP TIK", level: 1, q: "Anda tidak sengaja menekan tombol hapus pada data penting. Anda...", opts: ["Mencoba mengetik ulang data dari ingatan agar tidak ada yang tahu terjadi kesalahan", "Memeriksa folder sampah dan riwayat versi lalu menghubungi bagian TI bila tidak ditemukan", "Menyalahkan sistem yang dianggap terlalu mudah menghapus data tanpa peringatan, sebab Anda merasa tidak ada pilihan lain", "Membiarkannya dan berharap tidak ada yang mencari data itu dalam waktu dekat", "Segera berhenti, melaporkan kepada bagian TI, dan mencoba memulihkan dari cadangan"], ans: 4, skor: [3, 4, 1, 2, 5], bahas: "Kesalahan dilaporkan cepat agar data bisa dipulihkan." },
  { id: "tkp-tik-050", topik: "TKP TIK", level: 2, q: "Teknologi baru membuat sebagian tugas Anda otomatis. Anda...", opts: ["Menolak teknologi itu karena khawatir pekerjaan Anda akan tergantikan oleh sistem", "Menunggu sampai ada instruksi dari atasan tanpa berusaha mempersiapkan diri sendiri", "Mengabaikan teknologi itu dan tetap mengerjakan tugas dengan cara lama yang Anda kuasai", "Menanyakan kepada atasan peran baru yang bisa Anda ambil lalu mengikuti pelatihan yang dibutuhkan", "Mempelajari teknologi itu dan mengembangkan keterampilan yang lebih bernilai"], ans: 4, skor: [3, 2, 1, 4, 5], bahas: "Adaptif pada perubahan teknologi." },
  { id: "tkp-pro-001", topik: "TKP Profesionalisme", level: 2, q: "Anda menemukan kesalahan dalam laporan yang sudah Anda buat dan belum ada yang menyadarinya. Anda...", opts: ["Memperbaiki laporan itu lalu mengirim versi baru kepada penerima disertai penjelasan singkat tentang perubahannya", "Mengganti berkas laporan diam-diam tanpa memberi tahu siapa pun agar tidak menimbulkan pertanyaan", "Membiarkannya dan menyalahkan data dari bagian lain bila suatu saat kesalahan itu ketahuan", "Menunggu sampai ada yang menegur sebelum memperbaiki karena kesalahannya tidak terlalu besar tanpa berkonsultasi dengan siapa pun lebih dulu", "Segera memperbaiki, menyampaikan kepada atasan, dan memastikan pihak terdampak mendapat versi yang benar"], ans: 4, skor: [4, 2, 1, 3, 5], bahas: "Integritas berarti mengakui dan memperbaiki kesalahan." },
  { id: "tkp-pro-002", topik: "TKP Profesionalisme", level: 2, q: "Tenggat dekat dan kualitas pekerjaan terancam. Anda...", opts: ["Meminta bantuan rekan untuk membagi pekerjaan dan menyampaikan perkembangannya kepada atasan secara berkala", "Menyerahkan hasil seadanya agar tepat waktu walaupun beberapa bagian belum diperiksa dengan teliti", "Menyusun prioritas, melapor risikonya kepada atasan, dan mengupayakan hasil terbaik dalam batas waktu", "Mengabaikan bagian yang sulit dan berharap tidak ada yang memeriksanya dengan cermat, supaya Anda tidak mendapat masalah dengan siapa pun", "Menyerahkan terlambat tanpa memberi kabar supaya hasilnya lebih sempurna menurut penilaian Anda"], ans: 2, skor: [4, 3, 5, 1, 2], bahas: "Komunikasi dini dan manajemen prioritas menjaga mutu kerja." },
  { id: "tkp-pro-003", topik: "TKP Profesionalisme", level: 3, q: "Atasan memerintahkan sesuatu yang menurut Anda tidak sesuai aturan. Anda...", opts: ["Menolak keras di depan umum agar semua orang tahu bahwa Anda tidak mau melanggar aturan", "Meminta perintah itu dituangkan secara tertulis sambil menanyakan dasar aturan yang digunakan atasan", "Menyampaikan keberatan dengan sopan disertai dasar aturan, lalu mencari alternatif yang sesuai ketentuan", "Mengerjakan tanpa bertanya karena atasan pasti lebih paham dan Anda tidak ingin dianggap membangkang", "Mengerjakan perintah itu tetapi mencatat keberatan Anda untuk berjaga-jaga bila terjadi masalah"], ans: 2, skor: [2, 4, 5, 1, 3], bahas: "Taat aturan dan hormat kepada atasan dijaga dengan komunikasi yang tepat." },
  { id: "tkp-pro-004", topik: "TKP Profesionalisme", level: 2, q: "Vendor menawarkan hadiah menjelang proses pengadaan. Anda...", opts: ["Menolak dan melaporkannya sesuai aturan gratifikasi", "Menerima karena nilainya kecil lalu membagi hadiah itu ke rekan sekantor sebagai bentuk kebersamaan", "Menerima dan menukarnya dengan uang agar lebih bermanfaat bagi keperluan Anda sendiri", "Menyimpan hadiah itu dulu sampai proses pengadaan selesai lalu mengembalikannya kepada vendor", "Menolak hadiah itu dengan sopan dan menjelaskan bahwa pegawai tidak boleh menerima pemberian"], ans: 0, skor: [5, 2, 1, 3, 4], bahas: "Menjaga independensi pengadaan." },
  { id: "tkp-pro-005", topik: "TKP Profesionalisme", level: 1, q: "Seorang rekan sering terlambat sehingga pekerjaan tim terhambat. Anda...", opts: ["Melaporkannya kepada atasan tanpa berbicara dengannya karena merasa itu cara yang paling cepat", "Mengerjakan bagiannya sendiri tanpa memberi tahu siapa pun agar pekerjaan tim tetap selesai", "Ikut datang terlambat karena merasa tidak adil bila hanya Anda yang selalu tepat waktu dan menganggap persoalannya selesai begitu saja", "Menegurnya dengan baik, menanyakan kendalanya, dan menyepakati solusi bersama agar tidak terulang kembali", "Mengingatkan rekan itu secara pribadi dan menawarkan bantuan mengatur ulang pembagian tugas tim"], ans: 3, skor: [3, 2, 1, 5, 4], bahas: "Pendekatan personal yang empatik lebih dulu." },
  { id: "tkp-pro-006", topik: "TKP Profesionalisme", level: 1, q: "Anda diberi tugas di luar uraian jabatan Anda. Anda...", opts: ["Mengerjakan tugas itu dengan baik lalu menyampaikan kepada atasan bahwa tugas itu di luar jabatan Anda", "Mengerjakan sambil mengeluh kepada rekan karena merasa pekerjaan Anda dimanfaatkan secara tidak adil", "Menanyakan latar belakangnya, mengerjakan dengan baik bila mendesak, dan mendiskusikan pembagian tugas ke depan", "Menyuruh rekan mengerjakannya karena Anda sendiri sedang sibuk dengan tugas pokok", "Menolak karena itu bukan tugas Anda dan Anda tidak mau menambah beban kerja tanpa berkonsultasi dengan siapa pun lebih dulu"], ans: 2, skor: [4, 3, 5, 2, 1], bahas: "Fleksibel dan komunikatif untuk kepentingan organisasi." },
  { id: "tkp-pro-007", topik: "TKP Profesionalisme", level: 2, q: "Atasan mengkritik pekerjaan Anda di depan rekan-rekan. Anda...", opts: ["Menyalahkan rekan kerja agar atasan mengalihkan perhatian dari kesalahan yang Anda buat", "Menerima kritik itu dengan tenang lalu menanyakan hal yang perlu diperbaiki setelah pertemuan selesai", "Meninggalkan ruangan sebagai tanda tidak setuju dengan cara atasan menyampaikan kritik tersebut", "Membela diri dengan emosional di depan semua orang karena merasa dipermalukan tanpa alasan", "Mendengarkan, mengambil poin perbaikan, dan meminta waktu bicara pribadi bila perlu"], ans: 4, skor: [1, 4, 2, 3, 5], bahas: "Mengelola emosi dan fokus pada perbaikan." },
  { id: "tkp-pro-008", topik: "TKP Profesionalisme", level: 3, q: "Saudara Anda ikut dalam tender yang Anda tangani. Anda...", opts: ["Merahasiakan hubungan itu karena Anda khawatir dicurigai padahal tidak berbuat curang", "Tetap menilai secara objektif tanpa memberi tahu siapa pun karena yakin tidak akan memihak", "Menyatakan konflik kepentingan kepada atasan dan mengundurkan diri dari penilaian tender itu", "Meminta agar penilaian tender dialihkan kepada rekan lain lalu mencatat pernyataan konflik kepentingan", "Membantu saudara agar menang dengan memberi sedikit informasi yang tidak dimiliki peserta lain"], ans: 2, skor: [2, 3, 5, 4, 1], bahas: "Konflik kepentingan wajib dideklarasikan." },
  { id: "tkp-pro-009", topik: "TKP Profesionalisme", level: 2, q: "Anda diminta lembur untuk kebutuhan mendesak tanpa kepastian imbalan. Anda...", opts: ["Menyanggupi tetapi bekerja seperlunya saja karena tidak ada jaminan imbalan yang jelas", "Menyanggupi sesuai kemampuan, menanyakan ketentuan lembur, dan mengerjakan sebaik mungkin", "Menyanggupi dan meminta surat perintah lembur agar tercatat sesuai aturan yang berlaku di kantor", "Menghilang pada jam lembur dengan alasan ada keperluan keluarga yang tidak bisa ditunda", "Meminta imbalan dibayar di muka sebelum Anda bersedia mulai bekerja pada waktu lembur"], ans: 1, skor: [3, 5, 4, 1, 2], bahas: "Komitmen pada tugas disertai kejelasan administrasi." },
  { id: "tkp-pro-010", topik: "TKP Profesionalisme", level: 1, q: "Seorang teman menanyakan informasi rahasia pekerjaan Anda. Anda...", opts: ["Menjawab dengan petunjuk samar agar teman itu bisa menebak sendiri jawabannya", "Mengalihkan pembicaraan dengan ramah dan menjelaskan bahwa Anda tidak dapat membahas urusan pekerjaan", "Memberi sedikit petunjuk saja karena teman itu dekat dan tidak akan menyebarkan informasi", "Memberi informasi lengkap karena Anda percaya sepenuhnya kepada teman dekat Anda itu sesuai kebiasaan yang selama ini Anda jalani", "Menolak dengan sopan karena itu rahasia jabatan yang tidak boleh dibicarakan kepada siapa pun"], ans: 4, skor: [2, 4, 3, 1, 5], bahas: "Menjaga rahasia jabatan adalah kewajiban." },
  { id: "tkp-pro-011", topik: "TKP Profesionalisme", level: 3, q: "Target kerja bisa tercapai cepat dengan cara curang yang sulit terdeteksi. Anda...", opts: ["Menggunakan cara itu karena tidak akan ada yang tahu dan hasil kerja tetap tampak baik", "Menyuruh rekan melakukannya agar jika ketahuan Anda tidak ikut bertanggung jawab", "Menolak dan mencari cara yang sah walau membutuhkan waktu lebih lama", "Menyampaikan kepada atasan bahwa target sulit dicapai dengan cara yang sah dan meminta penyesuaian", "Menggunakan cara itu sekali saja karena hasilnya sangat dibutuhkan unit pada periode ini"], ans: 2, skor: [2, 1, 5, 4, 3], bahas: "Integritas lebih penting daripada hasil instan." },
  { id: "tkp-pro-012", topik: "TKP Profesionalisme", level: 2, q: "Anda lelah dan tugas menumpuk. Anda...", opts: ["Menyusun prioritas, meminta bantuan atau penyesuaian tenggat bila perlu, dan menjaga kesehatan", "Mengerjakan tugas yang paling mendesak lebih dulu lalu menjadwalkan sisanya dan memberi tahu atasan", "Menunda semua pekerjaan sampai Anda merasa lebih segar tanpa memberi tahu siapa pun", "Mengerjakan semuanya seadanya supaya cepat selesai walaupun mutunya menurun tanpa berkonsultasi dengan siapa pun lebih dulu", "Mengeluh kepada rekan tentang beban kerja tanpa membicarakannya kepada atasan Anda"], ans: 0, skor: [5, 4, 1, 2, 3], bahas: "Manajemen beban kerja secara terbuka." },
  { id: "tkp-pro-013", topik: "TKP Profesionalisme", level: 1, q: "Ada peluang promosi yang mensyaratkan sertifikasi yang belum Anda miliki. Anda...", opts: ["Mengikuti pelatihan atau ujian sertifikasi untuk memenuhi syarat dan merencanakan waktu belajarnya", "Menyerah karena merasa persyaratan itu terlalu berat dan tidak sesuai dengan kondisi Anda saat ini", "Menanyakan kemungkinan pengecualian syarat kepada pimpinan karena pengalaman kerja Anda sudah banyak", "Membuat sertifikat palsu supaya bisa segera mengajukan diri dalam promosi tersebut tanpa berkonsultasi dengan siapa pun lebih dulu", "Menanyakan jadwal sertifikasi terdekat lalu menyusun rencana belajar dan meminta izin kepada atasan"], ans: 0, skor: [5, 2, 3, 1, 4], bahas: "Kompetensi dikembangkan lewat jalur sah." },
  { id: "tkp-pro-014", topik: "TKP Profesionalisme", level: 3, q: "Anda dituduh bersalah oleh rekan atas kesalahan yang tidak Anda lakukan. Anda...", opts: ["Menjelaskan dengan tenang disertai bukti dan meminta klarifikasi lewat atasan bila perlu", "Mengumpulkan catatan kerja yang relevan lalu meminta pertemuan untuk mengklarifikasi tuduhan itu secara terbuka", "Marah-marah dan mengancam rekan itu supaya segera menarik kembali tuduhannya sesuai kebiasaan yang selama ini Anda jalani", "Diam dan menerima tuduhan karena tidak ingin memperpanjang urusan walaupun Anda merasa tidak bersalah", "Membalas dengan menuduh rekan itu melakukan kesalahan yang lain agar ia sadar"], ans: 0, skor: [5, 4, 1, 3, 2], bahas: "Klarifikasi berbasis bukti dan sikap tenang." },
  { id: "tkp-pro-015", topik: "TKP Profesionalisme", level: 3, q: "Hasil kerja tim gagal dan atasan marah. Anda...", opts: ["Bersembunyi dulu sampai suasana mereda agar tidak menjadi sasaran kemarahan atasan", "Menyalahkan rekan tim yang paling lemah agar tanggung jawab tidak jatuh kepada Anda", "Mengundurkan diri dari tim karena merasa tidak sanggup menerima tekanan atasan tanpa memikirkan akibat jangka panjangnya", "Menyampaikan fakta kegagalan dengan jujur kepada atasan lalu mengajak tim menyusun rencana perbaikan", "Mengakui bagian Anda, mengajak tim mengevaluasi penyebabnya, dan mengusulkan perbaikan"], ans: 4, skor: [3, 2, 1, 4, 5], bahas: "Tanggung jawab bersama dan pembelajaran dari kegagalan." },
  { id: "tkp-pro-016", topik: "TKP Profesionalisme", level: 1, q: "Anda kecewa karena tidak terpilih dalam sebuah proyek penting. Anda...", opts: ["Menanyakan masukan tentang hal yang perlu ditingkatkan dan tetap bekerja sebaik mungkin pada tugas lain", "Memberi selamat kepada rekan yang terpilih dan menyatakan kesiapan membantu proyek bila dibutuhkan", "Mengurangi semangat kerja sementara waktu sampai perasaan Anda membaik dan keadaan menjadi tenang", "Mengundurkan diri dari unit karena merasa tidak dihargai oleh pimpinan meskipun belum yakin dampaknya bagi orang lain", "Menjelekkan rekan yang terpilih kepada orang lain agar penilaian terhadapnya menurun"], ans: 0, skor: [5, 4, 3, 1, 2], bahas: "Jadikan kekecewaan sebagai bahan berkembang." },
  { id: "tkp-pro-017", topik: "TKP Profesionalisme", level: 2, q: "Rekan meminta Anda menandatangani daftar hadir untuknya karena ia belum tiba. Anda...", opts: ["Menolak dengan sopan karena itu pemalsuan data kehadiran", "Menolak dan menyarankan rekan mengisi sendiri begitu tiba lalu menyampaikan alasan keterlambatannya kepada atasan", "Meminta imbalan tertentu sebelum bersedia menandatangani daftar hadir untuknya", "Menandatangani karena kasihan dan tidak ingin rekan terkena potongan tunjangan kehadiran", "Menandatangani sekali saja karena rekan itu sedang dalam kesulitan dan berjanji tidak mengulanginya"], ans: 0, skor: [5, 4, 1, 2, 3], bahas: "Integritas dalam administrasi kehadiran." },
  { id: "tkp-pro-018", topik: "TKP Profesionalisme", level: 1, q: "Atasan baru memiliki gaya kerja yang berbeda dari atasan sebelumnya. Anda...", opts: ["Meminta pindah unit karena merasa tidak cocok dengan gaya kerja atasan baru dan menganggap persoalannya selesai begitu saja", "Menolak menyesuaikan diri karena cara kerja lama sudah terbukti berjalan baik", "Menanyakan prioritas dan cara pelaporan yang diinginkan atasan baru lalu menyesuaikan kebiasaan kerja Anda", "Membandingkannya terus dengan atasan lama dan menyampaikannya kepada rekan di unit", "Memahami harapan dan gaya kerjanya, lalu menyesuaikan cara berkomunikasi serta bekerja"], ans: 4, skor: [1, 2, 4, 3, 5], bahas: "Adaptif terhadap perubahan kepemimpinan." },
  { id: "tkp-pro-019", topik: "TKP Profesionalisme", level: 2, q: "Anda diberi tugas yang belum pernah dikerjakan sebelumnya. Anda...", opts: ["Mengerjakan sebisanya dengan perkiraan sendiri karena tidak ingin dianggap kurang mampu", "Menunda sampai mendekati tenggat berharap ada orang lain yang menyelesaikannya, agar urusannya cepat selesai menurut perhitungan Anda", "Mempelajari prosedurnya, bertanya kepada yang berpengalaman, lalu mengerjakannya dengan teliti", "Menyerahkan tugas itu kepada rekan lain yang menurut Anda lebih berpengalaman", "Meminta contoh pekerjaan serupa dan menanyakan hal yang kurang jelas sebelum memulai mengerjakannya"], ans: 2, skor: [3, 1, 5, 2, 4], bahas: "Mau belajar hal baru." },
  { id: "tkp-pro-020", topik: "TKP Profesionalisme", level: 3, q: "Anggaran tersisa di akhir tahun dan ada ajakan menghabiskannya agar tidak dipotong tahun depan. Anda...", opts: ["Mengusulkan penggunaan hanya untuk kebutuhan nyata yang telah direncanakan, dan mengembalikan sisa sesuai aturan", "Menyampaikan kepada atasan bahwa penggunaan anggaran harus sesuai perencanaan dan tidak dihabiskan hanya demi penyerapan", "Menyetujui penggunaan untuk kegiatan yang bermanfaat walaupun belum direncanakan sebelumnya", "Menghabiskan anggaran untuk barang yang tidak terlalu dibutuhkan agar penyerapan terlihat baik", "Membagi sisa anggaran kepada pegawai sebagai tambahan penghasilan di akhir tahun, karena menurut Anda itu cara yang paling praktis"], ans: 0, skor: [5, 4, 3, 2, 1], bahas: "Pengelolaan anggaran harus efisien dan akuntabel." },
  { id: "tkp-pro-021", topik: "TKP Profesionalisme", level: 1, q: "Rekan sering menceritakan masalah pribadinya saat jam kerja. Anda...", opts: ["Mendengarkan sebentar dengan empati lalu menawarkan berbincang lagi saat istirahat agar pekerjaan tidak terganggu", "Menghindari rekan itu pada jam kerja agar tidak terjebak dalam percakapan yang panjang", "Menyampaikan dengan ramah bahwa Anda ingin membantu setelah tugas selesai dan mengajaknya makan siang", "Memotong ceritanya dengan kasar karena merasa waktu kerja terbuang", "Mendengarkan terus sepanjang hari sehingga pekerjaan Anda sendiri menjadi terbengkalai, karena menurut Anda itu cara yang paling praktis"], ans: 0, skor: [5, 3, 4, 2, 1], bahas: "Empati dengan batas waktu kerja." },
  { id: "tkp-pro-022", topik: "TKP Profesionalisme", level: 3, q: "Anda ditawari pekerjaan sampingan yang beririsan dengan tugas kantor Anda. Anda...", opts: ["Menyampaikan kepada atasan atau unit etik untuk memastikan tidak ada konflik kepentingan sebelum memutuskan", "Menerimanya diam-diam karena penghasilan tambahan sangat Anda butuhkan saat ini", "Menerima dan memakai data kantor untuk mempercepat pekerjaan sampingan tersebut, agar urusannya cepat selesai menurut perhitungan Anda", "Menerima selama dikerjakan di luar jam kerja dan tidak memakai fasilitas kantor sama sekali", "Membaca aturan tentang pekerjaan sampingan pegawai lalu berkonsultasi dengan bagian kepegawaian sebelum menjawab"], ans: 0, skor: [5, 2, 1, 3, 4], bahas: "Deklarasikan potensi konflik kepentingan." },
  { id: "tkp-pro-023", topik: "TKP Profesionalisme", level: 3, q: "Anda menemukan temuan audit yang merugikan unit Anda sendiri. Anda...", opts: ["Menunggu sampai atasan menanyakan karena Anda tidak ingin terlihat membawa kabar buruk", "Melaporkan apa adanya kepada atasan dan mengusulkan langkah perbaikan", "Menyalahkan auditor atas temuan itu dan mengabaikan masukannya sama sekali", "Menyiapkan klarifikasi tertulis berdasarkan fakta lalu menyampaikannya kepada atasan dan auditor", "Mengubah angka agar temuan terlihat lebih ringan dan unit Anda tidak dinilai buruk"], ans: 1, skor: [3, 5, 1, 4, 2], bahas: "Transparan dan fokus perbaikan." },
  { id: "tkp-pro-024", topik: "TKP Profesionalisme", level: 2, q: "Anda menemukan dokumen lama berisi kesalahan dari pendahulu Anda. Anda...", opts: ["Menyembunyikan dokumen itu supaya kesalahannya tidak ketahuan oleh pihak mana pun sesuai kebiasaan yang selama ini Anda jalani", "Membiarkannya karena itu kesalahan pendahulu dan bukan tanggung jawab Anda sekarang", "Melaporkan kesalahan itu kepada atasan dan meminta petunjuk cara memperbaikinya dengan benar", "Menyalahkan pendahulu Anda di depan rekan lain agar tidak dianggap lalai", "Memperbaikinya sesuai prosedur, mencatat perubahannya, dan memberi tahu pihak yang terkait"], ans: 4, skor: [1, 3, 4, 2, 5], bahas: "Perbaiki kesalahan tanpa menyalahkan." },
  { id: "tkp-pro-025", topik: "TKP Profesionalisme", level: 1, q: "Rapat molor melewati jam pulang sementara Anda punya agenda penting. Anda...", opts: ["Menyalahkan pimpinan rapat di depan peserta lain karena tidak mengatur waktu dengan baik", "Tetap duduk sampai selesai sambil menggerutu karena tidak berani meminta izin", "Menyampaikan keperluan dengan sopan, lalu meminta izin keluar atau mendelegasikan catatan rapat", "Menanyakan kepada pimpinan rapat apakah ada bagian yang masih memerlukan Anda sebelum pamit", "Pergi tanpa pamit karena merasa rapat sudah terlalu lama dan tidak efektif"], ans: 2, skor: [1, 3, 5, 4, 2], bahas: "Komunikasikan keperluan dengan sopan." },
  { id: "tkp-pro-026", topik: "TKP Profesionalisme", level: 3, q: "Anda tahu rekan akan dipromosikan meski kinerjanya kurang layak. Anda...", opts: ["Menyebarkan kabar buruk tentang rekan itu agar rencana promosinya dibatalkan", "Menyiapkan catatan kinerja yang faktual dan menyerahkannya kepada pihak yang berwenang saat ada penilaian", "Menyampaikan data kinerja yang objektif melalui jalur resmi bila diminta, tanpa menyerang pribadi", "Diam dan ikut menyetujui promosi itu karena tidak ingin terlibat dalam urusan orang lain", "Menyabotase pekerjaan rekan itu supaya kinerjanya terlihat lebih buruk lagi meskipun belum yakin dampaknya bagi orang lain"], ans: 2, skor: [2, 4, 5, 3, 1], bahas: "Objektif dan profesional." },
  { id: "tkp-pro-027", topik: "TKP Profesionalisme", level: 2, q: "Seorang rekan menawarkan uang pelicin agar izin yang Anda proses lebih cepat. Anda...", opts: ["Menolak dengan tegas lalu menjelaskan bahwa izin diproses sesuai urutan dan menyampaikannya kepada atasan", "Menolak tetapi tidak melaporkan karena tidak ingin menimbulkan masalah dengan rekan itu", "Menerima lalu mengembalikannya kemudian agar tidak tercatat sebagai pelanggaran", "Menerima karena sama-sama untung dan hanya dilakukan satu kali saja", "Menolak, mencatat kejadian, dan melaporkannya sesuai prosedur"], ans: 4, skor: [4, 3, 2, 1, 5], bahas: "Tolak dan laporkan suap." },
  { id: "tkp-pro-028", topik: "TKP Profesionalisme", level: 2, q: "Kinerja unit menurun dan atasan meminta ide perbaikan. Anda...", opts: ["Mengumpulkan masukan rekan lalu menyampaikannya kepada atasan dalam bentuk usulan yang terstruktur", "Menyalahkan rekan tertentu sebagai penyebab menurunnya kinerja unit", "Menganalisis penyebab dengan data dan mengusulkan beberapa langkah perbaikan yang realistis", "Diam karena takut ide Anda salah dan dianggap tidak berguna oleh atasan", "Mengusulkan ide tanpa dasar data agar terlihat aktif di hadapan atasan sesuai kebiasaan yang selama ini Anda jalani"], ans: 2, skor: [4, 2, 5, 3, 1], bahas: "Ide berbasis data." },
  { id: "tkp-pro-029", topik: "TKP Profesionalisme", level: 2, q: "Anda diminta menyampaikan kabar buruk berupa permohonan ditolak kepada seorang warga. Anda...", opts: ["Menyuruh orang lain menyampaikannya karena Anda tidak sanggup melihat kekecewaan warga", "Menghindar dari warga itu sampai ia berhenti menanyakan keputusan permohonannya, karena menurut Anda itu cara yang paling praktis", "Mengirim pesan tertulis tanpa penjelasan karena menghindari pembicaraan yang tidak nyaman", "Menyampaikan dengan jelas dan sopan, menjelaskan alasannya, serta menyebut tindak lanjut yang masih bisa ditempuh", "Menyampaikan dengan empati sambil memberi tahu syarat yang harus dipenuhi untuk mengajukan kembali"], ans: 3, skor: [2, 1, 3, 5, 4], bahas: "Kabar buruk disampaikan jelas dan berempati." },
  { id: "tkp-pro-030", topik: "TKP Profesionalisme", level: 3, q: "Dua atasan memberi perintah yang jadwalnya bertabrakan. Anda...", opts: ["Memilih perintah yang paling mudah diselesaikan tanpa memberi tahu atasan lainnya", "Mengajukan usulan urutan pengerjaan lalu meminta persetujuan kedua atasan secara tertulis", "Mengerjakan keduanya sekaligus dengan hasil setengah-setengah agar tidak ada yang kecewa", "Menunda keduanya sampai ada yang menanyakan hasil pekerjaan itu", "Menyampaikan kondisi kepada keduanya dan meminta kesepakatan prioritas"], ans: 4, skor: [2, 4, 3, 1, 5], bahas: "Minta kejelasan prioritas." },
  { id: "tkp-pro-031", topik: "TKP Profesionalisme", level: 2, q: "Anda mendapati rekan memakai fasilitas kantor untuk urusan pribadi. Anda...", opts: ["Menegur secara pribadi dan menjelaskan aturan pemakaian fasilitas kantor yang berlaku", "Menyebarkan kejadian itu di grup agar rekan itu malu dan berhenti melakukannya", "Membiarkannya karena menganggap itu hal kecil yang lumrah dilakukan banyak pegawai", "Ikut memakai fasilitas itu untuk keperluan pribadi karena semua orang melakukannya", "Mengingatkannya dengan sopan dan menyampaikan kepada atasan bila berulang"], ans: 4, skor: [4, 1, 3, 2, 5], bahas: "Fasilitas negara dipakai sesuai peruntukan." },
  { id: "tkp-pro-032", topik: "TKP Profesionalisme", level: 3, q: "Anda diminta menandatangani dokumen yang belum sempat Anda baca lengkap. Anda...", opts: ["Menandatangani sambil berpikir bahwa kesalahan apa pun nanti menjadi tanggung jawab penyusunnya", "Meminta waktu singkat untuk membaca dan memeriksa dokumen itu bersama bagian terkait sebelum menandatangani", "Menandatangani karena yang meminta adalah atasan dan Anda percaya isinya sudah benar", "Menolak menandatangani sebelum membaca seluruh isinya, lalu menanyakan hal yang kurang jelas", "Menandatangani cepat-cepat agar urusan selesai dan tidak mengganggu waktu kerja orang lain"], ans: 3, skor: [2, 4, 3, 5, 1], bahas: "Tanda tangan adalah tanggung jawab." },
  { id: "tkp-pro-033", topik: "TKP Profesionalisme", level: 2, q: "Anda menerima tugas yang melebihi kemampuan Anda saat ini. Anda...", opts: ["Menyerahkan tugas itu kepada rekan tanpa menjelaskan alasan, supaya Anda tidak mendapat masalah dengan siapa pun", "Mengerjakan sendiri sebisanya tanpa memberi tahu siapa pun tentang kesulitan yang dihadapi", "Menyampaikan keterbatasan dengan jujur, meminta bimbingan, dan mengerjakan dengan sungguh-sungguh", "Meminta pelatihan atau pendampingan dari rekan berpengalaman sebelum mengerjakan tugas itu", "Menolak tugas itu karena takut gagal dan mengecewakan atasan"], ans: 2, skor: [1, 3, 5, 4, 2], bahas: "Jujur pada keterbatasan dan mau belajar." },
  { id: "tkp-pro-034", topik: "TKP Profesionalisme", level: 2, q: "Atasan memuji Anda atas hasil yang sebenarnya dikerjakan rekan. Anda...", opts: ["Meluruskan dengan sopan dan menyebut kontribusi rekan", "Menerima pujian itu lalu menyampaikan kepada atasan bahwa rekan Anda yang mengerjakan bagian terbesarnya", "Mengaku bahwa hasil itu hasil kerja Anda sendiri agar terlihat lebih berprestasi", "Menerima pujian tanpa komentar karena tidak ingin merusak suasana yang sedang menyenangkan", "Meminta rekan itu diam supaya pujian tetap untuk Anda"], ans: 0, skor: [5, 4, 2, 3, 1], bahas: "Jujur dan adil dalam penghargaan." },
  { id: "tkp-pro-035", topik: "TKP Profesionalisme", level: 3, q: "Anda mengetahui target dapat tercapai dengan memanipulasi data laporan. Anda...", opts: ["Menyampaikan kendala pencapaian target kepada atasan dengan data yang benar dan meminta dukungan", "Memanipulasi seluruh data karena target adalah satu-satunya yang dinilai atasan tanpa memikirkan akibat jangka panjangnya", "Mengikuti arahan rekan senior agar tidak dianggap tidak kompak dan menghambat unit", "Memanipulasi sedikit agar angka terlihat wajar dan tidak mencurigakan", "Menolak memanipulasi dan menyampaikan data apa adanya bersama usulan perbaikan kinerja"], ans: 4, skor: [4, 1, 3, 2, 5], bahas: "Data jujur adalah dasar kinerja." },
  { id: "tkp-pro-036", topik: "TKP Profesionalisme", level: 1, q: "Rapat unit sering tidak efektif dan membuang waktu. Anda...", opts: ["Menyiapkan bahan singkat sebelum rapat dan membantu memandu diskusi agar tetap fokus", "Tidak hadir pada rapat berikutnya dengan alasan pekerjaan lebih penting, agar tidak perlu repot menjelaskan kepada banyak orang", "Mengeluh kepada rekan setiap selesai rapat tanpa menyampaikan usulan perbaikan", "Menghadiri rapat sambil mengerjakan tugas lain karena menganggap rapat itu tidak penting", "Mengusulkan agenda dan batas waktu yang jelas serta pencatatan tindak lanjut agar rapat lebih efektif"], ans: 4, skor: [4, 1, 2, 3, 5], bahas: "Perbaikan proses dimulai dari usulan konstruktif." },
  { id: "tkp-pro-037", topik: "TKP Profesionalisme", level: 2, q: "Anda membuat keputusan yang ternyata keliru dan merugikan sedikit. Anda...", opts: ["Menyalahkan informasi yang tidak lengkap dari pihak lain agar Anda tidak terlihat lalai", "Menutupi kekeliruan itu dengan keputusan lain yang tampak seolah sudah direncanakan", "Mengakui kekeliruan, melapor kepada atasan, dan segera memperbaiki dampaknya", "Menjelaskan kronologi keputusan itu dengan jujur lalu mengusulkan langkah pemulihan", "Menunggu sampai kerugiannya diketahui orang lain baru menjelaskan alasan keputusan Anda"], ans: 2, skor: [2, 1, 5, 4, 3], bahas: "Tanggung jawab atas keputusan berarti mengakui dan memperbaiki." },
  { id: "tkp-pro-038", topik: "TKP Profesionalisme", level: 3, q: "Teman lama meminta Anda membocorkan informasi pengadaan dengan imbalan. Anda...", opts: ["Menolak tegas, menjelaskan bahwa itu pelanggaran, dan melaporkan upaya suap kepada pihak berwenang", "Menolak tetapi tetap berteman baik dan tidak membahas soal itu lagi kepada siapa pun", "Menolak dan menutup pembicaraan tentang hal itu lalu memberi tahu atasan mengenai tawaran tersebut", "Memberikan informasi itu dengan imbalan karena teman lama patut dibantu dan menganggap persoalannya selesai begitu saja", "Memberikan sedikit informasi yang tidak terlalu penting agar teman tidak kecewa"], ans: 0, skor: [5, 3, 4, 1, 2], bahas: "Tolak dan laporkan upaya suap." },
  { id: "tkp-pro-039", topik: "TKP Profesionalisme", level: 2, q: "Anda diminta menggantikan atasan memimpin rapat secara mendadak. Anda...", opts: ["Meminta catatan atau arahan dari atasan sebelum rapat lalu memimpin sesuai pokok bahasan yang ditentukan", "Memimpin rapat tanpa persiapan dan membiarkan diskusi berjalan tanpa arah yang jelas", "Menyerahkan kepemimpinan kepada rekan lain tanpa meminta persetujuan atasan terlebih dahulu", "Menolak karena merasa belum siap dan tidak ingin salah di depan peserta lain", "Menyiapkan agenda singkat, memimpin dengan tertib, dan melaporkan hasilnya kepada atasan"], ans: 4, skor: [4, 2, 1, 3, 5], bahas: "Kesiapan memimpin dalam situasi mendadak." },
  { id: "tkp-pro-040", topik: "TKP Profesionalisme", level: 2, q: "Seorang bawahan melakukan kesalahan kecil berulang. Anda...", opts: ["Mengajaknya berdiskusi untuk memahami penyebab kesalahan lalu menyusun rencana perbaikan bersama", "Membimbingnya secara pribadi, menjelaskan standar yang benar, dan memantau perkembangannya", "Membiarkan karena kesalahannya kecil dan tidak merugikan unit secara berarti", "Mengerjakan ulang pekerjaannya sendiri tanpa memberi tahu agar tidak menimbulkan perdebatan", "Menegur keras di depan rekan lain agar ia jera dan tidak mengulang kesalahan itu"], ans: 1, skor: [4, 5, 2, 1, 3], bahas: "Pimpinan membimbing, bukan mempermalukan." },
  { id: "tkp-pro-041", topik: "TKP Profesionalisme", level: 2, q: "Rekanan mengundang Anda makan siang mewah menjelang evaluasi kontrak. Anda...", opts: ["Menolak dengan sopan dan menjelaskan aturan larangan menerima jamuan dari rekanan", "Menerima dan meminta rekanan memberikan jamuan serupa kepada rekan satu tim Anda", "Menerima karena hanya makan siang dan Anda tidak akan terpengaruh dalam penilaian", "Menolak dan menyarankan pertemuan dilakukan di kantor pada jam kerja dan didampingi rekan lain", "Menerima dengan syarat membayar bagian Anda sendiri agar tidak dianggap menerima gratifikasi"], ans: 0, skor: [5, 1, 2, 4, 3], bahas: "Hindari jamuan yang dapat memengaruhi objektivitas." },
  { id: "tkp-pro-042", topik: "TKP Profesionalisme", level: 1, q: "Anda lupa membalas surat penting hingga lewat batas waktu. Anda...", opts: ["Membalas seperti biasa tanpa menyebut keterlambatan agar tidak ada yang menanyakannya", "Menunggu sampai pengirim menagih jawaban baru kemudian membalas dengan singkat", "Menyalahkan kesibukan unit atas keterlambatan itu dan tidak meminta maaf, sebab Anda yakin tidak akan ada yang mempermasalahkannya", "Segera membalas disertai permintaan maaf dan melapor kepada atasan agar dampaknya bisa diantisipasi", "Menghubungi pengirim surat untuk menjelaskan keterlambatan dan menanyakan tenggat baru yang masih mungkin"], ans: 3, skor: [3, 2, 1, 5, 4], bahas: "Akui keterlambatan dan perbaiki segera." },
  { id: "tkp-pro-043", topik: "TKP Profesionalisme", level: 3, q: "Anda diberi tugas ganda dari dua proyek yang sama-sama mendesak. Anda...", opts: ["Mengerjakan salah satu proyek lebih dulu dan membiarkan proyek lainnya menunggu tanpa kabar", "Membuat jadwal kerja terperinci dan menyampaikannya kepada kedua pimpinan proyek agar kesepakatan jelas", "Memetakan tenggat dan dampaknya, lalu mendiskusikan prioritas serta dukungan tenaga dengan atasan", "Menolak salah satu proyek tanpa penjelasan karena merasa tidak sanggup sesuai kebiasaan yang selama ini Anda jalani", "Mengerjakan keduanya sekaligus dengan mengorbankan jam istirahat dan kualitas hasil"], ans: 2, skor: [3, 4, 5, 1, 2], bahas: "Kelola prioritas secara terbuka." },
  { id: "tkp-pro-044", topik: "TKP Profesionalisme", level: 3, q: "Rekan meminta Anda berbohong kepada atasan untuk menutupi keterlambatannya. Anda...", opts: ["Menolak dan menawarkan membantu rekan menyiapkan penjelasan yang jujur kepada atasan", "Berbohong dengan memberi alasan lain agar rekan tidak ditegur atasan", "Menyetujui dan meminta rekan membalas budi di waktu lain, karena Anda sedang tidak ingin berurusan dengan hal itu", "Menolak berbohong dan menyarankan rekan menjelaskan sendiri alasan keterlambatannya kepada atasan", "Menyetujui sekali saja karena rekan itu sedang menghadapi masalah pribadi"], ans: 3, skor: [4, 2, 1, 5, 3], bahas: "Kejujuran tidak dikorbankan demi solidaritas." },
  { id: "tkp-pro-045", topik: "TKP Profesionalisme", level: 3, q: "Seorang warga menawarkan pekerjaan kepada saudara Anda sebagai balasan atas layanan cepat. Anda...", opts: ["Menyampaikan tawaran itu kepada saudara dan menyerahkan keputusan kepadanya", "Menerima tawaran itu karena tidak berhubungan langsung dengan pekerjaan Anda", "Menerima dan melayani warga itu lebih cepat sebagai bentuk terima kasih, sebab Anda merasa tidak ada pilihan lain", "Menolak tawaran itu, menjelaskan bahwa layanan tidak boleh dibalas dengan imbalan, dan melapor bila diperlukan", "Menolak tawaran itu dengan sopan dan memberi tahu atasan agar tercatat sebagai upaya gratifikasi"], ans: 3, skor: [3, 2, 1, 5, 4], bahas: "Gratifikasi dalam bentuk apa pun harus ditolak." },
  { id: "tkp-pro-046", topik: "TKP Profesionalisme", level: 2, q: "Anda merasa beban kerja tidak sebanding dengan imbalan yang Anda terima. Anda...", opts: ["Mengeluh di media sosial agar mendapat perhatian publik dan pimpinan", "Mendiskusikan dengan atasan bagian pekerjaan yang dapat disesuaikan dan mengajukan usulan perbaikan", "Mencari penghasilan tambahan dengan cara yang melanggar aturan kantor", "Mengurangi usaha kerja secara diam-diam sebagai bentuk protes terhadap kondisi ini", "Menyampaikan aspirasi lewat jalur resmi dan tetap bekerja sesuai standar"], ans: 4, skor: [1, 4, 2, 3, 5], bahas: "Aspirasi disalurkan lewat jalur yang benar." },
  { id: "tkp-pro-047", topik: "TKP Profesionalisme", level: 2, q: "Anda menemukan aturan lama yang menghambat pelayanan. Anda...", opts: ["Mengabaikan aturan itu dan memakai cara sendiri yang menurut Anda lebih cepat", "Menjalankan aturan itu apa adanya tanpa mengeluh karena aturan memang tidak bisa diubah", "Menyalahkan pembuat aturan di depan warga agar warga memahami kesulitan Anda meskipun belum yakin dampaknya bagi orang lain", "Mencatat kasus yang terhambat lalu menyampaikannya kepada atasan sebagai bahan usulan perbaikan aturan", "Mengusulkan perubahan aturan lewat jalur resmi disertai data dampaknya, sambil tetap menaati aturan yang berlaku"], ans: 4, skor: [2, 3, 1, 4, 5], bahas: "Taat aturan sambil mengusulkan perbaikan." },
  { id: "tkp-pro-048", topik: "TKP Profesionalisme", level: 3, q: "Anda diminta menyusun laporan kinerja unit yang hasilnya kurang memuaskan. Anda...", opts: ["Menunda penyusunan laporan sampai mendekati tenggat berharap ada perbaikan hasil", "Menonjolkan keberhasilan kecil saja dan menyamarkan angka yang kurang baik", "Mengarang capaian yang lebih baik agar unit Anda terlihat berprestasi tanpa memikirkan akibat jangka panjangnya", "Menyampaikan capaian dan kendala secara berimbang lalu mengusulkan target yang realistis untuk periode berikutnya", "Menyajikan data apa adanya, menganalisis penyebabnya, dan menyertakan rencana perbaikan yang jelas"], ans: 4, skor: [2, 3, 1, 4, 5], bahas: "Laporan yang jujur menjadi dasar perbaikan." },
  { id: "tkp-pro-049", topik: "TKP Profesionalisme", level: 2, q: "Anda menyaksikan atasan melanggar aturan kecil dalam pekerjaannya. Anda...", opts: ["Menyampaikan dengan sopan secara pribadi dan merujuk aturan yang berlaku", "Mengikuti cara atasan karena beranggapan bahwa itu sudah menjadi kebiasaan di unit", "Mengingatkan atasan lewat pesan pribadi yang santun sambil menawarkan alternatif yang sesuai aturan", "Menceritakannya kepada rekan lain agar mereka juga mengetahui pelanggaran atasan", "Membiarkannya karena atasan pasti memiliki pertimbangan sendiri yang tidak Anda ketahui"], ans: 0, skor: [5, 1, 4, 2, 3], bahas: "Ingatkan atasan dengan hormat dan merujuk aturan." },
  { id: "tkp-pro-050", topik: "TKP Profesionalisme", level: 2, q: "Anda menerima kritik tertulis tanpa nama tentang kinerja Anda. Anda...", opts: ["Membaca dengan tenang, mengambil bagian yang bermanfaat, dan memperbaiki kinerja", "Mencari tahu siapa penulisnya lalu menegurnya karena tidak berani menyebut nama", "Merenungkan kritik itu lalu meminta masukan dari atasan atau rekan yang dipercaya untuk memastikannya", "Menganggap kritik itu tidak penting karena tanpa nama dan tidak dapat dipertanggungjawabkan", "Merobek kritik itu dan melupakannya agar tidak mengganggu perasaan Anda"], ans: 0, skor: [5, 3, 4, 2, 1], bahas: "Kritik adalah bahan perbaikan." },
  { id: "tkp-rad-001", topik: "TKP Anti Radikalisme", level: 1, q: "Rekan menyebarkan ujaran kebencian terhadap kelompok tertentu di media sosial. Anda...", opts: ["Mengingatkan rekan secara pribadi bahwa unggahan itu menyakiti orang lain dan menyarankan menghapusnya", "Mengabaikannya karena itu akun pribadinya dan bukan urusan Anda sebagai rekan kerja", "Menegurnya dengan baik, mengingatkan dampaknya, dan melaporkan konten bila terus berlanjut", "Membalas dengan ujaran serupa agar rekan merasakan bagaimana rasanya diserang kelompoknya", "Menyukai dan membagikan ulang unggahan itu agar semakin banyak orang yang melihatnya"], ans: 2, skor: [4, 3, 5, 2, 1], bahas: "Menghentikan penyebaran kebencian dan menjaga persatuan." },
  { id: "tkp-rad-002", topik: "TKP Anti Radikalisme", level: 2, q: "Seorang teman mengajak Anda bergabung dengan kelompok yang menolak Pancasila. Anda...", opts: ["Ikut bergabung agar tidak dijauhi oleh teman-teman dekat yang sudah lebih dulu masuk", "Menolak tegas, menjelaskan alasan setia pada Pancasila, dan melapor bila ada indikasi bahaya", "Datang sekali untuk melihat-lihat karena penasaran tanpa berniat untuk bergabung", "Menjauhi teman itu tanpa penjelasan karena tidak ingin terlibat dengan urusan seperti itu", "Menolak ajakan itu dengan sopan lalu menjaga jarak dari kegiatan kelompok tersebut"], ans: 1, skor: [1, 5, 3, 2, 4], bahas: "Kesetiaan pada Pancasila diwujudkan dengan sikap tegas dan peduli." },
  { id: "tkp-rad-003", topik: "TKP Anti Radikalisme", level: 1, q: "Anda menerima pesan berantai provokatif yang mengadu domba umat beragama. Anda...", opts: ["Meneruskan ke seluruh kontak agar semua orang waspada terhadap kelompok yang disebut di dalamnya", "Meneruskan ke keluarga saja karena menurut Anda mereka perlu mengetahui hal itu", "Menyimpan pesan itu tanpa membagikannya karena merasa belum tahu apakah isinya benar", "Tidak menyebarkannya, memverifikasi kebenarannya, dan melaporkan akun penyebarnya kepada pihak yang berwenang", "Menghapus pesan itu dan mengingatkan pengirim bahwa isinya berpotensi memecah belah masyarakat"], ans: 3, skor: [1, 2, 3, 5, 4], bahas: "Hoaks provokatif harus dihentikan penyebarannya." },
  { id: "tkp-rad-004", topik: "TKP Anti Radikalisme", level: 2, q: "Dalam sebuah ceramah, pembicara menyalahkan dan merendahkan kelompok lain. Anda...", opts: ["Meninggalkan forum dengan tenang dan menyampaikan keberatan kepada panitia bila perlu", "Bertepuk tangan dan mendukung isi ceramah agar dianggap sepaham dengan jamaah yang lain", "Mencatat isi ceramah yang bermasalah lalu menyampaikannya kepada panitia dengan sopan setelah acara", "Tetap duduk sampai selesai agar tidak menarik perhatian dan membuat suasana menjadi canggung", "Berdebat dengan pembicara di tempat itu juga dengan nada emosional di depan para peserta"], ans: 0, skor: [5, 1, 4, 3, 2], bahas: "Tidak mendukung narasi intoleran, namun tetap menjaga ketertiban." },
  { id: "tkp-rad-005", topik: "TKP Anti Radikalisme", level: 2, q: "Rekan menyebar hoaks politik yang bisa memicu kerusuhan. Anda...", opts: ["Membalas dengan sindiran di kolom komentar agar rekan merasa malu atas unggahannya", "Menunjukkan sumber yang benar, meminta menghapusnya, dan melapor bila tidak diindahkan", "Mengajak rekan memeriksa sumber berita itu bersama lalu menyarankan meluruskan unggahannya", "Ikut membagikannya karena isinya sejalan dengan pendapat politik yang Anda yakini sesuai kebiasaan yang selama ini Anda jalani", "Membiarkannya karena Anda tidak ingin terlibat dalam urusan politik di tempat kerja"], ans: 1, skor: [2, 5, 4, 1, 3], bahas: "Literasi digital dan tanggung jawab sosial." },
  { id: "tkp-rad-006", topik: "TKP Anti Radikalisme", level: 3, q: "Seorang teman dekat Anda makin tertutup, intoleran, dan menjauhi keluarganya. Anda...", opts: ["Mendekatinya dengan empati, mengajaknya berdialog dengan tokoh yang dipercaya, dan melapor bila membahayakan", "Mengejek keyakinan barunya di depan teman-teman agar ia malu dan kembali seperti semula tanpa memikirkan akibat jangka panjangnya", "Mengamati perkembangannya dari jauh karena Anda tidak ingin ikut campur dalam urusan pribadinya", "Menjauhinya sementara supaya Anda sendiri tidak ikut terpengaruh oleh pandangannya yang berubah", "Mengajak teman itu berbicara dari hati ke hati dan menawarkan menemaninya menemui konselor atau tokoh agama"], ans: 0, skor: [5, 1, 3, 2, 4], bahas: "Pendekatan humanis dan peduli sambil tetap waspada." },
  { id: "tkp-rad-007", topik: "TKP Anti Radikalisme", level: 2, q: "Anda menemukan poster ajakan makar terhadap pemerintah yang sah di lingkungan Anda. Anda...", opts: ["Memotret poster itu dari jauh lalu melaporkannya kepada ketua lingkungan dan aparat setempat", "Memfoto poster dan membagikannya di media sosial agar semua orang membicarakannya", "Mendokumentasikannya dan melaporkannya kepada aparat berwenang", "Menanyakan kepada warga sekitar siapa pemasangnya lalu menegur orang yang dicurigai", "Merusak poster itu diam-diam agar tidak dibaca warga tanpa melapor kepada siapa pun"], ans: 2, skor: [4, 1, 5, 2, 3], bahas: "Laporkan kepada yang berwenang, jangan main hakim sendiri." },
  { id: "tkp-rad-008", topik: "TKP Anti Radikalisme", level: 2, q: "Diskusi di kantor memanas membahas ideologi tertentu. Anda...", opts: ["Menengahi, mengingatkan bahwa Pancasila dasar bersama, dan mengarahkan diskusi ke hal konstruktif", "Mengusulkan agar pembahasan dihentikan dulu lalu dilanjutkan dalam forum yang dipandu secara tertib", "Mengompori suasana dengan menambah pernyataan keras agar perdebatan menjadi semakin seru meskipun belum yakin dampaknya bagi orang lain", "Memihak satu sisi yang paling sesuai dengan pendapat Anda dan membantunya menekan pihak lain", "Meninggalkan ruangan agar tidak terseret perdebatan yang tampaknya tidak akan ada ujungnya"], ans: 0, skor: [5, 4, 1, 2, 3], bahas: "Menjaga forum tetap sehat dan berdasarkan persatuan." },
  { id: "tkp-rad-009", topik: "TKP Anti Radikalisme", level: 1, q: "Seorang rekan menganggap upacara bendera tidak perlu. Anda...", opts: ["Melaporkan rekan itu sebagai orang yang berpaham radikal kepada atasan tanpa berbicara dulu", "Mengabaikan pendapat itu karena menurut Anda tiap orang berhak berpikir seperti itu", "Mengajak rekan itu mengikuti upacara sambil menceritakan pengalaman Anda tentang makna kebersamaannya", "Menyetujui pendapat itu dan ikut tidak hadir pada upacara berikutnya bersama rekan tersebut, sebab Anda merasa tidak ada pilihan lain", "Menjelaskan makna upacara sebagai penghormatan kepada perjuangan bangsa dan mengajaknya mengikuti dengan khidmat"], ans: 4, skor: [2, 3, 4, 1, 5], bahas: "Edukasi nilai kebangsaan lebih efektif daripada menghakimi." },
  { id: "tkp-rad-010", topik: "TKP Anti Radikalisme", level: 2, q: "Media sosial terus merekomendasikan konten bernuansa radikal kepada Anda. Anda...", opts: ["Membiarkan algoritma bekerja karena menurut Anda tidak berbahaya selama tidak ikut membagikannya", "Mengatur ulang preferensi akun dan menghapus riwayat tontonan agar rekomendasi tidak lagi menampilkan konten itu", "Membagikan konten itu kepada teman agar mereka juga tahu apa yang sedang beredar tanpa berkonsultasi dengan siapa pun lebih dulu", "Menonton konten itu sampai selesai untuk mengetahui apa yang sebenarnya mereka sampaikan", "Menandai konten sebagai tidak relevan, melaporkannya, dan mengikuti sumber informasi yang kredibel"], ans: 4, skor: [3, 4, 1, 2, 5], bahas: "Kendalikan konsumsi informasi digital." },
  { id: "tkp-rad-011", topik: "TKP Anti Radikalisme", level: 1, q: "Tetangga dikucilkan karena berbeda keyakinan. Anda...", opts: ["Tidak ikut mengucilkan tetapi juga tidak berbuat apa-apa karena khawatir dijauhi warga lain", "Tetap menyapa dan bergaul baik, serta mengajak warga lain menghormati perbedaan", "Membicarakannya di grup warga untuk mencari tahu bagaimana pandangan warga lain terhadap tetangga itu", "Mengundang tetangga itu dalam kegiatan lingkungan dan memastikan ia diperlakukan sama dengan warga lain", "Ikut menjauhinya agar tidak berbeda sikap dari tetangga lain di lingkungan ini"], ans: 1, skor: [3, 5, 2, 4, 1], bahas: "Toleransi diwujudkan dalam sikap sehari-hari." },
  { id: "tkp-rad-012", topik: "TKP Anti Radikalisme", level: 2, q: "Sebuah lembaga tak jelas mengajak Anda berdonasi untuk perjuangan tertentu. Anda...", opts: ["Langsung berdonasi besar karena merasa perjuangan itu patut didukung bersama sesuai kebiasaan yang selama ini Anda jalani", "Menanyakan peruntukan dana secara rinci dan meminta bukti legalitas lembaga sebelum memutuskan", "Berdonasi dalam jumlah kecil saja karena tidak ingin dianggap pelit oleh pengajak", "Menelusuri legalitas lembaga itu, menolak berdonasi bila tidak jelas, dan melapor bila mencurigakan", "Membagikan ajakan donasi itu kepada teman karena tampaknya tujuannya mulia"], ans: 3, skor: [1, 4, 3, 5, 2], bahas: "Waspada terhadap pendanaan kelompok ekstrem." },
  { id: "tkp-rad-013", topik: "TKP Anti Radikalisme", level: 3, q: "Anak muda di lingkungan Anda mulai terpengaruh paham ekstrem. Anda...", opts: ["Memukul yang membandel agar jera dan tidak lagi terpengaruh paham seperti itu meskipun belum yakin dampaknya bagi orang lain", "Menginisiasi kegiatan positif bersama tokoh masyarakat dan pemuda, dan berkoordinasi dengan aparat bila diperlukan", "Mengajak para pemuda itu terlibat dalam kegiatan olahraga dan kerja sosial yang membangun rasa kebangsaan", "Menyalahkan orang tua mereka karena dianggap lalai mengawasi anak-anaknya sendiri", "Menjauhkan mereka dari lingkungan dengan melarang anak Anda bergaul dengan kelompok itu"], ans: 1, skor: [1, 5, 4, 2, 3], bahas: "Pencegahan lewat kegiatan positif dan kolaborasi." },
  { id: "tkp-rad-014", topik: "TKP Anti Radikalisme", level: 1, q: "Rekan Anda menghina lambang negara. Anda...", opts: ["Mengingatkan bahwa lambang negara wajib dihormati dan menjelaskan konsekuensinya", "Merekam ucapan itu untuk dipermalukan di media sosial agar rekan itu mendapat pelajaran", "Diam karena tidak ingin terjadi perdebatan yang bisa merusak hubungan baik di tempat kerja", "Ikut tertawa karena rekan lain juga tertawa dan Anda tidak ingin dianggap terlalu serius", "Menegur dengan sopan dan menawarkan menjelaskan makna lambang negara yang dihina itu"], ans: 0, skor: [5, 1, 3, 2, 4], bahas: "Menghormati lambang negara adalah kewajiban warga negara." },
  { id: "tkp-rad-015", topik: "TKP Anti Radikalisme", level: 3, q: "Teman mengajak Anda merusak fasilitas umum untuk membalas sebuah peristiwa. Anda...", opts: ["Ikut berkumpul tetapi tidak merusak apa pun agar tetap menjaga pertemanan dengan kelompok itu", "Pulang tanpa berbuat apa-apa karena tidak ingin terlibat urusan yang berbahaya bagi diri sendiri", "Menolak, mengajak menyalurkan aspirasi secara damai sesuai hukum, dan mencegah tindakan anarkis", "Menolak ikut dan menyarankan teman menyampaikan aspirasi lewat surat atau perwakilan yang resmi", "Ikut merusak bersama mereka karena merasa solidaritas lebih penting daripada risikonya sesuai kebiasaan yang selama ini Anda jalani"], ans: 2, skor: [2, 3, 5, 4, 1], bahas: "Aspirasi disampaikan damai dan berdasarkan hukum." },
  { id: "tkp-rad-016", topik: "TKP Anti Radikalisme", level: 2, q: "Tokoh yang Anda kagumi ternyata sering menyebarkan paham yang merendahkan kelompok lain. Anda...", opts: ["Berhenti mengikuti dan membagikan kontennya lalu mencari tokoh lain yang mengajarkan persatuan", "Menutup mata atas pandangannya karena Anda sudah lama mengaguminya dan merasa banyak manfaat", "Membela tokoh itu di media sosial dan menyerang siapa pun yang mengkritiknya, karena menurut Anda itu cara yang paling praktis", "Mengkritisi pandangannya yang bertentangan dengan Pancasila dan berhenti menyebarkan kontennya", "Tetap mengaguminya tetapi memilah hanya bagian ajarannya yang menurut Anda masih baik"], ans: 3, skor: [4, 2, 1, 5, 3], bahas: "Kagum tidak berarti membenarkan intoleransi." },
  { id: "tkp-rad-017", topik: "TKP Anti Radikalisme", level: 1, q: "Grup keluarga sering membagikan teori konspirasi yang memecah belah. Anda...", opts: ["Marah-marah di grup sampai suasana keluarga menjadi tegang dan saling menyalahkan", "Membalas dengan teori konspirasi lain agar pembahasan menjadi seimbang menurut Anda tanpa berkonsultasi dengan siapa pun lebih dulu", "Meninggalkan grup tanpa sepatah kata karena Anda lelah dengan pesan-pesan seperti itu", "Memberi tahu dengan sopan bahwa informasi itu belum terbukti dan membagikan sumber yang kredibel", "Menyampaikan lewat pesan pribadi kepada pengirim bahwa isinya belum diverifikasi dan menyarankan memeriksanya dulu"], ans: 3, skor: [2, 1, 3, 5, 4], bahas: "Luruskan informasi dengan santun." },
  { id: "tkp-rad-018", topik: "TKP Anti Radikalisme", level: 2, q: "Anda diminta menandatangani petisi yang menolak keberagaman di lingkungan Anda. Anda...", opts: ["Menolak dan menjelaskan bahwa keberagaman dilindungi konstitusi dan menjadi kekuatan bangsa", "Menyebarkan petisi itu kepada kenalan Anda agar semakin banyak yang ikut mendukungnya tanpa memikirkan akibat jangka panjangnya", "Menandatangani karena tidak ingin dimusuhi tetangga yang sudah lebih dulu mendukungnya", "Menolak menandatangani dan mengajak warga berdiskusi tentang manfaat hidup berdampingan secara damai", "Menyobek petisi itu di depan umum agar semua orang tahu penolakan Anda"], ans: 0, skor: [5, 1, 3, 4, 2], bahas: "Tegas pada nilai kebangsaan, santun dalam sikap." },
  { id: "tkp-rad-019", topik: "TKP Anti Radikalisme", level: 1, q: "Teman membuat meme yang mengejek agama tertentu. Anda...", opts: ["Mengabaikannya karena hanya meme dan tidak ada yang benar-benar menganggapnya serius", "Menertawakan dan menyebarkan meme itu karena dianggap lucu oleh teman-teman lain tanpa memikirkan akibat jangka panjangnya", "Meminta teman itu menghapus meme tersebut dan menjelaskan bahwa ejekan agama dapat memicu perpecahan", "Membuat meme balasan yang mengejek agama teman itu agar ia merasakan hal yang sama", "Menegur bahwa itu menyakiti orang lain dan meminta menghapusnya, lalu mengajak membuat konten yang membangun"], ans: 4, skor: [3, 1, 4, 2, 5], bahas: "Hentikan ejekan SARA." },
  { id: "tkp-rad-020", topik: "TKP Anti Radikalisme", level: 3, q: "Kelompok mahasiswa mengajak aksi dengan kekerasan. Anda...", opts: ["Menonton dari jauh sambil berharap aksi berjalan tanpa korban dan tanpa melibatkan Anda", "Membawa peralatan untuk berjaga-jaga dan siap membalas bila ada pihak yang menyerang, karena menurut Anda itu cara yang paling praktis", "Menolak ikut dan mengajak teman-teman menyusun tuntutan secara tertulis untuk disampaikan lewat jalur resmi", "Menolak dan mengajak menyalurkan aspirasi secara damai, serta melapor bila ada rencana kekerasan", "Ikut berbaris di barisan belakang agar tidak dianggap tidak solid oleh teman kelompok"], ans: 3, skor: [3, 1, 4, 5, 2], bahas: "Aspirasi damai, tolak kekerasan." },
  { id: "tkp-rad-021", topik: "TKP Anti Radikalisme", level: 3, q: "Anda melihat tetangga menyimpan atribut kelompok terlarang. Anda...", opts: ["Merusak atribut itu saat tetangga tidak berada di rumah supaya tidak ada yang melihatnya sesuai kebiasaan yang selama ini Anda jalani", "Membiarkannya karena belum tentu tetangga itu menjadi bagian dari kelompok terlarang tersebut", "Tidak menggunjing, mengumpulkan informasi seperlunya, dan melapor kepada RT atau aparat berwenang", "Menyebarkannya kepada warga di grup agar semua berhati-hati terhadap tetangga itu", "Memberi tahu ketua lingkungan secara tertutup agar dapat diteruskan kepada aparat yang berwenang"], ans: 2, skor: [1, 3, 5, 2, 4], bahas: "Lapor kepada yang berwenang, bukan main hakim sendiri." },
  { id: "tkp-rad-022", topik: "TKP Anti Radikalisme", level: 2, q: "Anda menerima brosur yang mengajak mendirikan sistem negara yang bertentangan dengan dasar negara. Anda...", opts: ["Tidak menyebarkannya dan melaporkannya kepada pihak berwenang", "Membagikannya kepada teman agar mereka juga mengetahui adanya pandangan seperti itu", "Menyimpan brosur itu sebagai barang bukti lalu menyerahkannya kepada aparat yang berwenang", "Menyimpannya untuk dibaca-baca karena penasaran dengan isi gagasan yang ditawarkannya", "Membuangnya ke tempat sampah tanpa membahasnya dengan siapa pun agar tidak dibaca orang lain"], ans: 0, skor: [5, 1, 4, 2, 3], bahas: "Jangan menyebarkan propaganda; laporkan." },
  { id: "tkp-rad-023", topik: "TKP Anti Radikalisme", level: 3, q: "Teman berkata hukum negara tidak perlu dipatuhi karena tidak sesuai keyakinannya. Anda...", opts: ["Menyetujui pendapat itu agar teman tidak merasa terasing dan tetap mau berteman dengan Anda tanpa memikirkan akibat jangka panjangnya", "Menghindari pembicaraan itu karena tidak ingin berdebat soal keyakinan dengan teman dekat", "Mengajak teman berdiskusi tentang cara mengubah aturan melalui jalur konstitusional yang tersedia", "Menjelaskan bahwa hukum berlaku bagi semua warga dan perbedaan pandangan disalurkan lewat cara yang sah", "Mengejek keyakinan teman itu agar ia merasa malu dan menarik ucapannya"], ans: 3, skor: [1, 3, 4, 5, 2], bahas: "Taat hukum, salurkan aspirasi lewat jalur sah." },
  { id: "tkp-rad-024", topik: "TKP Anti Radikalisme", level: 2, q: "Anda diminta menghapus unggahan tentang toleransi karena dianggap mengganggu. Anda...", opts: ["Menyampaikan kepada pihak yang meminta bahwa unggahan itu tidak melanggar aturan dan mengajak berdiskusi", "Menutup akun media sosial Anda agar tidak lagi diganggu oleh orang-orang yang berkeberatan", "Menghapus unggahan itu agar tidak terjadi keributan lalu membuat unggahan baru dengan bahasa yang lebih halus", "Membalas dengan unggahan yang menyerang pihak yang meminta penghapusan unggahan toleransi itu", "Mempertahankannya selama tidak melanggar aturan, dan menjelaskan maksud baiknya dengan tenang"], ans: 4, skor: [4, 2, 3, 1, 5], bahas: "Konsisten menyuarakan toleransi dengan cara damai." },
  { id: "tkp-rad-025", topik: "TKP Anti Radikalisme", level: 1, q: "Sebagian warga memprotes peringatan hari besar nasional di lingkungan. Anda...", opts: ["Menjelaskan makna peringatan sebagai penghormatan perjuangan bangsa dan mengajak warga berpartisipasi", "Mengajak pemrotes berdialog dengan panitia agar kekhawatiran mereka dapat dibahas bersama secara baik", "Membubarkan acara agar tidak ada warga yang merasa terganggu oleh peringatan tersebut", "Mengabaikan protes itu karena peringatan tetap akan berlangsung sesuai rencana panitia", "Menghina para pemrotes di depan warga agar mereka tidak berani memprotes lagi tanpa memikirkan akibat jangka panjangnya"], ans: 0, skor: [5, 4, 2, 3, 1], bahas: "Edukasi nilai kebangsaan." },
  { id: "tkp-rad-026", topik: "TKP Anti Radikalisme", level: 3, q: "Bendera simbol kelompok ekstrem berkibar di sebuah acara umum. Anda...", opts: ["Menjauh dengan aman, mendokumentasikan, dan melaporkannya kepada aparat", "Membiarkannya karena tidak ingin terlibat bila terjadi keributan di tengah keramaian", "Memotret untuk kenang-kenangan dan membagikannya kepada teman tanpa melaporkan", "Merobek paksa bendera itu sendiri meskipun situasi bisa memicu kekerasan", "Memberi tahu panitia dan petugas keamanan acara dari jarak aman tanpa membuat keributan"], ans: 0, skor: [5, 3, 2, 1, 4], bahas: "Utamakan keselamatan dan laporkan." },
  { id: "tkp-rad-027", topik: "TKP Anti Radikalisme", level: 2, q: "Teman meminta Anda berdonasi untuk jihad tanpa penjelasan jelas. Anda...", opts: ["Berdonasi sedikit karena tidak enak menolak permintaan teman dekat", "Mengancam teman itu agar tidak lagi meminta donasi kepada siapa pun dan menganggap persoalannya selesai begitu saja", "Menolak berdonasi sebelum ada kejelasan lembaga dan penggunaan dana yang dapat diperiksa", "Menanyakan lembaga, peruntukan, dan legalitasnya; menolak bila tidak jelas serta melapor bila mencurigakan", "Mengajak teman lain berdonasi juga agar jumlah donasi terkumpul semakin banyak"], ans: 3, skor: [3, 1, 4, 5, 2], bahas: "Waspadai aliran dana yang tidak jelas." },
  { id: "tkp-rad-028", topik: "TKP Anti Radikalisme", level: 3, q: "Sebagai guru, Anda membaca esai murid yang bernada kebencian ekstrem terhadap kelompok tertentu. Anda...", opts: ["Mengajak murid berdiskusi tentang pandangannya dan memperkenalkan nilai persatuan dengan contoh yang mudah dipahami", "Menunjukkan esai itu kepada guru lain sebagai bahan bercanda tentang pandangan muridnya", "Memberi nilai seperti biasa tanpa komentar karena Anda tidak ingin menimbulkan masalah dengan orang tua", "Berbicara pribadi dengan murid, mengenali sumber pengaruhnya, melibatkan orang tua dan sekolah, serta mengarahkan ke pemahaman yang sehat", "Menghukum murid itu di depan kelas supaya teman-temannya tidak meniru pandangan yang sama dan menganggap persoalannya selesai begitu saja"], ans: 3, skor: [4, 1, 3, 5, 2], bahas: "Pendekatan pembinaan dan kolaborasi." },
  { id: "tkp-rad-029", topik: "TKP Anti Radikalisme", level: 3, q: "Sekelompok anak muda berlatih semi-militer secara tertutup di lingkungan Anda. Anda...", opts: ["Mencari tahu dengan wajar tujuan kegiatannya lewat ketua lingkungan, dan melapor ke aparat bila ada indikasi membahayakan", "Mengamati dengan wajar dan mencatat hal yang mencurigakan lalu menyampaikannya kepada aparat setempat", "Mendatangi mereka dengan marah dan melarang kegiatan itu tanpa mengetahui tujuan sebenarnya", "Menyebarkan prasangka tentang mereka di media sosial agar warga lain ikut waspada sesuai kebiasaan yang selama ini Anda jalani", "Mengabaikan kegiatan itu karena belum tentu berhubungan dengan hal yang membahayakan masyarakat"], ans: 0, skor: [5, 4, 2, 1, 3], bahas: "Cari informasi yang benar dan laporkan jika perlu." },
  { id: "tkp-rad-030", topik: "TKP Anti Radikalisme", level: 2, q: "Anda diminta berkomentar pada polemik bernuansa SARA yang sedang ramai di media sosial. Anda...", opts: ["Membuat akun samaran untuk menyerang pihak yang berseberangan dengan pendapat Anda", "Memilih tidak berkomentar dan tidak membagikan konten polemik itu agar tidak menambah ketegangan", "Meneruskan unggahan provokatif itu karena banyak orang lain juga membagikannya tanpa berkonsultasi dengan siapa pun lebih dulu", "Tidak ikut memanaskan; bila berkomentar, menyampaikan ajakan menjaga persatuan dengan data yang benar", "Berkomentar singkat mendukung pihak yang Anda anggap benar tanpa memeriksa kebenaran kabarnya"], ans: 3, skor: [2, 4, 1, 5, 3], bahas: "Bijak bermedia sosial." },
  { id: "tkp-rad-031", topik: "TKP Anti Radikalisme", level: 1, q: "Teman mengajak Anda ikut pengajian tertutup yang melarang bergaul dengan pemeluk agama lain. Anda...", opts: ["Menolak dengan sopan, menjelaskan bahwa Anda menghargai pergaulan lintas agama, dan menyarankan teman berhati-hati", "Mengajak teman-teman lain ikut agar kelompok itu lebih ramai dan semakin kuat meskipun belum yakin dampaknya bagi orang lain", "Menanyakan lebih dulu isi pengajian itu kepada tokoh agama yang Anda percaya sebelum memutuskan", "Datang sekali untuk melihat sendiri dan memutuskan sesudahnya tanpa memberi tahu siapa pun", "Menerima ajakan karena tidak enak menolak dan tidak ingin kehilangan teman dekat"], ans: 0, skor: [5, 1, 4, 3, 2], bahas: "Jaga pergaulan lintas agama dan waspada pada ajakan eksklusif." },
  { id: "tkp-rad-032", topik: "TKP Anti Radikalisme", level: 2, q: "Anda melihat grafiti ajakan kebencian di fasilitas umum. Anda...", opts: ["Menambahkan coretan tandingan di dinding yang sama agar pesannya tertutup", "Mendokumentasikannya dan melaporkannya kepada pihak pengelola atau aparat", "Melaporkan lokasi dan isi grafiti itu kepada petugas kebersihan atau pengelola fasilitas umum", "Membiarkannya karena Anda yakin akan segera dibersihkan oleh petugas tanpa perlu dilaporkan", "Memotretnya dan membagikannya dengan komentar yang menyerang kelompok yang dituduh"], ans: 1, skor: [2, 5, 4, 3, 1], bahas: "Laporkan agar segera ditangani." },
  { id: "tkp-rad-033", topik: "TKP Anti Radikalisme", level: 2, q: "Rekan mengunggah kutipan yang memuji aksi kekerasan. Anda...", opts: ["Membiarkannya karena rekan itu mungkin hanya sedang emosi dan akan menghapusnya sendiri", "Mengingatkan bahwa kekerasan tidak dapat dibenarkan dan meminta rekan menghapusnya", "Membahas unggahan itu secara pribadi dan menjelaskan bahaya memuji kekerasan terhadap orang lain", "Menyebarkan tangkapan layar unggahan itu untuk mempermalukannya di depan rekan lain", "Memberi tanda suka agar rekan itu tidak merasa sendirian dengan pendapatnya"], ans: 1, skor: [3, 5, 4, 1, 2], bahas: "Tolak pembenaran kekerasan." },
  { id: "tkp-rad-034", topik: "TKP Anti Radikalisme", level: 3, q: "Seorang remaja kerabat Anda terpikat narasi ekstrem di gim daring. Anda...", opts: ["Menyita gawai remaja itu dan melarangnya bermain gim tanpa membicarakan penyebabnya", "Memarahinya di depan keluarga besar agar ia malu dan berhenti dengan sendirinya meskipun belum yakin dampaknya bagi orang lain", "Mendengarkan tanpa menghakimi, memberi pemahaman yang sehat, melibatkan orang tua, dan melapor bila ada ajakan berbahaya", "Mengajak remaja itu melakukan kegiatan bersama dan membatasi akses ke kelompok yang memengaruhinya secara bertahap", "Menganggapnya fase biasa pada remaja dan membiarkannya selama nilai sekolahnya tidak turun"], ans: 2, skor: [3, 1, 5, 4, 2], bahas: "Dampingi remaja dengan empati dan kewaspadaan." },
  { id: "tkp-rad-035", topik: "TKP Anti Radikalisme", level: 2, q: "Anda diundang diskusi daring yang menyalahkan satu kelompok atas masalah negara. Anda...", opts: ["Mengundang lebih banyak orang agar kelompok yang disalahkan itu semakin ditekan meskipun belum yakin dampaknya bagi orang lain", "Bergabung tetapi hanya diam supaya tidak terlibat perdebatan sengit di dalamnya", "Mengikuti diskusi untuk mendengarkan dan meluruskan informasi yang keliru dengan sopan bila diizinkan", "Ikut menyalahkan kelompok itu karena banyak peserta lain yang berpendapat sama", "Menolak bergabung bila diskusi menyalahkan kelompok dan menawarkan diskusi berbasis data dan solusi"], ans: 4, skor: [1, 3, 4, 2, 5], bahas: "Hindari narasi menyalahkan kelompok." },
  { id: "tkp-rad-036", topik: "TKP Anti Radikalisme", level: 3, q: "Anda diminta menyebarkan video propaganda kelompok tertentu. Anda...", opts: ["Menonton sampai habis untuk menilai isinya lalu memutuskan sendiri apakah akan diteruskan", "Menyebarkan secara luas karena merasa pesan di dalamnya penting diketahui semua orang meskipun belum yakin dampaknya bagi orang lain", "Menolak dan menyarankan pengirim tidak menyebarkannya karena dapat melanggar hukum dan memecah belah", "Menolak menyebarkannya, tidak menontonnya lebih jauh, dan melaporkan sumbernya kepada pihak berwenang", "Menyebarkan ke kelompok tertutup saja agar tidak diketahui banyak orang"], ans: 3, skor: [3, 1, 4, 5, 2], bahas: "Jangan menjadi penyebar propaganda." },
  { id: "tkp-rad-037", topik: "TKP Anti Radikalisme", level: 3, q: "Warga menolak pendirian rumah ibadah kelompok minoritas yang sudah memenuhi aturan. Anda...", opts: ["Mendukung penolakan warga karena jumlah warga yang menolak jauh lebih banyak", "Menyarankan kelompok minoritas mencari lokasi lain agar tidak menimbulkan keributan", "Mengajak pengurus lingkungan dan tokoh lintas agama membahas keberatan warga secara terbuka dan tertib", "Memfasilitasi dialog dengan tokoh agama dan warga, menjelaskan aturan yang berlaku, dan menjamin hak beribadah", "Mengompori warga agar menolak lebih keras supaya rencana itu dibatalkan tanpa memikirkan akibat jangka panjangnya"], ans: 3, skor: [2, 3, 4, 5, 1], bahas: "Hak beribadah dijamin dan dibahas lewat dialog." },
  { id: "tkp-rad-038", topik: "TKP Anti Radikalisme", level: 2, q: "Kegiatan kerohanian di kantor mendiskreditkan agama lain. Anda...", opts: ["Tidak menghadiri kegiatan berikutnya tanpa menyampaikan alasan kepada siapa pun", "Mencatat bagian yang bermasalah lalu menyampaikannya kepada atasan agar kegiatan berikutnya diperbaiki", "Ikut mengaminkan isi materi itu agar tidak dianggap tidak sepaham dengan rekan lain", "Menyebarkan kekecewaan Anda kepada rekan dari agama lain agar mereka ikut marah dan menganggap persoalannya selesai begitu saja", "Menyampaikan keberatan dengan sopan kepada penyelenggara dan mengusulkan materi yang menjaga toleransi"], ans: 4, skor: [3, 4, 2, 1, 5], bahas: "Kegiatan kerohanian harus menjaga toleransi." },
  { id: "tkp-rad-039", topik: "TKP Anti Radikalisme", level: 1, q: "Anda melihat ujaran kebencian di kolom komentar sebuah berita. Anda...", opts: ["Melaporkan komentar yang melanggar kepada pengelola platform lalu melanjutkan membaca berita", "Tidak ikut menanggapi dengan kebencian, melaporkan komentar itu, dan menulis komentar yang menyejukkan bila perlu", "Membalas dengan komentar yang lebih keras supaya pelaku ujaran kebencian merasa takut", "Memberi tanda suka pada komentar itu karena Anda setuju dengan isinya dan menganggap persoalannya selesai begitu saja", "Membaca saja tanpa menanggapi karena tidak ingin terlibat debat dengan orang tak dikenal"], ans: 1, skor: [4, 5, 2, 1, 3], bahas: "Jangan ikut menyuburkan ujaran kebencian." },
  { id: "tkp-rad-040", topik: "TKP Anti Radikalisme", level: 2, q: "Seorang tokoh masyarakat menyebut warga tertentu bukan bagian dari bangsa. Anda...", opts: ["Mengingatkan tokoh itu secara pribadi bahwa pernyataan tersebut melukai warga dan bertentangan dengan konstitusi", "Menegaskan dengan santun bahwa semua warga adalah bagian dari bangsa dan melapor bila ada ujaran diskriminatif", "Diam karena tokoh itu dihormati dan Anda tidak ingin dianggap tidak sopan kepadanya", "Menyetujui pernyataan itu karena tidak ingin berbeda pendapat dengan tokoh masyarakat", "Menyebarkan pernyataan itu agar warga lain mengetahui siapa saja yang dianggap bukan bagian bangsa"], ans: 1, skor: [4, 5, 3, 2, 1], bahas: "Persatuan menolak diskriminasi." },
  { id: "tkp-rad-041", topik: "TKP Anti Radikalisme", level: 3, q: "Anda diminta menyumbang untuk kelompok yang mendukung pemisahan wilayah dari negara. Anda...", opts: ["Menolak menyumbang, menjelaskan pentingnya keutuhan NKRI, dan melaporkan penggalangan dana itu kepada aparat", "Berjanji akan menyumbang nanti tetapi tidak benar-benar melakukannya agar tidak berdebat", "Menolak dengan tegas lalu mencari informasi tentang kelompok itu sebelum menyampaikannya kepada pihak berwenang", "Menyumbang dalam jumlah sangat kecil agar pengajak tidak kecewa dan tidak memaksa terus", "Menyumbang besar karena percaya kelompok itu memperjuangkan keadilan bagi daerahnya meskipun belum yakin dampaknya bagi orang lain"], ans: 0, skor: [5, 2, 4, 3, 1], bahas: "Keutuhan NKRI dijaga dan penggalangan dana dilaporkan." },
  { id: "tkp-rad-042", topik: "TKP Anti Radikalisme", level: 2, q: "Seorang teman mengkritik pemerintah dengan fakta lalu diserang pendukung fanatik. Anda...", opts: ["Mengingatkan para penyerang agar mengkritik gagasan, bukan menyerang pribadi, dengan bahasa sopan", "Membela hak teman menyampaikan kritik secara santun, dan mengajak semua pihak berdiskusi dengan data", "Menonton saja karena itu perdebatan di media sosial yang tidak ada ujungnya", "Ikut menyerang teman itu agar tidak dianggap membela pihak yang salah", "Meminta teman itu menghapus kritiknya supaya tidak terjadi keributan berkepanjangan dan menganggap persoalannya selesai begitu saja"], ans: 1, skor: [4, 5, 3, 2, 1], bahas: "Kritik santun dilindungi; serangan pribadi ditolak." },
  { id: "tkp-rad-043", topik: "TKP Anti Radikalisme", level: 2, q: "Anda menemukan akun yang menyebar hoaks bencana yang membuat warga panik. Anda...", opts: ["Memverifikasi ke sumber resmi, melaporkan akun itu, dan membagikan informasi yang benar", "Menghapus kontak semua teman yang membagikannya tanpa menjelaskan alasannya, agar urusannya cepat selesai menurut perhitungan Anda", "Membuat unggahan klarifikasi dengan tautan ke informasi resmi agar warga tidak panik", "Membiarkannya karena Anda yakin warga akan memeriksa kebenarannya sendiri", "Ikut menyebarkan agar warga lebih waspada walaupun belum pasti kebenarannya"], ans: 0, skor: [5, 1, 4, 3, 2], bahas: "Hoaks bencana membahayakan; luruskan dengan sumber resmi." },
  { id: "tkp-rad-044", topik: "TKP Anti Radikalisme", level: 1, q: "Rekan menolak menyanyikan lagu kebangsaan saat upacara. Anda...", opts: ["Diam saja karena tiap orang punya cara sendiri menunjukkan sikapnya", "Melaporkan rekan itu kepada atasan sebagai pelanggar tanpa mencoba menanyakan alasannya", "Berbicara dengan rekan itu secara pribadi setelah upacara dan menjelaskan pentingnya penghormatan", "Mengejek rekan itu di depan peserta lain agar ia merasa malu dan mau ikut menyanyi sesuai kebiasaan yang selama ini Anda jalani", "Menanyakan alasannya dengan baik, mengingatkan makna menghormati lagu kebangsaan, dan mengajaknya ikut khidmat"], ans: 4, skor: [3, 2, 4, 1, 5], bahas: "Hormati lagu kebangsaan dengan edukasi, bukan penghakiman." },
  { id: "tkp-rad-045", topik: "TKP Anti Radikalisme", level: 2, q: "Anda membaca tulisan yang menyebut demokrasi haram dan mengajak tidak ikut pemilu. Anda...", opts: ["Membagikannya agar orang lain bisa menilai sendiri isinya tanpa ada pendapat Anda", "Membiarkannya karena itu hanya tulisan pribadi yang tidak akan banyak dibaca orang", "Tidak menyebarkannya, memeriksa dasar klaimnya, dan menjelaskan pentingnya partisipasi dalam pemilu", "Mengajak teman membahas tulisan itu dengan merujuk pada sumber yang kredibel dan beragam", "Menyetujuinya dan mengajak keluarga tidak memilih pada pemilu berikutnya, sebab Anda yakin tidak akan ada yang mempermasalahkannya"], ans: 2, skor: [2, 3, 5, 4, 1], bahas: "Partisipasi dalam demokrasi adalah hak dan kewajiban warga." },
  { id: "tkp-rad-046", topik: "TKP Anti Radikalisme", level: 3, q: "Kelompok pemuda hendak menyegel rumah ibadah kelompok lain. Anda...", opts: ["Mencegah dengan damai, memanggil tokoh masyarakat dan aparat, serta mengingatkan bahwa hak beribadah dijamin hukum", "Ikut bergabung karena banyak warga lain mendukung tindakan itu", "Menghubungi aparat setempat segera dan menjauhkan diri dari lokasi agar keselamatan Anda tetap terjaga", "Merekam kejadian dan mengunggahnya dengan komentar yang mendukung aksi tersebut, sebab Anda yakin tidak akan ada yang mempermasalahkannya", "Mengamati dari jauh sambil berharap kelompok itu mengurungkan niatnya sendiri"], ans: 0, skor: [5, 2, 4, 1, 3], bahas: "Cegah tindakan anarkis dan lindungi hak beribadah." },
  { id: "tkp-rad-047", topik: "TKP Anti Radikalisme", level: 2, q: "Teman mengajak Anda membakar bendera negara lain sebagai bentuk protes. Anda...", opts: ["Menolak ikut serta lalu mengingatkan bahwa tindakan itu dapat merugikan hubungan antarbangsa", "Hadir hanya untuk menonton agar tahu apa yang akan terjadi", "Ikut membakar bendera itu karena merasa solidaritas kepada teman-teman perlu ditunjukkan", "Menyiapkan bendera yang akan dibakar agar acaranya berjalan lancar", "Menolak dan mengajak menyampaikan protes dengan cara damai dan sesuai hukum"], ans: 4, skor: [4, 3, 2, 1, 5], bahas: "Protes harus damai dan sesuai hukum." },
  { id: "tkp-rad-048", topik: "TKP Anti Radikalisme", level: 1, q: "Anak tetangga bertanya kepada Anda tentang arti jihad. Anda...", opts: ["Mengajak anak itu bertanya kepada guru agamanya dan menemaninya mencari sumber yang terpercaya", "Mengatakan anak kecil tidak perlu memikirkan hal seperti itu dan meminta ia bermain saja", "Menjawab seadanya berdasarkan pengetahuan Anda tanpa menjelaskan konteksnya", "Menjelaskan dengan bahasa sederhana bahwa jihad bermakna sungguh-sungguh berbuat baik, lalu menyarankannya bertanya kepada guru agama", "Menjelaskan jihad sebagai perang melawan kelompok yang tidak seiman dengan mereka, karena sudah menjadi kebiasaan di unit ini selama ini"], ans: 3, skor: [4, 2, 3, 5, 1], bahas: "Jawab dengan benar dan arahkan ke sumber terpercaya." },
  { id: "tkp-rad-049", topik: "TKP Anti Radikalisme", level: 3, q: "Seorang rekan menyebut pemilu tidak sah dan mengajak tidak mematuhi hasilnya. Anda...", opts: ["Mengajak rekan lain ikut menolak hasil pemilu secara terbuka di media sosial, sebab Anda merasa tidak ada pilihan lain", "Menghindari pembicaraan itu karena politik adalah topik yang sensitif di tempat kerja", "Menyetujui ajakan itu karena Anda juga kecewa terhadap hasil pemilu", "Mengingatkan bahwa sengketa pemilu diselesaikan lewat jalur hukum dan mengajak menghormati hasil yang sah", "Menjelaskan mekanisme penyelesaian sengketa pemilu yang tersedia dan menyarankan rekan menempuh jalur itu"], ans: 3, skor: [1, 3, 2, 5, 4], bahas: "Hormati hasil yang sah dan tempuh jalur hukum." },
  { id: "tkp-rad-050", topik: "TKP Anti Radikalisme", level: 2, q: "Anda diminta menjadi pembicara tentang toleransi bagi remaja. Anda...", opts: ["Mengajak remaja bermain peran tentang menghadapi perbedaan sehingga pesannya lebih mudah dipahami", "Menolak karena merasa belum cukup layak memberi nasihat kepada orang lain", "Menyampaikan materi seadanya tanpa persiapan karena toh topiknya sudah umum", "Menyerahkan tugas itu kepada orang lain tanpa menjelaskan alasan Anda menolak, sebab Anda yakin tidak akan ada yang mempermasalahkannya", "Menyiapkan materi dari sumber resmi, memakai contoh sehari-hari, dan membuka ruang bertanya"], ans: 4, skor: [4, 3, 2, 1, 5], bahas: "Persiapan yang baik membawa nilai kebangsaan." }
];
